*/
/* tslint:disable */
import React, { useState, useRef, useCallback } from 'react';
import { GoogleGenAI } from '@google/genai';
import GIF from 'gif.js';
import JSZip from 'jszip';
import {
  Box,
  Brush,
  ChevronDown,
  ChevronUp,
  Download,
  Film,
  Grid3X3,
  Hand,
  Layers,
  LoaderCircle,
  Minus,
  Music2,
  Palette,
  Pause,
  PenTool,
  Pencil,
  PersonStanding,
  Play,
  Plus,
  RectangleHorizontal,
  RectangleVertical,
  RotateCcw,
  Sparkles,
  Spline,
  Square,
  Trash2,
  Upload,
  UserPlus,
  Video,
  X,
  Check,
  Clapperboard,
  Scissors,
  Text,
  FileAudio,
  Type,
  ArrowRight,
} from 'lucide-react';

const ai = new GoogleGenAI({apiKey: process.env.API_KEY});

// --- TYPE DEFINITIONS ---
interface Character {
  id: string;
  name: string;
  image: string;
  prompt: string;
}

interface Scene {
  id: string;
  script: string;
  keyframeImage: string;
  animationFrames?: string[];
  transition: 'cut' | 'fade' | 'dissolve';
  isAnimating: boolean;
  animationSettings: {
    startFrame: string;
    endFrame: string;
    numFrames: number;
    prompt: string;
  }
}

interface AnimationStyle {
  name: string;
  prompt: string;
  icon: React.ElementType;
  previewImage: string;
}

// --- CONSTANTS ---
const ANIMATION_STYLES: AnimationStyle[] = [
  {
    name: '애니메이션',
    prompt:
      'a vibrant, detailed anime style, with sharp lines, expressive eyes, and dynamic shading, reminiscent of modern Japanese animation.',
    icon: Film,
    previewImage: 'data:image/png;base64,',
  },
  {
    name: '카툰',
    prompt:
      'a friendly, bubbly American cartoon style with soft, rounded shapes, bold outlines, and simple, bright colors.',
    icon: Brush,
    previewImage: 'data:image/png;base64,',
  },
  // Add other styles here...
];

const PHOTOREALISTIC_TO_ANIMATION_SYSTEM_INSTRUCTION =
  "You are a master character designer and animator. Your task is to transform a real-life photo of a person into a specific animation style. Faithfully translate the person's key facial features, expression, and essence into the chosen style. Do not create a caricature unless the style itself is caricatured. The output MUST be a purely visual image and must NOT contain any text, letters, numbers, or characters of any language.";


// --- HELPER FUNCTIONS ---
const fileToGenerativePart = async (file: File) => {
  const base64EncodedData = await new Promise<string>((resolve) => {
    const reader = new FileReader();
    reader.onload = () => resolve((reader.result as string).split(',')[1]);
    reader.readAsDataURL(file);
  });
  return {
    inlineData: {
      data: base64EncodedData,
      mimeType: file.type,
    },
  };
};

const imageToGenerativePart = (base64Data: string, mimeType = 'image/png') => {
  return {
    inlineData: {
      data: base64Data,
      mimeType,
    },
  };
}


// --- MAIN COMPONENT ---
export default function Home() {
  // --- STATE MANAGEMENT ---
  const [characters, setCharacters] = useState<Character[]>([]);
  const [selectedStyle, setSelectedStyle] = useState<AnimationStyle>(ANIMATION_STYLES[0]);
  const [scenario, setScenario] = useState('');
  const [scenes, setScenes] = useState<Scene[]>([]);

  const [isLoading, setIsLoading] = useState(false);
  const [loadingMessage, setLoadingMessage] = useState('');
  const [error, setError] = useState('');

  const [openSections, setOpenSections] = useState({
    character: true,
    style: true,
    scenario: true,
    timeline: true,
    finalize: true,
  });

  const toggleSection = (section: keyof typeof openSections) => {
    setOpenSections(prev => ({ ...prev, [section]: !prev[section] }));
  };

  const fileInputRef = useRef<HTMLInputElement>(null);

  // --- CORE LOGIC FUNCTIONS ---

  const handleAddCharacter = async (file: File) => {
    setIsLoading(true);
    setLoadingMessage('캐릭터 분석 중...');
    setError('');
    try {
      const imagePart = await fileToGenerativePart(file);
      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: {
          parts: [
            imagePart,
            { text: 'Describe this character for an animation prompt. Focus on visual details like hair, clothing, and notable features. Be concise.' },
          ]
        },
      });
      const newCharacter: Character = {
        id: `char_${Date.now()}`,
        name: `캐릭터 ${characters.length + 1}`,
        image: (imagePart.inlineData.data as string),
        prompt: response.text,
      };
      setCharacters(prev => [...prev, newCharacter]);
    } catch (e) {
      setError('캐릭터를 분석하는 데 실패했습니다. 다른 이미지를 시도해 주세요.');
      console.error(e);
    } finally {
      setIsLoading(false);
    }
  };

  const handleSplitScenario = async () => {
    if (!scenario.trim()) {
      setError('시나리오를 입력해주세요.');
      return;
    }
    if (characters.length === 0) {
      setError('캐릭터를 먼저 추가해주세요.');
      return;
    }

    setIsLoading(true);
    setLoadingMessage('AI가 시나리오를 장면으로 나누는 중...');
    setError('');

    try {
      const characterPrompts = characters.map(c => c.prompt).join(', ');
      const systemInstruction = `You are a film director. Split the following script into logical scenes. Each scene should be a short, coherent unit of action or dialogue. Respond with a JSON object with a single key "scenes" which is an array of strings. Each string is a script for one scene. Your response must be ONLY the JSON object. Do not add any commentary.

      Example script: "A wizard walks into a tavern. He orders a drink. Suddenly, a dragon attacks!"
      Example response: { "scenes": ["A wizard walks into a tavern.", "He orders a drink.", "Suddenly, a dragon attacks the tavern!"] }`;

      const response = await ai.models.generateContent({
        model: 'gemini-3-pro-preview',
        contents: `Script: "${scenario}"`,
        config: {
          systemInstruction,
          responseMimeType: 'application/json',
        }
      });

      let jsonText = response.text.replace(/```json|```/g, '').trim();
      const parsed = JSON.parse(jsonText);
      const sceneScripts = parsed.scenes;

      if (!Array.isArray(sceneScripts)) throw new Error('Invalid response format from AI.');

      setLoadingMessage(`장면 ${sceneScripts.length}개 생성 중...`);
      const newScenes: Scene[] = [];
      for (let i = 0; i < sceneScripts.length; i++) {
        setLoadingMessage(`장면 ${i + 1}/${sceneScripts.length}의 대표 이미지 생성 중...`);
        const script = sceneScripts[i];

        const imageResponse = await ai.models.generateContent({
          model: 'gemini-2.5-flash-image',
          contents: {
            parts: [{ text: `Characters: [${characterPrompts}]. Style: [${selectedStyle.prompt}]. Scene: [${script}]. Generate a single keyframe image for this scene.` }]
          }
        });

        const imagePart = imageResponse.candidates[0].content.parts.find(p => p.inlineData);
        if (!imagePart || !imagePart.inlineData) throw new Error(`Failed to generate image for scene ${i+1}`);

        newScenes.push({
          id: `scene_${Date.now()}_${i}`,
          script,
          keyframeImage: imagePart.inlineData.data,
          transition: 'cut',
          isAnimating: false,
          animationSettings: {
            startFrame: imagePart.inlineData.data,
            endFrame: '',
            numFrames: 10,
            prompt: '',
          }
        });
      }
      setScenes(newScenes);

    } catch (e) {
      setError('시나리오를 나누는 데 실패했습니다. 다시 시도해 주세요.');
      console.error(e);
    } finally {
      setIsLoading(false);
    }
  };

  const handleToggleAnimate = (sceneId: string) => {
    setScenes(scenes.map(s => s.id === sceneId ? { ...s, isAnimating: !s.isAnimating } : s));
  };

  const handleAnimationSettingChange = (sceneId: string, field: keyof Scene['animationSettings'], value: any) => {
    setScenes(scenes.map(s => {
      if (s.id === sceneId) {
        return {
          ...s,
          animationSettings: {
            ...s.animationSettings,
            [field]: value
          }
        };
      }
      return s;
    }));
  };

  const handleGenerateAnimationForScene = async (sceneId: string) => {
    const scene = scenes.find(s => s.id === sceneId);
    if (!scene) return;

    const { startFrame, endFrame, numFrames, prompt } = scene.animationSettings;

    if (!startFrame || !endFrame) {
      setError('애니메이션을 만들려면 시작 프레임과 종료 프레임이 모두 필요합니다.');
      return;
    }

    setIsLoading(true);
    setLoadingMessage(`장면 애니메이션 생성 중... (${numFrames} 프레임)`);
    setError('');

    try {
      const generatedFrames: string[] = [startFrame];
      const model = 'gemini-2.5-flash-image';

      const characterPrompts = characters.map(c => c.prompt).join(', ');

      for (let i = 1; i < numFrames - 1; i++) {
        setLoadingMessage(`프레임 ${i + 1}/${numFrames} 생성 중...`);

        const interpolationValue = i / (numFrames - 1);
        const textPart = { text: `Create an in-between frame for an animation.
          Characters: [${characterPrompts}]
          Style: [${selectedStyle.prompt}]
          This frame is ${Math.round(interpolationValue * 100)}% of the way between the start and end frames.
          Scene Context: ${scene.script}
          Animation Details: ${prompt || 'smoothly transition between the start and end poses.'}
          CRITICAL RULE: Do NOT include any text, letters, or numbers in the image.`};

        const response = await ai.models.generateContent({
            model,
            contents: {
                parts: [
                    {text: "START FRAME:"},
                    imageToGenerativePart(startFrame),
                    {text: "END FRAME:"},
                    imageToGenerativePart(endFrame),
                    textPart
                ]
            },
        });

        const imagePart = response.candidates[0].content.parts.find(p => p.inlineData);
        if (imagePart && imagePart.inlineData) {
            generatedFrames.push(imagePart.inlineData.data);
        } else {
            console.warn(`Frame ${i+1} generation failed, reusing previous frame.`);
            generatedFrames.push(generatedFrames[generatedFrames.length - 1]);
        }
      }
      generatedFrames.push(endFrame);

      setScenes(scenes.map(s => s.id === sceneId ? { ...s, animationFrames: generatedFrames } : s));

    } catch (e) {
      setError(e instanceof Error ? e.message : '애니메이션 프레임 생성 중 오류가 발생했습니다.');
      console.error(e);
    } finally {
      setIsLoading(false);
    }
  };


  // --- RENDER FUNCTIONS ---

  const renderLoading = () => (
    <div className="fixed inset-0 bg-black bg-opacity-50 flex flex-col items-center justify-center z-50">
      <div className="bg-white p-8 rounded-lg shadow-xl text-center">
        <LoaderCircle className="h-12 w-12 text-indigo-600 animate-spin mx-auto" />
        <p className="mt-4 text-lg font-medium text-gray-700">{loadingMessage}</p>
        <p className="mt-1 text-sm text-gray-500">잠시만 기다려주세요...</p>
      </div>
    </div>
  );

  const renderError = () => (
    error && (
      <div className="fixed bottom-4 right-4 bg-red-100 border border-red-400 text-red-700 px-4 py-3 rounded-lg shadow-lg z-50 flex items-center">
        <span className="block sm:inline">{error}</span>
        <button onClick={() => setError('')} className="ml-4">
          <X className="h-5 w-5" />
        </button>
      </div>
    )
  );

  const Section = ({ title, icon, sectionKey, children }) => {
    const isOpen = openSections[sectionKey];
    return (
      <div className="border border-gray-200 rounded-lg mb-4 bg-white shadow-sm">
        <button
          className="w-full flex justify-between items-center p-4 text-left"
          onClick={() => toggleSection(sectionKey)}
        >
          <div className="flex items-center">
            {icon}
            <h2 className="text-xl font-semibold text-gray-800">{title}</h2>
          </div>
          {isOpen ? <ChevronUp className="h-6 w-6 text-gray-500" /> : <ChevronDown className="h-6 w-6 text-gray-500" />}
        </button>
        {isOpen && <div className="p-4 border-t border-gray-200">{children}</div>}
      </div>
    );
  };

  const renderCharacterSetup = () => (
    <div className="grid grid-cols-2 md:grid-cols-4 lg:grid-cols-6 gap-4">
      {characters.map((char) => (
        <div key={char.id} className="relative group border-2 border-dashed border-gray-300 rounded-lg p-2 text-center">
          <img src={`data:image/png;base64,${char.image}`} alt={char.name} className="w-full h-auto object-cover rounded-md aspect-square" />
          <p className="text-sm mt-2 truncate font-medium">{char.name}</p>
          <button
            onClick={() => setCharacters(characters.filter(c => c.id !== char.id))}
            className="absolute top-1 right-1 bg-red-500 text-white rounded-full p-1 opacity-0 group-hover:opacity-100 transition-opacity"
            aria-label="캐릭터 삭제"
          >
            <Trash2 className="h-4 w-4" />
          </button>
        </div>
      ))}
      <button
        onClick={() => fileInputRef.current?.click()}
        className="flex flex-col items-center justify-center p-4 border-2 border-dashed border-gray-300 rounded-lg hover:bg-gray-50 transition-colors h-full aspect-square"
      >
        <UserPlus className="h-8 w-8 text-gray-400 mb-2" />
        <span className="text-sm text-gray-500 text-center">캐릭터 추가</span>
      </button>
      <input
        type="file"
        ref={fileInputRef}
        onChange={(e) => e.target.files && handleAddCharacter(e.target.files[0])}
        className="hidden"
        accept="image/*"
      />
    </div>
  );

  const renderStyleSelection = () => (
    <div className="flex flex-wrap gap-4">
      {ANIMATION_STYLES.map((style) => (
        <button
          key={style.name}
          onClick={() => setSelectedStyle(style)}
          className={`p-2 border-2 rounded-lg flex items-center gap-2 transition-all ${selectedStyle.name === style.name ? 'border-indigo-500 bg-indigo-50 shadow-md' : 'border-gray-300 hover:border-indigo-400'}`}
        >
          <img src={style.previewImage} alt={style.name} className="w-10 h-10 rounded-md object-cover" />
          <div>
            <div className="font-semibold text-gray-800">{style.name}</div>
          </div>
        </button>
      ))}
    </div>
  );

  const renderScenarioInput = () => (
    <div className="flex flex-col gap-4">
      <textarea
        value={scenario}
        onChange={(e) => setScenario(e.target.value)}
        placeholder="여기에 전체 시나리오나 대본을 입력하세요... AI가 문맥에 맞게 장면을 나눠 드립니다."
        className="w-full h-40 p-3 border border-gray-300 rounded-lg focus:ring-2 focus:ring-indigo-500 focus:border-indigo-500 transition"
      />
      <button
        onClick={handleSplitScenario}
        disabled={isLoading}
        className="self-start bg-indigo-600 text-white font-bold py-2 px-6 rounded-lg hover:bg-indigo-700 disabled:bg-indigo-300 transition-colors flex items-center gap-2"
      >
        <Sparkles className="h-5 w-5" />
        스토리보드 생성
      </button>
    </div>
  );

  const renderAnimationEditor = (scene: Scene) => (
    <div className="bg-gray-50 p-4 mt-4 rounded-lg border border-gray-200">
        <h4 className="text-md font-semibold text-gray-700 mb-3">애니메이션 설정</h4>
        <div className="grid grid-cols-1 md:grid-cols-2 gap-4 items-start">
            <div className="flex flex-col items-center gap-2">
                <label className="font-medium text-sm">시작 프레임</label>
                <div className="w-full h-48 border-2 border-dashed rounded-lg bg-white flex items-center justify-center">
                    <img src={`data:image/png;base64,${scene.animationSettings.startFrame}`} className="max-w-full max-h-full object-contain rounded" alt="시작 프레임"/>
                </div>
            </div>
            <div className="flex flex-col items-center gap-2">
                 <label className="font-medium text-sm">종료 프레임</label>
                 <div className="w-full h-48 border-2 border-dashed rounded-lg bg-white flex items-center justify-center p-2 relative">
                    {scene.animationSettings.endFrame ? (
                        <img src={`data:image/png;base64,${scene.animationSettings.endFrame}`} className="max-w-full max-h-full object-contain rounded" alt="종료 프레임"/>
                    ) : (
                        <span className="text-xs text-gray-500">이미지 업로드</span>
                    )}
                    <input
                        type="file"
                        className="absolute inset-0 w-full h-full opacity-0 cursor-pointer"
                        accept="image/*"
                        onChange={async (e) => {
                            if (e.target.files && e.target.files[0]) {
                                const file = e.target.files[0];
                                const base64 = (await fileToGenerativePart(file)).inlineData.data;
                                handleAnimationSettingChange(scene.id, 'endFrame', base64);
                            }
                        }}
                    />
                 </div>
            </div>
        </div>
        <div className="mt-4">
          <label htmlFor={`prompt-${scene.id}`} className="block text-sm font-medium text-gray-700 mb-1">애니메이션 프롬프트</label>
          <input
            id={`prompt-${scene.id}`}
            type="text"
            placeholder="예: 캐릭터가 왼쪽으로 천천히 고개를 돌립니다."
            value={scene.animationSettings.prompt}
            onChange={(e) => handleAnimationSettingChange(scene.id, 'prompt', e.target.value)}
            className="w-full p-2 border border-gray-300 rounded-md"
          />
        </div>
        <div className="mt-4">
            <label htmlFor={`frames-${scene.id}`} className="block text-sm font-medium text-gray-700 mb-1">프레임 수: {scene.animationSettings.numFrames}</label>
            <input
                id={`frames-${scene.id}`}
                type="range"
                min="3"
                max="30"
                value={scene.animationSettings.numFrames}
                onChange={(e) => handleAnimationSettingChange(scene.id, 'numFrames', parseInt(e.target.value, 10))}
                className="w-full h-2 bg-gray-200 rounded-lg appearance-none cursor-pointer"
            />
        </div>
        <div className="mt-6 flex justify-end">
            <button
                onClick={() => handleGenerateAnimationForScene(scene.id)}
                disabled={isLoading || !scene.animationSettings.endFrame}
                className="bg-green-600 text-white font-bold py-2 px-4 rounded-lg hover:bg-green-700 disabled:bg-green-300 transition-colors flex items-center gap-2"
            >
                <Film className="h-5 w-5"/>
                애니메이션 생성
            </button>
        </div>
    </div>
  );

  const renderTimeline = () => (
    <div className="flex overflow-x-auto p-4 space-x-8 bg-gray-100 rounded-lg">
      {scenes.map((scene, index) => (
        <React.Fragment key={scene.id}>
          <div className="w-80 flex-shrink-0 bg-white rounded-lg shadow-md p-3">
            <div className="flex justify-between items-center mb-2">
              <span className="font-bold text-indigo-600">Scene #{index + 1}</span>
            </div>

            {scene.animationFrames ? (
               <div className="w-full h-48 border rounded-lg bg-black flex items-center justify-center overflow-hidden">
                    <img src={`data:image/gif;base64,${/* Placeholder for GIF */ ''}`} alt="애니메이션 미리보기" className="w-full h-full object-contain" />
                    <p className="text-white absolute">애니메이션 있음</p>
                </div>
            ) : (
                <div className="w-full h-48 border rounded-lg bg-gray-200 flex items-center justify-center">
                    <img src={`data:image/png;base64,${scene.keyframeImage}`} alt={`Scene ${index + 1} keyframe`} className="max-w-full max-h-full object-contain rounded-md" />
                </div>
            )}

            <p className="text-sm text-gray-600 mt-2 p-2 bg-gray-50 rounded h-20 overflow-y-auto">{scene.script}</p>

            <div className="mt-3">
              <button
                onClick={() => handleToggleAnimate(scene.id)}
                className="w-full text-sm bg-blue-100 text-blue-800 font-semibold py-2 px-4 rounded-lg hover:bg-blue-200 transition-colors flex items-center justify-center gap-2"
              >
                <Layers className="h-4 w-4" />
                {scene.isAnimating ? '애니메이션 닫기' : '애니메이션 만들기'}
              </button>
              {scene.isAnimating && renderAnimationEditor(scene)}
            </div>
          </div>
          {index < scenes.length - 1 && (
            <div className="flex items-center">
              <button className="bg-gray-300 rounded-full p-2 hover:bg-indigo-500 hover:text-white transition-colors">
                <Plus className="h-5 w-5" />
              </button>
            </div>
          )}
        </React.Fragment>
      ))}
    </div>
  );

  const renderFinalize = () => (
    <div className="flex flex-wrap gap-4">
        <button className="bg-gray-200 text-gray-800 font-bold py-2 px-4 rounded-lg hover:bg-gray-300 transition-colors flex items-center gap-2">
            <FileAudio className="h-5 w-5"/>
            오디오 업로드 (MP3)
        </button>
        <button className="bg-gray-200 text-gray-800 font-bold py-2 px-4 rounded-lg hover:bg-gray-300 transition-colors flex items-center gap-2">
            <Type className="h-5 w-5"/>
            TTS 음성 생성
        </button>
        <button className="bg-purple-600 text-white font-bold py-2 px-4 rounded-lg hover:bg-purple-700 transition-colors flex items-center gap-2">
            <Video className="h-5 w-5"/>
            전체 미리보기
        </button>
        <button className="bg-emerald-600 text-white font-bold py-2 px-4 rounded-lg hover:bg-emerald-700 transition-colors flex items-center gap-2">
            <Download className="h-5 w-5"/>
            영상으로 내보내기
        </button>
    </div>
  );

  return (
    <div className="bg-gray-50 min-h-screen">
      {isLoading && renderLoading()}
      {renderError()}
      <header className="bg-white shadow-md p-4 flex items-center">
        <Clapperboard className="h-8 w-8 text-indigo-600" />
        <h1 className="text-2xl font-bold text-gray-800 ml-2">Gemini Animation Studio</h1>
      </header>

      <main className="p-4 md:p-8">
        <Section title="1. 캐릭터 설정" icon={<PersonStanding className="h-6 w-6 mr-2 text-indigo-600" />} sectionKey="character">
            {renderCharacterSetup()}
        </Section>

        <Section title="2. 스타일 선택" icon={<Palette className="h-6 w-6 mr-2 text-indigo-600" />} sectionKey="style">
            {renderStyleSelection()}
        </Section>

        <Section title="3. 시나리오 입력" icon={<Text className="h-6 w-6 mr-2 text-indigo-600" />} sectionKey="scenario">
            {renderScenarioInput()}
        </Section>

        {scenes.length > 0 && (
          <Section title="4. 씬 타임라인 & 편집" icon={<Film className="h-6 w-6 mr-2 text-indigo-600" />} sectionKey="timeline">
            {renderTimeline()}
          </Section>
        )}

        {scenes.length > 0 && (
          <Section title="5. 오디오 및 최종화" icon={<Music2 className="h-6 w-6 mr-2 text-indigo-600" />} sectionKey="finalize">
            {renderFinalize()}
          </Section>
        )}
      </main>
    </div>
  );
}

