import React, { useState, useRef, useEffect, useCallback } from 'react';
import { GoogleGenAI } from '@google/genai';
import GIF from 'gif.js';
import JSZip from 'jszip';
import {
  Brush,
  ChevronDown,
  ChevronUp,
  Download,
  Film,
  Layers,
  LoaderCircle,
  Music2,
  Palette,
  Pause,
  Pencil,
  PersonStanding,
  Play,
  Plus,
  RotateCcw,
  Sparkles,
  Text,
  Trash2,
  Upload,
  UserPlus,
  Video,
  X,
  Clapperboard,
  FileAudio,
  Type,
  Eraser,
} from 'lucide-react';

const ai = new GoogleGenAI({apiKey: process.env.API_KEY});

// --- TYPE DEFINITIONS ---
interface Character {
  id: string;
  name: string;
  image: string;
  prompt: string;
}

interface Scene {
  id: string;
  script: string;
  keyframeImage: string;
  animationFrames?: string[];
  transition: 'cut' | 'fade' | 'dissolve';
  animationSettings: {
    startFrame: string;
    endFrame: string;
    numFrames: number;
    prompt: string;
  }
}

interface AnimationStyle {
  name: string;
  prompt: string;
  icon: React.ElementType;
  previewImage: string;
}

// --- CONSTANTS ---
const ANIMATION_STYLES: AnimationStyle[] = [
  {
    name: '애니메이션',
    prompt:
      'a vibrant, detailed anime style, with sharp lines, expressive eyes, and dynamic shading, reminiscent of modern Japanese animation.',
    icon: Film,
    previewImage: 'data:image/png;base64,',
  },
  {
    name: '카툰',
    prompt:
      'a friendly, bubbly American cartoon style with soft, rounded shapes, bold outlines, and simple, bright colors.',
    icon: Brush,
    previewImage: 'data:image/png;base64,',
  },
];


// --- HELPER FUNCTIONS ---
const fileToGenerativePart = async (file: File) => {
  const base64EncodedData = await new Promise<string>((resolve) => {
    const reader = new FileReader();
    reader.onload = () => resolve((reader.result as string).split(',')[1]);
    reader.readAsDataURL(file);
  });
  return { inlineData: { data: base64EncodedData, mimeType: file.type } };
};

const imageToGenerativePart = (base64Data: string, mimeType = 'image/png') => {
  return { inlineData: { data: base64Data, mimeType } };
};

// --- CANVAS COMPONENT (Restored) ---
const Canvas = ({ image, onUpdate, width = 512, height = 512, tool, brushColor, brushSize, onClear }: {
    image: string,
    onUpdate: (data: string) => void,
    width?: number,
    height?: number,
    tool: string,
    brushColor: string,
    brushSize: number,
    onClear: () => void,
}) => {
    const canvasRef = useRef<HTMLCanvasElement>(null);
    const isDrawing = useRef(false);
    const lastPos = useRef<{ x: number; y: number } | null>(null);

    const drawImage = useCallback(() => {
        const canvas = canvasRef.current;
        if (!canvas) return;
        const ctx = canvas.getContext('2d');
        if (!ctx) return;
        ctx.fillStyle = 'white';
        ctx.fillRect(0, 0, width, height);
        if (image) {
            const img = new Image();
            img.crossOrigin = 'anonymous';
            img.src = `data:image/png;base64,${image}`;
            img.onload = () => {
                ctx.drawImage(img, 0, 0, width, height);
            };
        }
    }, [image, width, height]);

    useEffect(() => {
        drawImage();
    }, [drawImage]);

    useEffect(() => {
        const canvas = canvasRef.current;
        if (!canvas) return;
        const ctx = canvas.getContext('2d');
        if (!ctx) return;
        if (onClear) { // A bit of a hack to link clear button to canvas
          ctx.fillStyle = 'white';
          ctx.fillRect(0, 0, width, height);
        }
    }, [onClear, width, height]);


    const getMousePos = (e: React.MouseEvent<HTMLCanvasElement>) => {
        if (!canvasRef.current) return { x: 0, y: 0 };
        const rect = canvasRef.current.getBoundingClientRect();
        return {
            x: e.clientX - rect.left,
            y: e.clientY - rect.top,
        };
    };

    const startDrawing = (e: React.MouseEvent<HTMLCanvasElement>) => {
        isDrawing.current = true;
        lastPos.current = getMousePos(e);
    };

    const draw = (e: React.MouseEvent<HTMLCanvasElement>) => {
        if (!isDrawing.current) return;
        const canvas = canvasRef.current;
        const ctx = canvas?.getContext('2d');
        const pos = getMousePos(e);

        if (ctx && lastPos.current) {
            ctx.beginPath();
            if (tool === 'pencil') {
                ctx.globalCompositeOperation = 'source-over';
                ctx.strokeStyle = brushColor;
                ctx.lineWidth = brushSize;
                ctx.lineCap = 'round';
                ctx.lineJoin = 'round';
            } else { // eraser
                ctx.globalCompositeOperation = 'destination-out';
                ctx.lineWidth = brushSize * 2;
            }
            ctx.moveTo(lastPos.current.x, lastPos.current.y);
            ctx.lineTo(pos.x, pos.y);
            ctx.stroke();
        }
        lastPos.current = pos;
    };

    const stopDrawing = () => {
        isDrawing.current = false;
        lastPos.current = null;
        if (onUpdate && canvasRef.current) {
            onUpdate(canvasRef.current.toDataURL('image/png').split(',')[1]);
        }
    };

    return (
        <canvas
            ref={canvasRef}
            width={width}
            height={height}
            className="border-2 border-gray-300 rounded-lg shadow-inner cursor-crosshair bg-white"
            onMouseDown={startDrawing}
            onMouseMove={draw}
            onMouseUp={stopDrawing}
            onMouseLeave={stopDrawing}
        />
    );
};

// --- MAIN COMPONENT ---
export default function Home() {
  // --- STATE FOR ORIGINAL FUNCTIONALITY ---
  const [startFrame, setStartFrame] = useState('');
  const [endFrame, setEndFrame] = useState('');
  const [generatedFrames, setGeneratedFrames] = useState<string[]>([]);
  const [numFrames, setNumFrames] = useState(10);
  const [isPlaying, setIsPlaying] = useState(false);
  const [currentFrameIndex, setCurrentFrameIndex] = useState(0);
  const [activeTool, setActiveTool] = useState('pencil');
  const [brushSize, setBrushSize] = useState(5);
  const [brushColor, setBrushColor] = useState('#000000');

  // --- STATE FOR NEW WORKFLOW ---
  const [characters, setCharacters] = useState<Character[]>([]);
  const [selectedStyle, setSelectedStyle] = useState<AnimationStyle>(ANIMATION_STYLES[0]);
  const [scenario, setScenario] = useState('');
  const [scenes, setScenes] = useState<Scene[]>([]);
  const [activeSceneId, setActiveSceneId] = useState<string | null>(null);

  // --- GENERAL STATE ---
  const [isLoading, setIsLoading] = useState(false);
  const [loadingMessage, setLoadingMessage] = useState('');
  const [error, setError] = useState('');
  const [openSections, setOpenSections] = useState({
    story: false,
    timeline: true,
  });

  const fileInputRef = useRef<HTMLInputElement>(null);
  const startFrameFileRef = useRef<HTMLInputElement>(null);
  const endFrameFileRef = useRef<HTMLInputElement>(null);
  const playbackIntervalRef = useRef<number | null>(null);

  // --- PLAYBACK LOGIC (Restored) ---
  useEffect(() => {
    if (isPlaying) {
      playbackIntervalRef.current = window.setInterval(() => {
        setCurrentFrameIndex(prev => (prev + 1) % generatedFrames.length);
      }, 100);
    } else {
      if (playbackIntervalRef.current) {
        clearInterval(playbackIntervalRef.current);
      }
    }
    return () => {
      if (playbackIntervalRef.current) clearInterval(playbackIntervalRef.current);
    };
  }, [isPlaying, generatedFrames.length]);

  // --- CORE LOGIC FUNCTIONS ---
  const handleFileUpload = async (file: File, frameSetter: (data: string) => void) => {
    const part = await fileToGenerativePart(file);
    frameSetter(part.inlineData.data);
  };

  const handleGenerateAnimation = async () => {
    if (!startFrame || !endFrame) {
      setError('애니메이션을 만들려면 시작 프레임과 종료 프레임이 모두 필요합니다.');
      return;
    }
    setIsLoading(true);
    setLoadingMessage(`애니메이션 생성 중... (${numFrames} 프레임)`);
    setError('');
    try {
      const frames: string[] = [startFrame];
      const model = 'gemini-2.5-flash-image';

      for (let i = 1; i < numFrames - 1; i++) {
        setLoadingMessage(`프레임 ${i + 1}/${numFrames} 생성 중...`);
        const interpolationValue = i / (numFrames - 1);
        const textPart = { text: `Create an in-between frame for an animation. This frame is ${Math.round(interpolationValue * 100)}% of the way between the start and end frames. Style: [${selectedStyle.prompt}]. CRITICAL: Do NOT include any text.` };

        const response = await ai.models.generateContent({
            model,
            contents: { parts: [ {text: "START FRAME:"}, imageToGenerativePart(startFrame), {text: "END FRAME:"}, imageToGenerativePart(endFrame), textPart ] },
        });

        const imagePart = response.candidates[0].content.parts.find(p => p.inlineData);
        if (imagePart && imagePart.inlineData) {
            frames.push(imagePart.inlineData.data);
        } else {
            frames.push(frames[frames.length - 1]);
        }
      }
      frames.push(endFrame);
      setGeneratedFrames(frames);

      if (activeSceneId) {
        setScenes(scenes.map(s => s.id === activeSceneId ? { ...s, animationFrames: frames, animationSettings: { ...s.animationSettings, startFrame, endFrame, numFrames } } : s));
      }

    } catch (e) {
      setError(e instanceof Error ? e.message : '애니메이션 프레임 생성 중 오류가 발생했습니다.');
      console.error(e);
    } finally {
      setIsLoading(false);
    }
  };

  const handleAddCharacter = async (file: File) => {
    setIsLoading(true);
    setLoadingMessage('캐릭터 분석 중...');
    setError('');
    try {
      const imagePart = await fileToGenerativePart(file);
      const response = await ai.models.generateContent({ model: 'gemini-3-flash-preview', contents: { parts: [ imagePart, { text: 'Describe this character for an animation prompt. Focus on visual details.' } ] } });
      const newCharacter: Character = { id: `char_${Date.now()}`, name: `캐릭터 ${characters.length + 1}`, image: imagePart.inlineData.data, prompt: response.text };
      setCharacters(prev => [...prev, newCharacter]);
    } catch (e) {
      setError('캐릭터 분석에 실패했습니다.'); console.error(e);
    } finally {
      setIsLoading(false);
    }
  };

  const handleSplitScenario = async () => {
    if (!scenario.trim() || characters.length === 0) {
      setError('캐릭터를 추가하고 시나리오를 입력해주세요.'); return;
    }
    setIsLoading(true);
    setLoadingMessage('AI가 시나리오를 장면으로 나누는 중...');
    setError('');
    try {
      const characterPrompts = characters.map(c => c.prompt).join(', ');
      const systemInstruction = `You are a film director. Split the script into logical scenes. Respond with a JSON object: { "scenes": ["script for scene 1", "script for scene 2"] }. ONLY the JSON.`;
      const response = await ai.models.generateContent({ model: 'gemini-3-pro-preview', contents: `Script: "${scenario}"`, config: { systemInstruction, responseMimeType: 'application/json' } });
      const sceneScripts = JSON.parse(response.text.replace(/```json|```/g, '').trim()).scenes;
      if (!Array.isArray(sceneScripts)) throw new Error('Invalid response from AI.');
      const newScenes: Scene[] = [];
      for (let i = 0; i < sceneScripts.length; i++) {
        setLoadingMessage(`장면 ${i + 1}/${sceneScripts.length} 대표 이미지 생성 중...`);
        const script = sceneScripts[i];
        const imageResponse = await ai.models.generateContent({ model: 'gemini-2.5-flash-image', contents: { parts: [{ text: `Characters: [${characterPrompts}]. Style: [${selectedStyle.prompt}]. Scene: [${script}]. Generate a single keyframe.` }] } });
        const imagePart = imageResponse.candidates[0].content.parts.find(p => p.inlineData);
        if (!imagePart?.inlineData) throw new Error(`Image generation failed for scene ${i+1}`);
        newScenes.push({
          id: `scene_${Date.now()}_${i}`, script, keyframeImage: imagePart.inlineData.data, transition: 'cut',
          animationSettings: { startFrame: imagePart.inlineData.data, endFrame: '', numFrames: 10, prompt: '' }
        });
      }
      setScenes(newScenes);
      if (newScenes.length > 0) handleSelectScene(newScenes[0]);
    } catch (e) {
      setError('시나리오 분할에 실패했습니다.'); console.error(e);
    } finally {
      setIsLoading(false);
    }
  };

  const handleSelectScene = (scene: Scene) => {
    setActiveSceneId(scene.id);
    setStartFrame(scene.keyframeImage);
    if (scene.animationFrames && scene.animationFrames.length > 1) {
      setEndFrame(scene.animationSettings.endFrame);
      setNumFrames(scene.animationSettings.numFrames);
      setGeneratedFrames(scene.animationFrames);
    } else {
      setEndFrame('');
      setGeneratedFrames([scene.keyframeImage]);
      setNumFrames(10);
    }
    setCurrentFrameIndex(0);
  };

  const handleExportGif = () => {
    if (generatedFrames.length === 0) return;
    setLoadingMessage('GIF 생성 중...');
    setIsLoading(true);
    const gif = new GIF({ workers: 2, quality: 10, width: 512, height: 512 });
    const imageLoadPromises = generatedFrames.map(frameData => {
        return new Promise<HTMLImageElement>(resolve => {
            const img = new Image();
            img.src = `data:image/png;base64,${frameData}`;
            img.onload = () => resolve(img);
        });
    });
    Promise.all(imageLoadPromises).then(images => {
        images.forEach(img => gif.addFrame(img, { delay: 100 }));
        gif.on('finished', (blob) => {
            const link = document.createElement('a');
            link.href = URL.createObjectURL(blob);
            link.download = 'animation.gif';
            link.click();
            setIsLoading(false);
        });
        gif.render();
    });
  };

  // --- RENDER FUNCTIONS ---
  const toggleSection = (section: keyof typeof openSections) => setOpenSections(prev => ({ ...prev, [section]: !prev[section] }));
  const Section = ({ title, icon, sectionKey, children }: { title: string; icon: React.ReactNode; sectionKey: keyof typeof openSections; children: React.ReactNode }) => (
    <div className="border border-gray-200 rounded-lg mb-4 bg-white shadow-sm">
      <button className="w-full flex justify-between items-center p-4 text-left" onClick={() => toggleSection(sectionKey)}>
        <div className="flex items-center space-x-2"><h2 className="text-xl font-semibold text-gray-800">{icon}{title}</h2></div>
        {openSections[sectionKey] ? <ChevronUp className="h-6 w-6 text-gray-500" /> : <ChevronDown className="h-6 w-6 text-gray-500" />}
      </button>
      {openSections[sectionKey] && <div className="p-4 border-t border-gray-200">{children}</div>}
    </div>
  );

  const FrameEditor = ({ title, frame, setFrame, fileRef }) => (
    <div className="w-full max-w-[512px] mx-auto">
        <h3 className="text-xl font-semibold text-center mb-2">{title}</h3>
        <Canvas image={frame} onUpdate={setFrame} tool={activeTool} brushColor={brushColor} brushSize={brushSize} onClear={() => setFrame('')}/>
        <div className="flex justify-center gap-2 mt-2">
            <button onClick={() => fileRef.current?.click()} className="flex-1 bg-gray-200 p-2 rounded-lg hover:bg-gray-300">업로드</button>
            <button onClick={() => setFrame('')} className="flex-1 bg-gray-200 p-2 rounded-lg hover:bg-gray-300">클리어</button>
            <input type="file" ref={fileRef} onChange={(e) => e.target.files && handleFileUpload(e.target.files[0], setFrame)} className="hidden" accept="image/*" />
        </div>
    </div>
  );

  return (
    <div className="bg-gray-50 min-h-screen">
      {isLoading && <div className="fixed inset-0 bg-black bg-opacity-50 flex flex-col items-center justify-center z-50"><div className="bg-white p-8 rounded-lg shadow-xl text-center"><LoaderCircle className="h-12 w-12 text-indigo-600 animate-spin mx-auto" /><p className="mt-4 text-lg">{loadingMessage}</p></div></div>}
      {error && <div className="fixed bottom-4 right-4 bg-red-100 border-red-400 text-red-700 px-4 py-3 rounded-lg z-50 flex items-center"><span className="block sm:inline">{error}</span><button onClick={() => setError('')} className="ml-4"><X className="h-5 w-5" /></button></div>}

      <header className="bg-white shadow-md p-4 flex items-center sticky top-0 z-10">
        <Clapperboard className="h-8 w-8 text-indigo-600" />
        <h1 className="text-2xl font-bold text-gray-800 ml-2">Gemini Animation Studio</h1>
      </header>

      <main className="p-4 md:p-8">
        <Section title="스토리 모드" icon={<Clapperboard className="inline h-6 w-6 mr-2" />} sectionKey="story">
          <div className="space-y-6">
            <div>
              <h3 className="text-lg font-semibold mb-2">1. 캐릭터 설정</h3>
              <div className="grid grid-cols-2 md:grid-cols-4 lg:grid-cols-6 gap-4">
                {characters.map(char => (<div key={char.id} className="relative group text-center"><img src={`data:image/png;base64,${char.image}`} alt={char.name} className="w-full rounded-md aspect-square object-cover" /><p className="text-sm mt-1">{char.name}</p><button onClick={() => setCharacters(characters.filter(c => c.id !== char.id))} className="absolute top-1 right-1 bg-red-500 text-white rounded-full p-1 opacity-0 group-hover:opacity-100"><Trash2 className="h-4 w-4" /></button></div>))}
                <button onClick={() => fileInputRef.current?.click()} className="flex flex-col items-center justify-center p-4 border-2 border-dashed rounded-lg h-full aspect-square"><UserPlus className="h-8 w-8 text-gray-400" /><span className="text-sm mt-2">캐릭터 추가</span></button>
                <input type="file" ref={fileInputRef} onChange={(e) => e.target.files && handleAddCharacter(e.target.files[0])} className="hidden" accept="image/*" />
              </div>
            </div>
            <div>
              <h3 className="text-lg font-semibold mb-2">2. 스타일 선택</h3>
              <div className="flex flex-wrap gap-4">{ANIMATION_STYLES.map(style => (<button key={style.name} onClick={() => setSelectedStyle(style)} className={`p-2 border-2 rounded-lg flex items-center gap-2 ${selectedStyle.name === style.name ? 'border-indigo-500 bg-indigo-50' : 'border-gray-300'}`}><img src={style.previewImage} alt={style.name} className="w-10 h-10 rounded-md" /><span>{style.name}</span></button>))}</div>
            </div>
            <div>
              <h3 className="text-lg font-semibold mb-2">3. 시나리오 입력</h3>
              <textarea value={scenario} onChange={(e) => setScenario(e.target.value)} placeholder="전체 시나리오를 입력하세요..." className="w-full h-32 p-2 border rounded-lg" />
              <button onClick={handleSplitScenario} disabled={isLoading} className="mt-2 bg-indigo-600 text-white font-bold py-2 px-6 rounded-lg flex items-center gap-2"><Sparkles className="h-5 w-5" />스토리보드 생성</button>
            </div>
          </div>
        </Section>

        {scenes.length > 0 && (
          <Section title="씬 타임라인" icon={<Film className="inline h-6 w-6 mr-2" />} sectionKey="timeline">
            <div className="flex overflow-x-auto p-4 space-x-4 bg-gray-100 rounded-lg">
              {scenes.map((scene, index) => (
                <button key={scene.id} onClick={() => handleSelectScene(scene)} className={`w-64 flex-shrink-0 p-2 rounded-lg text-left ${activeSceneId === scene.id ? 'bg-indigo-200 ring-2 ring-indigo-500' : 'bg-white'}`}>
                  <span className="font-bold text-sm">Scene #{index + 1}</span>
                  <img src={`data:image/png;base64,${scene.keyframeImage}`} alt={`Scene ${index + 1}`} className="w-full h-36 object-cover rounded-md my-1" />
                  <p className="text-xs text-gray-600 h-16 overflow-y-auto">{scene.script}</p>
                </button>
              ))}
            </div>
          </Section>
        )}

        <div className="mt-8">
            <div className="grid grid-cols-1 lg:grid-cols-3 gap-8 items-start">
                <FrameEditor title="시작 프레임" frame={startFrame} setFrame={setStartFrame} fileRef={startFrameFileRef} />

                <div className="flex flex-col items-center gap-4 order-first lg:order-none">
                  <h3 className="text-xl font-semibold text-center">애니메이션 제어</h3>
                  <div className="bg-white p-4 rounded-lg shadow-md w-full max-w-sm">
                    <label className="font-medium">도구</label>
                    <div className="flex gap-2 my-2">
                        <button onClick={() => setActiveTool('pencil')} className={`flex-1 p-2 rounded-lg flex items-center justify-center gap-2 ${activeTool === 'pencil' ? 'bg-blue-500 text-white' : 'bg-gray-200'}`}><Pencil className="h-5 w-5" /> 연필</button>
                        <button onClick={() => setActiveTool('eraser')} className={`flex-1 p-2 rounded-lg flex items-center justify-center gap-2 ${activeTool === 'eraser' ? 'bg-blue-500 text-white' : 'bg-gray-200'}`}><Eraser className="h-5 w-5" /> 지우개</button>
                    </div>
                    <label className="font-medium mt-4 block">브러시 크기: {brushSize}</label>
                    <input type="range" min="1" max="50" value={brushSize} onChange={e => setBrushSize(Number(e.target.value))} className="w-full mt-1" />
                    <label className="font-medium mt-4 block">브러시 색상</label>
                    <input type="color" value={brushColor} onChange={e => setBrushColor(e.target.value)} className="w-full h-10 p-1 mt-1 border rounded" />
                    <label className="font-medium mt-4 block">프레임 수: {numFrames}</label>
                    <input type="range" min="3" max="30" value={numFrames} onChange={(e) => setNumFrames(parseInt(e.target.value))} className="w-full mt-1"/>
                  </div>
                  <button onClick={handleGenerateAnimation} disabled={isLoading || !startFrame || !endFrame} className="bg-green-600 text-white font-bold py-3 px-8 rounded-lg text-lg flex items-center gap-2 disabled:bg-green-300"><Film className="h-6 w-6"/>애니메이션 생성</button>
                </div>

                <FrameEditor title="종료 프레임" frame={endFrame} setFrame={setEndFrame} fileRef={endFrameFileRef} />
            </div>
        </div>

        {generatedFrames.length > 0 && (
          <div className="mt-8">
            <h2 className="text-2xl font-bold mb-4">결과 미리보기</h2>
            <div className="flex flex-col items-center gap-4">
              <div className="relative w-full max-w-[512px]">
                <img src={`data:image/png;base64,${generatedFrames[currentFrameIndex]}`} alt="Generated Animation" className="w-full border-2 rounded-lg"/>
                <div className="absolute top-2 left-2 bg-black bg-opacity-50 text-white text-sm px-2 py-1 rounded">
                    {currentFrameIndex + 1} / {generatedFrames.length}
                </div>
              </div>
              <div className="flex items-center gap-4">
                  <button onClick={() => setIsPlaying(!isPlaying)} className="bg-blue-500 text-white p-3 rounded-full">
                      {isPlaying ? <Pause className="h-6 w-6" /> : <Play className="h-6 w-6" />}
                  </button>
                  <button onClick={handleExportGif} className="bg-purple-600 text-white font-bold py-2 px-4 rounded-lg flex items-center gap-2"><Download className="h-5 w-5" /> GIF로 내보내기</button>
              </div>
            </div>
            <div className="flex overflow-x-auto p-4 gap-2 bg-gray-200 rounded-lg mt-4">
              {generatedFrames.map((frame, index) => (<img key={index} src={`data:image/png;base64,${frame}`} alt={`Frame ${index + 1}`} className={`h-24 w-24 object-cover rounded-md cursor-pointer ${currentFrameIndex === index ? 'ring-2 ring-blue-500' : ''}`} onClick={() => setCurrentFrameIndex(index)}/>))}
            </div>
          </div>
        )}
      </main>
    </div>
  );
}

