              {/* Timeline */}
              <div className="w-full p-3 bg-gray-200/60 rounded-lg shadow-sm">
                <div className="flex items-center gap-2 mb-3">
                  <Video className="w-5 h-5 text-gray-700" />
                  <h3 className="text-sm font-bold text-gray-800">타임라인</h3>
