                          aria-label={`프레임 ${index + 1} 삭제`}>
                          <X className="w-3 h-3" />
                        </button>
                      )}
                    </div>
                  ))}
                </div>
              </div>
            </div>

            {/* Right Column: All tools and settings */}
            <div className="w-full lg:w-1/2 flex flex-col gap-6 mt-6 lg:mt-0">
              <div className="w-full p-3 bg-gray-200/60 rounded-lg shadow-sm">
                <div className="flex items-center gap-2 mb-3">
                  <Settings2 className="w-5 h-5 text-gray-700" />
