type AspectRatio = '16:9' | '9:16' | '1:1';
type ActiveTool = 'pen' | 'eraser' | 'ai-eraser' | 'pan';

const ASPECT_RATIOS = {
  '16:9': {width: 960, height: 540},
  '9:16': {width: 540, height: 960},
  '1:1': {width: 800, height: 800},
};

const THUMBNAIL_DIMS = {
  '16:9': {width: 160, height: 90},
  '9:16': {width: 90, height: 160},
  '1:1': {width: 120, height: 120},
};

// Helper to decode base64 string to Uint8Array
function decode(base64: string) {
  const binaryString = atob(base64);
  const len = binaryString.length;
  const bytes = new Uint8Array(len);
  for (let i = 0; i < len; i++) {
    bytes[i] = binaryString.charCodeAt(i);
  }
  return bytes;
}

// Helper to create a WAV blob from raw PCM data for playback
function createWavBlob(
  pcmData: Uint8Array,
  sampleRate: number,
  numChannels: number,
): Blob {
  const bitsPerSample = 16;
  const dataSize = pcmData.length;
  const buffer = new ArrayBuffer(44); // Header size
  const view = new DataView(buffer);
  const blockAlign = numChannels * (bitsPerSample / 8);
  const byteRate = sampleRate * blockAlign;

  // RIFF chunk descriptor
  view.setUint32(0, 0x52494646, false); // 'RIFF'
  view.setUint32(4, 36 + dataSize, true); // file-size - 8
  view.setUint32(8, 0x57415645, false); // 'WAVE'

  // "fmt " sub-chunk
  view.setUint32(12, 0x666d7420, false); // 'fmt '
  view.setUint32(16, 16, true); // 16 for PCM
  view.setUint16(20, 1, true); // PCM is 1
  view.setUint16(22, numChannels, true);
  view.setUint32(24, sampleRate, true);
  view.setUint32(28, byteRate, true);
  view.setUint16(32, blockAlign, true);
  view.setUint16(34, bitsPerSample, true);

  // "data" sub-chunk header
  const dataHeaderBuffer = new ArrayBuffer(8);
  const dataHeaderView = new DataView(dataHeaderBuffer);
  dataHeaderView.setUint32(0, 0x64617461, false); // 'data'
  dataHeaderView.setUint32(4, dataSize, true); // data-size

  return new Blob([view.buffer, pcmData], {type: 'audio/wav'});
}

export default function Home() {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const [activeTool, setActiveTool] = useState<ActiveTool>('pen');
  const isInteracting = useRef(false);
  const lastPosition = useRef({ x: 0, y: 0 });
  const [penColor, setPenColor] = useState('#000000');
  const colorInputRef = useRef(null);
  const [prompt, setPrompt] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const [showErrorModal, setShowErrorModal] = useState(false);
  const [errorMessage, setErrorMessage] = useState('');
  const [selectedModel, setSelectedModel] = useState('gemini-2.5-flash-image');

  // Canvas transform state
  const [zoom, setZoom] = useState(1);
  const [pan, setPan] = useState({ x: 0, y: 0 });

  // Animation state
  const [frames, setFrames] = useState<(string | null)[]>([null]);
  const [currentFrameIndex, setCurrentFrameIndex] = useState(0);
  const [isPlaying, setIsPlaying] = useState(false);
  const [numKeyScenes, setNumKeyScenes] = useState(3);
  const [sceneDuration, setSceneDuration] = useState(2);
  const [fps, setFps] = useState(8);
  const [frameDurations, setFrameDurations] = useState<number[]>([1000 / fps]);
  const thumbnailRefs = useRef<(HTMLCanvasElement | null)[]>([]);
  const [isExporting, setIsExporting] = useState(false);
  const [isExportingMp4, setIsExportingMp4] = useState(false);
  const playbackTimeoutRef = useRef<number | null>(null);

  // Narration State
  const [narrationAudio, setNarrationAudio] = useState<string | null>(null);
  const [isGeneratingNarration, setIsGeneratingNarration] = useState(false);
  const [initialPrompt, setInitialPrompt] = useState('');
  const audioRef = useRef<HTMLAudioElement>(null);

  // Aspect Ratio State
  const [aspectRatio, setAspectRatio] = useState<AspectRatio>('16:9');
  const [showAspectRatioConfirm, setShowAspectRatioConfirm] = useState(false);
  const [targetAspectRatio, setTargetAspectRatio] =
    useState<AspectRatio | null>(null);
  const [isRecomposing, setIsRecomposing] = useState(false);

  // Undo/Redo state
  const [history, setHistory] = useState<{ [key: number]: string[] }>({});
  const [historyIndex, setHistoryIndex] = useState<{ [key: number]: number }>(
    {},
  );

  // Reference image state
  const fileInputRef = useRef<HTMLInputElement>(null);
  const [referenceImage, setReferenceImage] = useState<string | null>(null);

  // Character Cast State
  const [cast, setCast] = useState<string[]>([]);
  const [selectedCharacterIndex, setSelectedCharacterIndex] = useState<
    number | null
  >(null);

  // Export frames state
  const [showExportFramesModal, setShowExportFramesModal] = useState(false);
  const [exportFormat, setExportFormat] = useState<'png' | 'jpg'>('png');

  // GIF export state
  const [showGifExportModal, setShowGifExportModal] = useState(false);
  const [gifQuality, setGifQuality] = useState(10); // 1-30, lower is better

  // Style state
  const [selectedStyle, setSelectedStyle] = useState<string | null>(null);
  const [hoveredStyle, setHoveredStyle] = useState<string | null>(null);

  const drawCanvasContent = () => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    // Clear canvas
    ctx.save();
    ctx.setTransform(1, 0, 0, 1, 0, 0);
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    ctx.restore();

    // Apply zoom and pan
    ctx.save();
    ctx.translate(pan.x, pan.y);
    ctx.scale(zoom, zoom);

    // Draw the current frame image
    const dataUrl = frames[currentFrameIndex];
    if (dataUrl) {
        const img = new Image();
        img.onload = () => {
            ctx.drawImage(img, 0, 0);
            ctx.restore();
        };
        img.src = dataUrl;
    } else {
        ctx.restore();
    }
  };

  useEffect(() => {
    drawCanvasContent();
  }, [currentFrameIndex, frames, aspectRatio, zoom, pan]);


    // Update thumbnails when frames change
    const drawThumbnail = (ctx: CanvasRenderingContext2D, img: HTMLImageElement) => {
        const canvas = ctx.canvas;
        const hRatio = canvas.width / img.width;
        const vRatio = canvas.height / img.height;
        const ratio = Math.min(hRatio, vRatio);
        const centerShift_x = (canvas.width - img.width * ratio) / 2;
        const centerShift_y = (canvas.height - img.height * ratio) / 2;
        ctx.clearRect(0, 0, canvas.width, canvas.height);
        ctx.drawImage(img, 0, 0, img.width, img.height,
                      centerShift_x, centerShift_y, img.width * ratio, img.height * ratio);
    };

  useEffect(() => {
    frames.forEach((frameDataUrl, index) => {
      const canvas = thumbnailRefs.current[index];
      if (!canvas) return;
      const ctx = canvas.getContext('2d');
      if (!ctx) return;

      // Clear with white background first
      ctx.fillStyle = '#FFFFFF';
      ctx.fillRect(0, 0, canvas.width, canvas.height);
      ctx.strokeStyle = '#DDDDDD';
      ctx.strokeRect(0, 0, canvas.width, canvas.height);

      if (frameDataUrl) {
        const img = new Image();
        img.onload = () => {
            drawThumbnail(ctx, img);
        };
        img.src = frameDataUrl;
      }
    });
  }, [frames, aspectRatio]);

    // Animation playback
    useEffect(() => {
        if (playbackTimeoutRef.current) {
            clearTimeout(playbackTimeoutRef.current);
        }

        if (isPlaying) {
            const playNextFrame = () => {
                setCurrentFrameIndex(prevIndex => (prevIndex + 1) % frames.length);
            };

            const currentDuration = frameDurations[currentFrameIndex] ?? 1000 / fps;
            playbackTimeoutRef.current = window.setTimeout(playNextFrame, currentDuration);
        }

        return () => {
            if (playbackTimeoutRef.current) {
                clearTimeout(playbackTimeoutRef.current);
            }
        };
    }, [isPlaying, currentFrameIndex, frames.length, frameDurations, fps]);

  const handleFpsChange = (newFps: number) => {
    setFps(newFps);
  };

  const getCoordinates = (e: React.MouseEvent | React.TouchEvent) => {
    const canvas = canvasRef.current;
    if (!canvas) return { x: 0, y: 0 };
    const rect = canvas.getBoundingClientRect();

    const clientX = 'touches' in e ? e.touches[0].clientX : e.clientX;
    const clientY = 'touches' in e ? e.touches[0].clientY : e.clientY;

    const canvasX = clientX - rect.left;
    const canvasY = clientY - rect.top;

    // Invert the transformation to get coordinates on the zoomed/panned canvas
    const transformedX = (canvasX - pan.x) / zoom;
    const transformedY = (canvasY - pan.y) / zoom;

    return {
      x: transformedX,
      y: transformedY,
    };
  };

  const startInteraction = (e: React.MouseEvent | React.TouchEvent) => {
    if ('touches' in e) e.preventDefault();
    if (isPlaying) setIsPlaying(false);

    const canvas = canvasRef.current;
    if (!canvas) return;
    const { x, y } = getCoordinates(e);

    // For panning, we need the raw client coordinates
    const clientX = 'touches' in e ? e.touches[0].clientX : e.clientX;
    const clientY = 'touches' in e ? e.touches[0].clientY : e.clientY;
    lastPosition.current = { x: clientX, y: clientY };

    isInteracting.current = true;

    if (activeTool !== 'pan') {
      const ctx = canvas.getContext('2d');
      if (!ctx) return;
      ctx.save();
      ctx.translate(pan.x, pan.y);
      ctx.scale(zoom, zoom);
      ctx.beginPath();
      ctx.moveTo(x, y);
      ctx.restore();
    }
  };

  const moveInteraction = (e: React.MouseEvent | React.TouchEvent) => {
    if (!isInteracting.current) return;
    if ('touches' in e) e.preventDefault();

    const canvas = canvasRef.current;
    if (!canvas) return;
    const { x, y } = getCoordinates(e);

    if (activeTool === 'pan') {
        const clientX = 'touches' in e ? e.touches[0].clientX : e.clientX;
        const clientY = 'touches' in e ? e.touches[0].clientY : e.clientY;
        const dx = clientX - lastPosition.current.x;
        const dy = clientY - lastPosition.current.y;
        setPan({ x: pan.x + dx, y: pan.y + dy });
        lastPosition.current = { x: clientX, y: clientY };
    } else {
        const ctx = canvas.getContext('2d');
        if (!ctx) return;
        ctx.save();
        ctx.translate(pan.x, pan.y);
        ctx.scale(zoom, zoom);

        if (activeTool === 'pen') {
            ctx.globalCompositeOperation = 'source-over';
            ctx.lineWidth = 5 / zoom;
            ctx.lineCap = 'round';
            ctx.strokeStyle = penColor;
        } else { // eraser or ai-eraser
            ctx.globalCompositeOperation = 'destination-out';
            ctx.lineWidth = 20 / zoom;
            ctx.lineCap = 'round';
        }

        ctx.lineTo(x, y);
        ctx.stroke();
        ctx.restore();
    }
  };

  const handleAiInpaint = async () => {
        const canvas = canvasRef.current;
        if (!canvas) return;

        // Create a temporary canvas to get the final visual state with transforms
        const tempCanvas = document.createElement('canvas');
        tempCanvas.width = canvas.width;
        tempCanvas.height = canvas.height;
        const tempCtx = tempCanvas.getContext('2d');
        if (!tempCtx) return;

        // Draw the current frame image
        const img = new Image();
        img.onload = async () => {
            tempCtx.drawImage(img, 0, 0);

            // Now draw the erased part from the main canvas on top
            tempCtx.drawImage(canvas, 0, 0);

            const currentFrameData = tempCanvas.toDataURL('image/png');

            setIsLoading(true);
            try {
                const aiPrompt = `This is an inpainting request. The transparent pixels in this image should be filled in. Use the surrounding image content and style to fill the transparent area. Additionally, follow this user instruction: ${prompt || 'seamlessly blend with the background'}. CRITICAL: Do not include any text, letters, or numbers in the image.`;

                const parts = [
                    { inlineData: { data: currentFrameData.split(',')[1], mimeType: 'image/png' } },
                    { text: aiPrompt }
                ];

                const response = await ai.models.generateContent({
                    model: selectedModel,
                    contents: { parts },
                });

                let generatedImageData: string | undefined;
                for (const part of response.candidates?.[0]?.content?.parts || []) {
                    if (part.inlineData) {
                        generatedImageData = part.inlineData.data;
                        break;
                    }
                }

                if (generatedImageData) {
                    const imageUrl = `data:image/png;base64,${generatedImageData}`;
                    const newFrames = [...frames];
                    newFrames[currentFrameIndex] = imageUrl;
                    setFrames(newFrames);
                    updateHistory(imageUrl);
                    setPrompt('');
                } else {
                    throw new Error('AI 지우개 작업에 실패했습니다. 안전 설정에 의해 차단되었을 수 있습니다.');
                }
            } catch (error) {
                console.error('AI inpainting failed:', error);
                setErrorMessage(parseError(error.message) || 'AI 지우개 작업 중 오류가 발생했습니다.');
                setShowErrorModal(true);
                // Revert to pre-erased state on failure
                drawCanvasContent();
            } finally {
                setIsLoading(false);
            }
        };
        img.src = frames[currentFrameIndex] || `data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAQAAAC1HAwCAAAAC0lEQVR42mNkYAAAAAYAAjCB0C8AAAAASUVORK5CYII=`; // Use transparent pixel if no image
    };

  const stopInteraction = () => {
    if (!isInteracting.current) return;
    isInteracting.current = false;

    const canvas = canvasRef.current;
    if (!canvas || activeTool === 'pan') return;

    if (activeTool === 'ai-eraser') {
        handleAiInpaint();
    } else {
        // Create a temporary canvas to flatten the drawing with transforms
        const tempCanvas = document.createElement('canvas');
        tempCanvas.width = canvas.width;
        tempCanvas.height = canvas.height;
        const tempCtx = tempCanvas.getContext('2d');
        if (!tempCtx) return;

        // Draw existing image if it exists
        const existingImage = frames[currentFrameIndex];
        if (existingImage) {
            const img = new Image();
            img.src = existingImage;
            tempCtx.drawImage(img, 0, 0);
        }

        // Draw the new strokes from the main canvas, applying transforms
        tempCtx.save();
        tempCtx.translate(pan.x, pan.y);
        tempCtx.scale(zoom, zoom);
        // This part is tricky. Re-drawing strokes is complex.
        // A simpler way is to flatten the view from the main canvas.
        // Let's create the final image state.
        const finalCanvas = document.createElement('canvas');
        finalCanvas.width = canvas.width;
        finalCanvas.height = canvas.height;
        const finalCtx = finalCanvas.getContext('2d');
        if (!finalCtx) return;
        finalCtx.drawImage(canvas, 0, 0);

        const dataUrl = finalCanvas.toDataURL('image/png');

        updateHistory(dataUrl);
        const newFrames = [...frames];
        newFrames[currentFrameIndex] = dataUrl;
        setFrames(newFrames);
    }
  };

  const updateHistory = (dataUrl: string, replace = false) => {
    const currentIndex = historyIndex[currentFrameIndex] ?? -1;
    const currentHistory = history[currentFrameIndex] || [];
    const newHistory = replace
      ? [dataUrl]
      : [...currentHistory.slice(0, currentIndex + 1), dataUrl];

    setHistory({...history, [currentFrameIndex]: newHistory});
    setHistoryIndex({
      ...historyIndex,
      [currentFrameIndex]: newHistory.length - 1,
    });
  };

  const handleUndo = () => {
    const currentIndex = historyIndex[currentFrameIndex] ?? 0;
    if (currentIndex <= 0) return;

    const newIndex = currentIndex - 1;
    setHistoryIndex({...historyIndex, [currentFrameIndex]: newIndex});

    const dataUrl = history[currentFrameIndex][newIndex];
    const newFrames = [...frames];
    newFrames[currentFrameIndex] = dataUrl;
    setFrames(newFrames);
  };

  const handleRedo = () => {
    const currentIndex = historyIndex[currentFrameIndex] ?? -1;
    const frameHistory = history[currentFrameIndex] || [];
    if (currentIndex >= frameHistory.length - 1) return;

    const newIndex = currentIndex + 1;
    setHistoryIndex({...historyIndex, [currentFrameIndex]: newIndex});

    const dataUrl = frameHistory[newIndex];
    const newFrames = [...frames];
    newFrames[currentFrameIndex] = dataUrl;
    setFrames(newFrames);
  };

  const clearCanvas = () => {
    const newFrames = [...frames];
    newFrames[currentFrameIndex] = null;
    setFrames(newFrames);
    // Also clear history for this frame
    const newHistory = {...history};
    delete newHistory[currentFrameIndex];
    setHistory(newHistory);
    const newHistoryIdx = {...historyIndex};
    delete newHistoryIdx[currentFrameIndex];
    setHistoryIndex(newHistoryIdx);
  };

  const handleColorChange = (e: ChangeEvent<HTMLInputElement>) =>
    setPenColor(e.target.value);

  const openColorPicker = () =>
    (colorInputRef.current as HTMLInputElement)?.click();

  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter' || e.key === ' ') openColorPicker();
  };

  const handleImageUpload = (e: ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        setReferenceImage(reader.result as string);
        // Clear the canvas to encourage applying a new style
        clearCanvas();
      };
      reader.readAsDataURL(file);
    }
  };

  const handleStyleSelect = (stylePrompt: string) => {
    if (selectedStyle === stylePrompt) {
      setSelectedStyle(null); // Toggle off if already selected
    } else {
      setSelectedStyle(stylePrompt); // Select the new style
    }
  };

  const handleStyleApply = async (stylePrompt: string) => {
    if (!referenceImage) {
      setErrorMessage('Please upload a photo first to apply a style.');
      setShowErrorModal(true);
      return;
    }
    setIsLoading(true);
    try {
      const parts = [
        {
          inlineData: {
            data: referenceImage.split(',')[1],
            mimeType: referenceImage.match(/:(.*?);/)?.[1] || 'image/png',
          },
        },
        {
          text: `Redraw the person in this photo in the following animation style: ${stylePrompt}. Faithfully translate their key features.`,
        },
      ];

      const response = await ai.models.generateContent({
        model: 'gemini-3-pro-image-preview', // Use a powerful model for style transfer
        contents: {parts},
        config: {systemInstruction: PHOTOREALISTIC_TO_ANIMATION_SYSTEM_INSTRUCTION},
      });

      let generatedImageData: string | undefined;
      for (const part of response.candidates?.[0]?.content?.parts || []) {
        if (part.inlineData) {
          generatedImageData = part.inlineData.data;
          break;
        }
      }

      if (generatedImageData) {
        const imageUrl = `data:image/png;base64,${generatedImageData}`;
        const newFrames = [...frames];
        newFrames[currentFrameIndex] = imageUrl;
        setFrames(newFrames);
        updateHistory(imageUrl, true); // Replace history with the new styled image
      } else {
        throw new Error('Could not generate styled image. It might be blocked by safety settings.');
      }
    } catch (error) {
      console.error('Error applying style:', error);
      setErrorMessage(
        parseError(error.message) || 'An unexpected error occurred while applying style.',
      );
      setShowErrorModal(true);
    } finally {
      setIsLoading(false);
      setReferenceImage(null); // Clear ref image after use
    }
  };


  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!prompt && !selectedStyle) return;
    setIsLoading(true);

    const currentFrameData = frames[currentFrameIndex];
    const hasContentOnCurrentFrame = currentFrameData !== null;

    try {
      // SCENARIO 1: Apply selected style to existing content (prompt is empty)
      if (hasContentOnCurrentFrame && selectedStyle && !prompt) {
        const generationPromises = frames.map(async (frameData) => {
          if (!frameData) return null;

          const parts = [
            { inlineData: { data: frameData.split(',')[1], mimeType: 'image/png' } },
            { text: `Redraw this image in the following style: ${selectedStyle}. IMPORTANT: Do not include any text, letters, or numbers in the image.` }
          ];

          const response = await ai.models.generateContent({
            model: selectedModel,
            contents: {parts},
            config: {systemInstruction: STYLE_CHANGE_SYSTEM_INSTRUCTION},
          });

          let generatedImageData: string | undefined;
          for (const part of response.candidates?.[0]?.content?.parts || []) {
            if (part.inlineData) {
              generatedImageData = part.inlineData.data;
              break;
            }
          }
          return generatedImageData ? `data:image/png;base64,${generatedImageData}` : frameData;
        });

        const newStyledFrames = await Promise.all(generationPromises);
        setFrames(newStyledFrames);
        const newHistory = {};
        const newHistoryIndex = {};
        newStyledFrames.forEach((frame, index) => {
          if (frame) {
            newHistory[index] = [frame];
            newHistoryIndex[index] = 0;
          }
        });
        setHistory(newHistory);
        setHistoryIndex(newHistoryIndex);
        setSelectedStyle(null); // De-select style after applying
      }

      // SCENARIO 2: Modify a single existing frame with a prompt (canvas has content, prompt has text)
      else if (hasContentOnCurrentFrame && prompt) {
        const parts = [];
        parts.push({
          inlineData: {data: currentFrameData.split(',')[1], mimeType: 'image/png'},
        });

        let modificationPrompt = `${prompt}.`;
        if (selectedStyle) {
          modificationPrompt += ` Redraw the result in this style: ${selectedStyle}.`
        }
        modificationPrompt += ` Keep the same minimalist line drawing style as the sketch. IMPORTANT: Do not include any text, letters, or numbers in the image.`
        parts.push({ text: modificationPrompt });

        const response = await ai.models.generateContent({
          model: selectedModel,
          contents: {parts},
          config: {
            systemInstruction: INFOGRAPHIC_SYSTEM_INSTRUCTION,
          },
        });

        let generatedImageData: string | undefined;
        for (const part of response.candidates?.[0]?.content?.parts || []) {
          if (part.inlineData) {
            generatedImageData = part.inlineData.data;
            break;
          }
        }

        if (generatedImageData) {
          const imageUrl = `data:image/png;base64,${generatedImageData}`;
          const newFrames = [...frames];
          newFrames[currentFrameIndex] = imageUrl;
          setFrames(newFrames);
          updateHistory(imageUrl, true);
        } else {
          throw new Error('Could not find an image in the response. It might be blocked by safety settings.');
        }
      } else if (!hasContentOnCurrentFrame && prompt) {
        setErrorMessage("Please generate an animation using the controls below, or draw something first.");
        setShowErrorModal(true);
      }

      setPrompt('');
    } catch (error) {
      console.error('Error on submit:', error);
      setErrorMessage(
        parseError(error.message) || 'An unexpected error occurred.',
      );
      setShowErrorModal(true);
    } finally {
      setIsLoading(false);
    }
  };

  const handleGenerateAnimation = async (generationPrompt: string) => {
    if (!generationPrompt) return;
    setIsLoading(true);
    try {
        setInitialPrompt(generationPrompt);
        let allGeneratedFrames: string[] = [];
        const characterImage = selectedCharacterIndex !== null ? cast[selectedCharacterIndex] : null;
        const totalFramesPerScene = sceneDuration * fps;

        for (let i = 0; i < numKeyScenes; i++) {
          for (let j = 0; j < totalFramesPerScene; j++) {
            const parts = [];
            if (characterImage) {
              parts.push({
                inlineData: { data: characterImage.split(',')[1], mimeType: 'image/png' },
              });
            }

            let framePrompt = `Key Scene ${i + 1} of ${numKeyScenes}. Frame ${j + 1} of ${totalFramesPerScene} in a ${sceneDuration}-second animation at ${fps} FPS of: ${generationPrompt}. The character provided should be included if it makes sense. Ensure smooth, continuous motion from the previous frame to the next for this scene.`;
            if (selectedStyle) {
              framePrompt += ` IMPORTANT: Draw this in the following style: ${selectedStyle}.`;
            }
            framePrompt += ` CRITICAL: Do not include any text, letters, or numbers in the image.`;
            parts.push({text: framePrompt});

            const response = await ai.models.generateContent({
              model: selectedModel,
              contents: {parts},
              config: {systemInstruction: INFOGRAPHIC_SYSTEM_INSTRUCTION},
            });

            let generatedImageData: string | undefined;
            for (const part of response.candidates?.[0]?.content?.parts || []) {
              if (part.inlineData) {
                generatedImageData = part.inlineData.data;
                break;
              }
            }

            if (generatedImageData) {
              allGeneratedFrames.push(`data:image/png;base64,${generatedImageData}`);
            } else {
              throw new Error(`Frame generation failed at Scene ${i + 1}, Frame ${j + 1}. It might be blocked by safety settings.`);
            }
          }
        }

        setFrames(allGeneratedFrames);
        const newDurations = Array(allGeneratedFrames.length).fill(1000 / fps);
        setFrameDurations(newDurations);
        setCurrentFrameIndex(0);
        const newHistory = {};
        const newHistoryIndex = {};
        allGeneratedFrames.forEach((frame, index) => {
          if (frame) {
            newHistory[index] = [frame];
            newHistoryIndex[index] = 0;
          }
        });
        setHistory(newHistory);
        setHistoryIndex(newHistoryIndex);

    } catch (error) {
      console.error('Error generating animation:', error);
      setErrorMessage(
        parseError(error.message) || 'An unexpected error occurred during animation generation.',
      );
      setShowErrorModal(true);
    } finally {
        setIsLoading(false);
    }
  }


  const addFrame = () => {
    const currentFrameData = frames[currentFrameIndex];
    const newFrames = [...frames];
    newFrames.splice(currentFrameIndex + 1, 0, currentFrameData);
    setFrames(newFrames);

    const newDurations = [...frameDurations];
    newDurations.splice(currentFrameIndex + 1, 0, 1000 / fps);
    setFrameDurations(newDurations);

    setCurrentFrameIndex(currentFrameIndex + 1);
  };

  const selectFrame = (index: number) => {
    if (isPlaying) setIsPlaying(false);
    setCurrentFrameIndex(index);
  };

  const deleteFrame = (index: number) => {
    if (frames.length <= 1) {
      setFrames([null]);
      setFrameDurations([1000/fps]);
      setCurrentFrameIndex(0);
      return;
    }
    const newFrames = frames.filter((_, i) => i !== index);
    setFrames(newFrames);

    const newDurations = frameDurations.filter((_, i) => i !== index);
    setFrameDurations(newDurations);

    if (currentFrameIndex >= index) {
      setCurrentFrameIndex(Math.max(0, currentFrameIndex - 1));
    }
  };

  const togglePlay = () => setIsPlaying(!isPlaying);

  const closeErrorModal = () => setShowErrorModal(false);

  const handleFrameDurationChange = (e: ChangeEvent<HTMLInputElement>) => {
    const newDuration = Number(e.target.value);
    if (newDuration > 0) {
        const newDurations = [...frameDurations];
        newDurations[currentFrameIndex] = newDuration;
        setFrameDurations(newDurations);
    }
  };

  const handleGenerateNarration = async () => {
    const validFrames = frames.filter((f): f is string => f !== null);
    if (validFrames.length === 0) {
      setErrorMessage('Please create an animation before generating narration.');
      setShowErrorModal(true);
      return;
    }
    setIsGeneratingNarration(true);
    try {
      // 1. Describe frames to get context
      const descriptionParts: any[] = [
        {
          text: 'Describe this sequence of images as a short, simple story for an animation. Focus on the main action and mood. This description will be used to create a narration script. Do not describe the style, only the content.',
        },
      ];
      validFrames.forEach((frame) => {
        descriptionParts.push({
          inlineData: {data: frame.split(',')[1], mimeType: 'image/png'},
        });
      });

      const descriptionResponse = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: {parts: descriptionParts},
      });
      // Fix: Per Gemini API guidelines, .text is a property, not a method.
      const description = descriptionResponse.text ?? '';

      // 2. Generate a script from the description
      const scriptPrompt = `Based on the following scene description, write a short, one or two-sentence narration script in English. Include simple onomatopoeia (like "whoosh", "pop", "ding") where appropriate to make it lively. The script should be suitable for a general audience. Scene description: ${description}. The original animation idea was: ${initialPrompt}`;
      const scriptResponse = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: scriptPrompt,
      });
      // Fix: Per Gemini API guidelines, .text is a property, not a method.
      const script = (scriptResponse.text ?? '').trim();
      if (!script) {
        throw new Error('Failed to generate a narration script.');
      }

      // 3. Generate audio from the script using TTS
      const ttsResponse = await ai.models.generateContent({
        model: 'gemini-2.5-flash-preview-tts',
        contents: [{parts: [{text: `Read this cheerfully: ${script}`}]}],
        config: {
          responseModalities: [Modality.AUDIO],
          speechConfig: {
            voiceConfig: {prebuiltVoiceConfig: {voiceName: 'Kore'}},
          },
        },
      });

      const base64Audio =
        ttsResponse.candidates?.[0]?.content?.parts?.[0]?.inlineData?.data;
      if (!base64Audio) {
        throw new Error('Audio data not found in the response.');
      }

      // 4. Create a playable WAV blob and set it in state
      const pcmData = decode(base64Audio);
      const wavBlob = createWavBlob(pcmData, 24000, 1);
      const audioUrl = URL.createObjectURL(wavBlob);
      setNarrationAudio(audioUrl);
    } catch (error) {
      console.error('Narration generation failed:', error);
      setErrorMessage(
        parseError(error.message) || 'Failed to generate narration.',
      );
      setShowErrorModal(true);
    } finally {
      setIsGeneratingNarration(false);
    }
  };

  const handleExportGif = async () => {
    if (isExporting) return;
    const framesToExport = frames.filter(
      (frame): frame is string => frame !== null,
    );
    if (framesToExport.length === 0) {
      alert('There are no frames to export.');
      return;
    }

    setIsExporting(true);
    setShowGifExportModal(false);

    try {
      const gif = new GIF({
        workers: 2,
        quality: gifQuality,
        workerScript:
          'https://cdnjs.cloudflare.com/ajax/libs/gif.js/0.2.0/gif.worker.js',
        width: ASPECT_RATIOS[aspectRatio].width,
        height: ASPECT_RATIOS[aspectRatio].height,
      });

      const imagePromises = framesToExport.map((dataUrl) => {
        return new Promise<HTMLImageElement>((resolve, reject) => {
          const img = new Image();
          img.onload = () => resolve(img);
          img.onerror = reject;
          img.src = dataUrl;
        });
      });

      const loadedImages = await Promise.all(imagePromises);

      for (let i = 0; i < loadedImages.length; i++) {
        const image = loadedImages[i];
        const delay = frameDurations[i] || (1000 / fps);
        gif.addFrame(image, { delay });
      }

      gif.on('finished', (blob) => {
        const url = URL.createObjectURL(blob);
        const a = document.createElement('a');
        a.href = url;
        a.download = 'animation.gif';
        document.body.appendChild(a);
        a.click();
        document.body.removeChild(a);
        URL.revokeObjectURL(url);
        setIsExporting(false);
      });

      gif.render();
    } catch (error) {
      console.error('GIF export failed:', error);
      setErrorMessage('An error occurred while exporting the GIF.');
      setShowErrorModal(true);
      setIsExporting(false);
    }
  };

  const handleExportFrames = async () => {
    if (isExporting) return;
    const framesToExport = frames.filter((frame): frame is string =>
      Boolean(frame),
    );
    if (framesToExport.length === 0) {
      alert('There are no frames to export.');
      return;
    }

    setIsExporting(true);
    setShowExportFramesModal(false);

    try {
      const zip = new JSZip();
      const format = exportFormat;
      const mimeType = `image/${format === 'jpg' ? 'jpeg' : 'png'}`;

      for (let i = 0; i < framesToExport.length; i++) {
        const frameDataUrl = framesToExport[i];
        let processedDataUrl = frameDataUrl;

        if (format === 'jpg') {
          processedDataUrl = await new Promise<string>((resolve, reject) => {
            const img = new Image();
            img.onload = () => {
              const canvas = document.createElement('canvas');
              canvas.width = img.width;
              canvas.height = img.height;
              const ctx = canvas.getContext('2d');
              if (!ctx) return reject(new Error('Canvas context unavailable'));
              ctx.fillStyle = '#FFFFFF'; // Add white background for JPG
              ctx.fillRect(0, 0, canvas.width, canvas.height);
              ctx.drawImage(img, 0, 0);
              resolve(canvas.toDataURL(mimeType, 0.9));
            };
            img.onerror = reject;
            img.src = frameDataUrl;
          });
        }

        const base64Data = processedDataUrl.split(',')[1];
        zip.file(
          `frame_${String(i + 1).padStart(3, '0')}.${format}`,
          base64Data,
          {base64: true},
        );
      }

      const blob = await zip.generateAsync({type: 'blob'});
      const a = document.createElement('a');
      a.href = URL.createObjectURL(blob);
      a.download = `animation_frames.zip`;
      document.body.appendChild(a);
      a.click();
      document.body.removeChild(a);
      URL.revokeObjectURL(a.href);
    } catch (error) {
      console.error('Frame export failed:', error);
      setErrorMessage(
        `An error occurred while exporting frames as ${exportFormat.toUpperCase()}.`,
      );
      setShowErrorModal(true);
    } finally {
      setIsExporting(false);
    }
  };

  const handleExportMp4 = async () => {
    if (isExporting || isExportingMp4) return;
    const framesToExport = frames.filter(
      (frame): frame is string => frame !== null,
    );
    if (framesToExport.length === 0) {
      alert('There are no frames to export.');
      return;
    }

    setIsExportingMp4(true);

    try {
      const canvas = document.createElement('canvas');
      canvas.width = ASPECT_RATIOS[aspectRatio].width;
      canvas.height = ASPECT_RATIOS[aspectRatio].height;
      const ctx = canvas.getContext('2d');
      if (!ctx) {
        throw new Error('Could not get canvas context.');
      }

      const videoStream = canvas.captureStream(fps);
      let finalStream: MediaStream = videoStream;

      // If narration exists, mix it in
      if (narrationAudio) {
        const audioContext = new (window.AudioContext || (window as any).webkitAudioContext)();
        const response = await fetch(narrationAudio);
        const arrayBuffer = await response.arrayBuffer();
        const audioBuffer = await audioContext.decodeAudioData(arrayBuffer);
        const destination = audioContext.createMediaStreamDestination();
        const source = audioContext.createBufferSource();
        source.buffer = audioBuffer;
        source.connect(destination);
        const audioStream = destination.stream;
        finalStream = new MediaStream([
            ...videoStream.getVideoTracks(),
            ...audioStream.getAudioTracks()
        ]);
        source.start(); // Start playing the audio into the stream
      }

      const mimeType = 'video/webm; codecs=vp9,opus';
      if (!MediaRecorder.isTypeSupported(mimeType)) {
        throw new Error(`${mimeType} is not supported in this browser.`);
      }
      const recorder = new MediaRecorder(finalStream, {mimeType});

      const chunks: Blob[] = [];
      recorder.ondataavailable = (e) => {
        if (e.data.size > 0) {
          chunks.push(e.data);
        }
      };

      recorder.onstop = () => {
        const blob = new Blob(chunks, {type: 'video/mp4'});
        const url = URL.createObjectURL(blob);
        const a = document.createElement('a');
        a.href = url;
        a.download = 'animation.mp4';
        document.body.appendChild(a);
        a.click();
        document.body.removeChild(a);
        URL.revokeObjectURL(url);
        setIsExportingMp4(false);
      };

      const imagePromises = framesToExport.map(
        (dataUrl) =>
          new Promise<HTMLImageElement>((resolve, reject) => {
            const img = new Image();
            img.onload = () => resolve(img);
            img.onerror = reject;
            img.src = dataUrl;
          }),
      );
      const loadedImages = await Promise.all(imagePromises);

      recorder.start();

      let frameIndex = 0;
      const intervalId = setInterval(() => {
        if (frameIndex >= loadedImages.length) {
          clearInterval(intervalId);
          recorder.stop();
          return;
        }
        const image = loadedImages[frameIndex];
        ctx.fillStyle = '#FFFFFF';
        ctx.fillRect(0, 0, canvas.width, canvas.height);
        ctx.drawImage(image, 0, 0, canvas.width, canvas.height);
        frameIndex++;
      }, 1000 / fps);
    } catch (error) {
      console.error('MP4 export failed:', error);
      setErrorMessage(`An error occurred while exporting the MP4: ${error.message}`);
      setShowErrorModal(true);
      setIsExportingMp4(false);
    }
  };

  const performAspectRatioChange = async (newRatio: AspectRatio) => {
    const currentFrameData = frames[currentFrameIndex];
    setShowAspectRatioConfirm(false);

    if (!currentFrameData) {
      setAspectRatio(newRatio);
      setFrames([null]);
      setFrameDurations([1000/fps]);
      setCurrentFrameIndex(0);
      setHistory({});
      setHistoryIndex({});
      setNarrationAudio(null);
      setTargetAspectRatio(null);
      return;
    }

    setIsRecomposing(true);
    setErrorMessage('');

    try {
      const parts = [
        {
          inlineData: {
            data: currentFrameData.split(',')[1],
            mimeType: 'image/png',
          },
        },
        {
          text: `Re-compose this image to fit a ${newRatio} aspect ratio. Do not stretch or distort the main subject; instead, expand the background scenery to fit the new dimensions while maintaining the subject's proportions.`,
        },
      ];

      const response = await ai.models.generateContent({
        model: selectedModel,
        contents: {parts},
        config: {systemInstruction: RECOMPOSE_SYSTEM_INSTRUCTION},
      });

      let generatedImageData: string | undefined;
      for (const part of response.candidates?.[0]?.content?.parts || []) {
        if (part.inlineData) {
          generatedImageData = part.inlineData.data;
          break;
        }
      }

      if (generatedImageData) {
        const imageUrl = `data:image/png;base64,${generatedImageData}`;
        setAspectRatio(newRatio);
        const newFrames = Array(frames.length).fill(null);
        newFrames[0] = imageUrl;

        setFrames(newFrames);
        setFrameDurations(Array(frames.length).fill(1000 / fps));
        setCurrentFrameIndex(0);
        setHistory({0: [imageUrl]});
        setHistoryIndex({0: 0});
        setNarrationAudio(null);
      } else {
        throw new Error(
          'Failed to re-compose the image. The model did not return a valid image.',
        );
      }
    } catch (error) {
      console.error('Error during re-composition:', error);
      setErrorMessage(
        parseError(error.message) ||
          'An error occurred during re-composition.',
      );
      setShowErrorModal(true);
    } finally {
      setIsRecomposing(false);
      setTargetAspectRatio(null);
    }
  };

  const handleAspectRatioChange = (newRatio: AspectRatio) => {
    if (newRatio === aspectRatio) return;

    const hasContent = frames.some((f) => f !== null);
    if (hasContent) {
      setTargetAspectRatio(newRatio);
      setShowAspectRatioConfirm(true);
    } else {
      // If there's no content, just change the aspect ratio without AI call
      setAspectRatio(newRatio);
      setFrames([null]);
      setFrameDurations([1000 / fps]);
      setCurrentFrameIndex(0);
      setHistory({});
      setHistoryIndex({});
      setNarrationAudio(null);
    }
  };

  const handleSaveCharacter = () => {
    const canvas = canvasRef.current;
    if (canvas) {
      const dataUrl = canvas.toDataURL('image/png');
      const isEmpty = !frames[currentFrameIndex];
      if (!isEmpty) {
        setCast([...cast, dataUrl]);
      } else {
        setErrorMessage('Cannot save an empty canvas as a character.');
        setShowErrorModal(true);
      }
    }
  };

  const handleSelectCharacter = (index: number) => {
    if (selectedCharacterIndex === index) {
      setSelectedCharacterIndex(null); // Deselect if already selected
    } else {
      setSelectedCharacterIndex(index);
    }
  };

  const handleRemoveCharacter = (
    e: React.MouseEvent,
    indexToRemove: number,
  ) => {
    e.stopPropagation(); // Prevent selection when clicking remove button
    setCast(cast.filter((_, index) => index !== indexToRemove));
    if (selectedCharacterIndex === indexToRemove) {
      setSelectedCharacterIndex(null);
    }
  };


  useEffect(() => {
    const preventTouchDefault = (e: TouchEvent) => {
      if (isInteracting.current) e.preventDefault();
    };
    const canvas = canvasRef.current;
    if (canvas) {
      canvas.addEventListener('touchstart', preventTouchDefault, {
        passive: false,
      });
      canvas.addEventListener('touchmove', preventTouchDefault, {
        passive: false,
      });
    }
    return () => {
      if (canvas) {
        canvas.removeEventListener('touchstart', preventTouchDefault);
        canvas.removeEventListener('touchmove', preventTouchDefault);
      }
    };
  }, []);

  const hasContent = frames.some(f => f !== null);

  const canUndo = (historyIndex[currentFrameIndex] ?? 0) > 0;
  const canRedo =
    (historyIndex[currentFrameIndex] ?? -1) <
    (history[currentFrameIndex]?.length ?? 0) - 1;

  const currentCanvasDimensions = ASPECT_RATIOS[aspectRatio];
  const currentThumbnailDimensions = THUMBNAIL_DIMS[aspectRatio];

  const previewStylePrompt = hoveredStyle || selectedStyle;
  const previewStyleObject = ANIMATION_STYLES.find(s => s.prompt === previewStylePrompt);


  return (
    <>
      <div className="min-h-screen notebook-paper-bg text-gray-900 flex flex-col justify-start items-center">
        <main className="container mx-auto px-3 sm:px-6 py-5 sm:py-10 max-w-7xl w-full">
          {/* Header */}
          <div className="flex flex-col sm:flex-row sm:justify-between sm:items-end mb-4 sm:mb-6 gap-2">
            <div>
              <h1 className="text-2xl sm:text-3xl font-bold mb-0 leading-tight font-mega">
                Gemini 애니메이션 스튜디오
              </h1>
              <p className="text-sm sm:text-base text-gray-500 mt-1">
                <a
                  className="underline"
                  href="https://ai.google.dev/gemini-api/docs/image-generation"
                  target="_blank"
                  rel="noopener noreferrer">
                  Gemini 네이티브 이미지 생성으로 제작
                </a>
              </p>
            </div>
          </div>

          {/* Main Content: Two-column layout for large screens */}
          <div className="w-full flex flex-col lg:flex-row lg:gap-8">
            {/* Left Column: Canvas, Prompt, Cast, Timeline */}
            <div className="w-full lg:w-1/2 flex flex-col gap-6">
            <div
                className="w-full mx-auto relative bg-white overflow-hidden"
                style={{
                  aspectRatio: aspectRatio.replace(':', '/'),
                }}>
                {isRecomposing && (
                  <div className="absolute inset-0 bg-white/80 flex flex-col items-center justify-center z-20 rounded-md">
                    <LoaderCircle className="w-12 h-12 animate-spin text-gray-800" />
                    <p className="mt-4 text-gray-700 font-medium text-center">
                      새로운 종횡비로 재구성 중...
                    </p>
                  </div>
                )}
                <div className="absolute inset-0 bg-[conic-gradient(#ccc_25%,#eee_0_50%,#ccc_0_75%,#eee_0)] bg-[length:20px_20px] rounded-md"></div>
                <canvas
                  ref={canvasRef}
                  width={currentCanvasDimensions.width}
                  height={currentCanvasDimensions.height}
                  onMouseDown={startInteraction}
                  onMouseMove={moveInteraction}
                  onMouseUp={stopInteraction}
                  onMouseLeave={stopInteraction}
                  onTouchStart={startInteraction}
                  onTouchMove={moveInteraction}
                  onTouchEnd={stopInteraction}
                  className={`relative w-full h-full touch-none z-10 border-2 border-gray-400 rounded-md ${
                    activeTool === 'pen' ? 'cursor-crosshair' : activeTool === 'pan' ? 'cursor-grab' : 'cursor-auto'
                  }`}
                />
              </div>

              <form onSubmit={handleSubmit} className="w-full">
                <div className="relative">
                  <input
                    type="text"
                    value={prompt}
                    onChange={(e) => setPrompt(e.target.value)}
                    placeholder="현재 프레임 편집 또는 스타일 적용"
                    className="w-full p-3 sm:p-4 pr-12 sm:pr-14 text-sm sm:text-base border-2 border-black bg-white text-gray-800 shadow-sm focus:ring-2 focus:ring-gray-200 focus:outline-none transition-all font-mono"
                  />
                  <button
                    type="submit"
                    disabled={isLoading}
                    className="absolute right-3 sm:right-4 top-1/2 -translate-y-1/2 p-1.5 sm:p-2 rounded-none bg-black text-white hover:cursor-pointer hover:bg-gray-800 disabled:bg-gray-300 disabled:cursor-not-allowed transition-colors">
                    {isLoading ? (
                      <LoaderCircle
                        className="w-5 sm:w-6 h-5 sm:h-6 animate-spin"
                        aria-label="로딩"
                      />
                    ) : (
                      <SendHorizontal
                        className="w-5 sm:w-6 h-5 sm:h-6"
                        aria-label="제출"
                      />
                    )}
                  </button>
                </div>
              </form>

              {cast.length > 0 && (
                <div className="w-full p-3 bg-gray-200/60 rounded-lg shadow-sm">
                  <h3 className="text-sm font-bold text-gray-800 mb-2">
                    나의 캐릭터
                  </h3>
                  <div className="flex gap-3 overflow-x-auto p-2">
                    {cast.map((charSrc, index) => (
                      <div
                        key={index}
                        onClick={() => handleSelectCharacter(index)}
                        className={`relative shrink-0 cursor-pointer rounded-md p-1 transition-all ${
                          selectedCharacterIndex === index
                            ? 'bg-blue-500'
                            : 'bg-white'
                        }`}>
                        <img
                          src={charSrc}
                          alt={`캐릭터 ${index + 1}`}
                          className="w-20 h-20 object-contain rounded-sm bg-white"
                        />
                        <button
                          onClick={(e) => handleRemoveCharacter(e, index)}
                          className="absolute -top-2 -right-2 w-5 h-5 bg-red-500 text-white rounded-full flex items-center justify-center shadow transition-transform hover:scale-110"
                          aria-label={`캐릭터 ${index + 1} 삭제`}>
                          <X className="w-3 h-3" />
                        </button>
                      </div>
                    ))}
                  </div>
                </div>
              )}

              {/* Timeline */}
              <div className="w-full p-3 bg-gray-200/60 rounded-lg shadow-sm">
                <div className="flex items-center gap-2 mb-3">
                    <Video className="w-5 h-5 text-gray-700" />
                    <h3 className="text-sm font-bold text-gray-800">타임라인</h3>
                </div>
                <div className="flex flex-wrap items-center gap-3 p-2 bg-gray-100 rounded-md mb-3">
                    <button
                      onClick={togglePlay}
                      className="w-10 h-10 rounded-full flex items-center justify-center bg-white shadow-sm transition-all hover:bg-gray-50 hover:scale-110"
                      aria-label={isPlaying ? '일시정지' : '재생'}>
                      {isPlaying ? (
                        <Pause className="w-5 h-5 text-gray-700" />
                      ) : (
                        <Play className="w-5 h-5 text-gray-700" />
                      )}
                    </button>
                    <button
                      onClick={addFrame}
                      className="flex-grow flex items-center justify-center gap-2 h-10 px-4 rounded-full bg-white shadow-sm transition-all hover:bg-gray-50 text-gray-700 font-medium text-sm">
                      <Plus className="w-4 h-4" />새 프레임
                    </button>
                    <button onClick={handleSaveCharacter} disabled={!frames[currentFrameIndex]} className="flex-grow flex items-center justify-center gap-2 h-10 px-4 rounded-full bg-white shadow-sm transition-all hover:bg-gray-50 text-gray-800 font-medium text-sm disabled:bg-gray-200 disabled:cursor-not-allowed disabled:text-gray-500">
                      <UserPlus className="w-5 h-5" /> 캐릭터 저장
                    </button>
                    <div className="flex items-center gap-2">
                        <label htmlFor="frame-duration" className="text-xs sm:text-sm font-medium text-gray-700 whitespace-nowrap">시간:</label>
                        <input
                            id="frame-duration"
                            type="number"
                            value={frameDurations[currentFrameIndex] ?? Math.round(1000 / fps)}
                            onChange={handleFrameDurationChange}
                            className="w-20 p-1 text-sm border border-gray-300 rounded-md"
                            min="10"
                            step="10"
                        />
                        <span className="text-sm text-gray-600">ms</span>
                    </div>
                </div>
                <div className="flex gap-2 overflow-x-auto p-2 bg-white/80 rounded-md min-h-[100px] items-center">
                  {frames.map((frame, index) => (
                    <div
                      key={index}
                      className="relative shrink-0"
                      onClick={() => selectFrame(index)}>
                      <canvas
                        ref={(el) => (thumbnailRefs.current[index] = el)}
                        width={120}
                        height={120}
                        className={`bg-white cursor-pointer rounded-sm ${
                          currentFrameIndex === index
                            ? 'ring-2 ring-blue-500 ring-offset-2'
                            : 'ring-1 ring-gray-300'
                        }`}
                        style={{
                            width: `${currentThumbnailDimensions.width}px`,
                            height: `${currentThumbnailDimensions.height}px`,
                        }}
                      />
                      <span className="absolute bottom-1 right-1.5 text-xs font-mono bg-black/50 text-white px-1 rounded-sm">
                        {index + 1}
                      </span>
                      {frames.length > 1 && (
                        <button
                          onClick={(e) => {
                            e.stopPropagation();
                            deleteFrame(index);
                          }}
                          className="absolute -top-2 -right-2 w-5 h-5 bg-red-500 text-white rounded-full flex items-center justify-center shadow transition-transform hover:scale-110"
                          aria-label={`프레임 ${index + 1} 삭제`}>
                          <X className="w-3 h-3" />
                        </button>
                      )}
                    </div>
                  ))}
                </div>
              </div>
            </div>

            {/* Right Column: All tools and settings */}
            <div className="w-full lg:w-1/2 flex flex-col gap-6 mt-6 lg:mt-0">
              <div className="w-full p-3 bg-gray-200/60 rounded-lg shadow-sm">
                <div className="flex items-center gap-2 mb-3">
                  <Settings2 className="w-5 h-5 text-gray-700" />
                  <h3 className="text-sm font-bold text-gray-800">도구</h3>
                </div>
                <div className="grid grid-cols-2 sm:grid-cols-3 lg:grid-cols-2 gap-3">
                  <div className="relative col-span-2">
                    <select
                      value={selectedModel}
                      onChange={(e) => setSelectedModel(e.target.value)}
                      className="w-full h-10 rounded-full bg-white pl-3 pr-8 text-sm text-gray-700 shadow-sm transition-all hover:bg-gray-50 focus:outline-none focus:ring-2 focus:ring-gray-400 appearance-none border-2 border-white"
                      aria-label="Gemini 모델 선택">
                      <option value="gemini-2.5-flash-image">2.5 Flash</option>
                      <option value="gemini-3-pro-image-preview">3.0 Pro</option>
                    </select>
                    <div className="pointer-events-none absolute inset-y-0 right-0 flex items-center px-3 text-gray-700">
                      <ChevronDown className="w-5 h-5" />
                    </div>
                  </div>

                  <div className="col-span-2 p-2 bg-gray-200 rounded-lg">
                    <h4 className="text-xs font-bold text-gray-600 mb-2 pl-1">캔버스 도구</h4>
                    <div className="grid grid-cols-2 gap-2">
                        <button onClick={() => setActiveTool('pen')} className={`flex items-center justify-center gap-2 h-10 px-4 rounded-full shadow-sm transition-all ${activeTool === 'pen' ? 'bg-blue-500 text-white' : 'bg-white hover:bg-gray-50 text-gray-700'}`}>
                            <PenTool className="w-4 h-4" /> 펜
                        </button>
                        <button onClick={() => setActiveTool('pan')} className={`flex items-center justify-center gap-2 h-10 px-4 rounded-full shadow-sm transition-all ${activeTool === 'pan' ? 'bg-blue-500 text-white' : 'bg-white hover:bg-gray-50 text-gray-700'}`}>
                            <Hand className="w-4 h-4" /> 이동
                        </button>
                        <button onClick={() => setActiveTool('eraser')} className={`flex items-center justify-center gap-2 h-10 px-4 rounded-full shadow-sm transition-all ${activeTool === 'eraser' ? 'bg-blue-500 text-white' : 'bg-white hover:bg-gray-50 text-gray-700'}`}>
                            <Eraser className="w-4 h-4" /> 지우개
                        </button>
                        <button onClick={() => setActiveTool('ai-eraser')} className={`flex items-center justify-center gap-2 h-10 px-4 rounded-full shadow-sm transition-all ${activeTool === 'ai-eraser' ? 'bg-blue-500 text-white' : 'bg-white hover:bg-gray-50 text-gray-700'}`}>
                            <Sparkles className="w-4 h-4" /> AI 지우개
                        </button>
                    </div>
                  </div>

                  <div className="col-span-2 p-2 bg-gray-200 rounded-lg">
                    <h4 className="text-xs font-bold text-gray-600 mb-2 pl-1">캔버스 제어</h4>
                    <div className="flex items-center gap-2 mt-2">
                        <button onClick={() => setZoom(z => Math.max(0.1, z - 0.1))} className="w-10 h-10 flex-shrink-0 flex items-center justify-center rounded-full bg-white shadow-sm hover:bg-gray-50"><Minus className="w-4 h-4 text-gray-700"/></button>
                        <div className="w-full text-center text-sm font-mono text-gray-700 bg-white rounded-full h-10 flex items-center justify-center shadow-sm cursor-pointer" onClick={() => {setZoom(1); setPan({x:0, y:0})}}>
                            {(zoom * 100).toFixed(0)}%
                        </div>
                        <button onClick={() => setZoom(z => Math.min(5, z + 0.1))} className="w-10 h-10 flex-shrink-0 flex items-center justify-center rounded-full bg-white shadow-sm hover:bg-gray-50"><Plus className="w-4 h-4 text-gray-700"/></button>
                    </div>
                  </div>

                  <div className="col-span-2 p-2 bg-gray-200 rounded-lg">
                    <h4 className="text-xs font-bold text-gray-600 mb-2 pl-1">애니메이션 설정</h4>
                    <div>
                        <label htmlFor="fps-slider" className="block text-sm font-medium text-gray-700">
                            기본 FPS: {fps}
                        </label>
                        <input
                            id="fps-slider"
                            type="range"
                            min="1"
                            max="30"
                            value={fps}
                            onChange={(e) => setFps(Number(e.target.value))}
                            className="w-full h-2 bg-gray-300 rounded-lg appearance-none cursor-pointer"
                        />
                        <p className="text-xs text-gray-500 mt-1">
                            새 프레임 및 MP4 내보내기에 사용됩니다.
                        </p>
                    </div>
                  </div>

                  <button onClick={handleUndo} disabled={!canUndo} className="flex items-center justify-center gap-2 h-10 px-4 rounded-full bg-white shadow-sm transition-all hover:bg-gray-50 disabled:opacity-50 disabled:cursor-not-allowed text-gray-700 font-medium text-sm">
                      <RotateCcw className="w-4 h-4" />실행 취소
                  </button>
                  <button onClick={handleRedo} disabled={!canRedo} className="flex items-center justify-center gap-2 h-10 px-4 rounded-full bg-white shadow-sm transition-all hover:bg-gray-50 disabled:opacity-50 disabled:cursor-not-allowed text-gray-700 font-medium text-sm">
                      <RotateCw className="w-4 h-4" />다시 실행
                  </button>
                   <button type="button" className="flex items-center justify-center gap-2 h-10 px-4 rounded-full bg-white shadow-sm transition-all hover:bg-gray-50 text-gray-700 font-medium text-sm" onClick={() => (fileInputRef.current as HTMLInputElement)?.click()}>
                      <Upload className="w-4 h-4" />사진
                   </button>
                   <input
                      ref={fileInputRef}
                      type="file"
                      accept="image/png, image/jpeg"
                      className="hidden"
                      onChange={handleImageUpload}
                    />
                   <button type="button" onClick={clearCanvas} className="flex items-center justify-center gap-2 h-10 px-4 rounded-full bg-white shadow-sm transition-all hover:bg-gray-50 text-gray-700 font-medium text-sm">
                      <Trash2 className="w-4 h-4" />지우기
                   </button>
                   <button type="button" className="col-span-2 flex items-center justify-center gap-2 h-10 px-4 rounded-full bg-white shadow-sm transition-all hover:bg-gray-50 text-gray-700 font-medium text-sm" onClick={openColorPicker}>
                        펜 색상
                        <div className="w-6 h-6 rounded-full border-2 border-white shadow-sm" style={{ backgroundColor: penColor }}></div>
                   </button>
                   <input
                      ref={colorInputRef}
                      type="color"
                      value={penColor}
                      onChange={handleColorChange}
                      className="opacity-0 absolute w-px h-px"
                      aria-label="펜 색상 선택"
                    />
                </div>
              </div>

              <div className="w-full p-3 bg-gray-200/60 rounded-lg shadow-sm">
                <div className="flex items-center justify-between gap-2 mb-2">
                  <div className="flex items-center gap-2">
                    <Palette className="w-5 h-5 text-gray-700" />
                    <h3 className="text-sm font-bold text-gray-800">
                      스타일 팔레트
                    </h3>
                  </div>
                  {referenceImage && (
                  <div className="relative w-16">
                    <img
                      src={referenceImage}
                      alt="참고 이미지"
                      className="rounded-md border-2 border-gray-400"
                    />
                    <button
                      onClick={() => setReferenceImage(null)}
                      className="absolute -top-2 -right-2 w-6 h-6 bg-red-500 text-white rounded-full flex items-center justify-center shadow-lg hover:scale-110 transition-transform"
                      aria-label="참고 이미지 삭제">
                      <X size={16} />
                    </button>
                  </div>
                  )}
                </div>

                {/* Style Preview Area */}
                <div className="mb-3 p-2 bg-white/70 rounded-md border border-gray-300 min-h-[120px] flex items-center justify-center">
                    {previewStyleObject ? (
                        <img 
                            src={previewStyleObject.previewImage} 
                            alt={`${previewStyleObject.name} 스타일 미리보기`}
                            className="w-28 h-28 object-contain rounded-sm"
                        />
                    ) : (
                        <p className="text-xs text-center text-gray-500 p-4">
                            스타일 위로 마우스를 가져가 미리보세요
                        </p>
                    )}
                </div>

                {referenceImage && (
                    <p className="text-xs text-center text-gray-600 mb-2 bg-blue-100 border border-blue-300 p-2 rounded-md">
                        사진이 로드되었습니다. 아래에서 스타일을 선택하여 변환하세요.
                    </p>
                )}
                <div className="grid grid-cols-3 sm:grid-cols-4 lg:grid-cols-3 gap-2" onMouseLeave={() => setHoveredStyle(null)}>
                  {ANIMATION_STYLES.map((style) => (
                    <button
                      key={style.name}
                      onClick={() => referenceImage ? handleStyleApply(style.prompt) : handleStyleSelect(style.prompt)}
                      onMouseEnter={() => setHoveredStyle(style.prompt)}
                      disabled={isLoading}
                      className={`flex flex-col items-center justify-center gap-2 p-2 h-20 rounded-md bg-white shadow-sm border hover:bg-gray-100 hover:border-blue-500 hover:text-blue-600 transition-all disabled:opacity-50 disabled:cursor-not-allowed ${selectedStyle === style.prompt ? 'ring-2 ring-blue-500 border-blue-500' : 'border-gray-300'}`}>
                      <style.icon className="w-6 h-6" />
                      <span className="text-xs font-medium text-center">
                        {style.name}
                      </span>
                    </button>
                  ))}
                </div>
              </div>

              <div className="w-full p-3 bg-gray-200/60 rounded-lg shadow-sm space-y-4">
                  <button onClick={handleGenerateNarration} disabled={isGeneratingNarration || frames.every(f => f === null)} className="w-full flex items-center justify-center gap-2 h-10 px-4 rounded-full bg-white shadow-sm transition-all hover:bg-gray-50 text-gray-700 font-medium text-sm disabled:bg-gray-200 disabled:cursor-not-allowed">
                      {isGeneratingNarration ? (<><LoaderCircle className="w-4 h-4 animate-spin" />생성 중...</>) : (<><Sparkles className="w-4 h-4" />내레이션 생성</>)}
                  </button>
                   {narrationAudio && (
                     <div className="flex items-center gap-2 p-2 rounded-md border border-gray-300 bg-white/50">
                        <Music2 className="w-5 h-5 text-gray-600 shrink-0" />
                        <audio ref={audioRef} src={narrationAudio} controls className="w-full h-8"></audio>
                        <button onClick={() => setNarrationAudio(null)} className="p-2 rounded-full hover:bg-gray-200 transition-colors">
                            <Trash2 className="w-5 h-5 text-red-500" aria-label="내레이션 삭제" />
                        </button>
                     </div>
                  )}
              </div>

              <div className="w-full p-3 bg-gray-200/60 rounded-lg shadow-sm space-y-4">
                  <div>
                    <span className="text-sm font-medium text-gray-700">종횡비:</span>
                    <div className="flex items-center gap-1 p-1 bg-gray-200 rounded-full mt-1">
                      <button onClick={() => handleAspectRatioChange('16:9')} className={`w-1/3 flex items-center justify-center gap-1.5 px-3 py-1.5 text-xs sm:text-sm rounded-full transition-colors ${ aspectRatio === '16:9' ? 'bg-white shadow-sm text-gray-800' : 'bg-transparent text-gray-600 hover:bg-gray-300'}`}>
                        <RectangleHorizontal className="w-4 h-4" /> 가로
                      </button>
                      <button onClick={() => handleAspectRatioChange('9:16')} className={`w-1/3 flex items-center justify-center gap-1.5 px-3 py-1.5 text-xs sm:text-sm rounded-full transition-colors ${ aspectRatio === '9:16' ? 'bg-white shadow-sm text-gray-800' : 'bg-transparent text-gray-600 hover:bg-gray-300'}`}>
                        <RectangleVertical className="w-4 h-4" /> 세로
                      </button>
                      <button onClick={() => handleAspectRatioChange('1:1')} className={`w-1/3 flex items-center justify-center gap-1.5 px-3 py-1.5 text-xs sm:text-sm rounded-full transition-colors ${ aspectRatio === '1:1' ? 'bg-white shadow-sm text-gray-800' : 'bg-transparent text-gray-600 hover:bg-gray-300'}`}>
                        <Square className="w-4 h-4" /> 정사각형
                      </button>
                    </div>
                  </div>
              </div>

              <div className="w-full p-3 bg-gray-200/60 rounded-lg shadow-sm space-y-3">
                  <button onClick={() => setShowGifExportModal(true)} disabled={isExporting || isExportingMp4} className="w-full flex items-center justify-center gap-2 h-10 px-4 rounded-full bg-white shadow-sm transition-all hover:bg-gray-50 text-gray-700 font-medium text-sm disabled:bg-gray-200 disabled:cursor-not-allowed">
                    <Download className="w-4 h-4" /> GIF 다운로드
                  </button>
                  <button onClick={handleExportMp4} disabled={isExporting || isExportingMp4} className="w-full flex items-center justify-center gap-2 h-10 px-4 rounded-full bg-white shadow-sm transition-all hover:bg-gray-50 text-gray-700 font-medium text-sm disabled:bg-gray-200 disabled:cursor-not-allowed">
                      {isExportingMp4 ? (<><LoaderCircle className="w-4 h-4 animate-spin" />MP4 생성 중...</>) : (<><Download className="w-4 h-4" />MP4 다운로드</>)}
                  </button>
                   <button onClick={() => setShowExportFramesModal(true)} disabled={isExporting || isExportingMp4} className="w-full flex items-center justify-center gap-2 h-10 px-4 rounded-full bg-white shadow-sm transition-all hover:bg-gray-50 text-gray-700 font-medium text-sm disabled:bg-gray-200 disabled:cursor-not-allowed">
                      <Download className="w-4 h-4" /> 프레임 저장
                   </button>
              </div>

            </div>
          </div>
        </main>

        {/* Modals */}
        {showAspectRatioConfirm && (
          <div className="fixed inset-0 bg-black/50 flex items-center justify-center z-50 p-4">
            <div className="bg-white rounded-lg shadow-xl max-w-sm w-full">
              <div className="p-6">
                <h3 className="text-lg font-bold text-gray-800 mb-2">
                  종횡비 변경
                </h3>
                <p className="text-sm text-gray-600">
                  현재 프레임을 새 종횡비로 재구성하고 다른 모든 프레임을 삭제합니다. 계속하시겠습니까?
                </p>
              </div>
              <div className="bg-gray-50 px-6 py-4 flex justify-end gap-3 rounded-b-lg">
                <button
                  onClick={() => setShowAspectRatioConfirm(false)}
                  className="px-4 py-2 text-sm font-medium text-gray-700 bg-white border border-gray-300 rounded-md shadow-sm hover:bg-gray-50 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-gray-400">
                  취소
                </button>
                <button
                  onClick={() =>
                    performAspectRatioChange(targetAspectRatio as AspectRatio)
                  }
                  className="px-4 py-2 text-sm font-medium text-white bg-blue-600 border border-transparent rounded-md shadow-sm hover:bg-blue-700 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-blue-500">
                  변경 및 재구성
                </button>
              </div>
            </div>
          </div>
        )}
        {showGifExportModal && (
          <div className="fixed inset-0 bg-black/50 flex items-center justify-center z-50 p-4">
            <div className="bg-white rounded-lg shadow-xl max-w-sm w-full">
              <div className="p-6">
                <h3 className="text-lg font-bold text-gray-800 mb-4">
                  GIF 내보내기 옵션
                </h3>
                <div className="space-y-2">
                  <label
                    htmlFor="gif-quality-slider"
                    className="block text-sm font-medium text-gray-700">
                    품질 (낮을수록 좋음): {gifQuality}
                  </label>
                  <input
                    id="gif-quality-slider"
                    type="range"
                    min="1"
                    max="30"
                    step="1"
                    value={gifQuality}
                    onChange={(e) => setGifQuality(Number(e.target.value))}
                    className="w-full h-2 bg-gray-200 rounded-lg appearance-none cursor-pointer"
                  />
                  <p className="text-xs text-gray-500">
                    값이 낮을수록 품질은 높지만 파일 크기가 커집니다. (1: 최고, 30: 최저)
                  </p>
                </div>
              </div>
              <div className="bg-gray-50 px-6 py-4 flex justify-end gap-3 rounded-b-lg">
                <button
                  onClick={() => setShowGifExportModal(false)}
                  className="px-4 py-2 text-sm font-medium text-gray-700 bg-white border border-gray-300 rounded-md shadow-sm hover:bg-gray-50 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-gray-400">
                  취소
                </button>
                <button
                  onClick={handleExportGif}
                  disabled={isExporting}
                  className="px-4 py-2 text-sm font-medium text-white bg-blue-600 border border-transparent rounded-md shadow-sm hover:bg-blue-700 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-blue-500 disabled:bg-blue-300">
                  {isExporting ? '내보내는 중...' : '다운로드'}
                </button>
              </div>
            </div>
          </div>
        )}
        {showExportFramesModal && (
          <div className="fixed inset-0 bg-black/50 flex items-center justify-center z-50 p-4">
            <div className="bg-white rounded-lg shadow-xl max-w-sm w-full">
              <div className="p-6">
                <h3 className="text-lg font-bold text-gray-800 mb-4">
                  프레임 내보내기
                </h3>
                <p className="text-sm text-gray-600 mb-4">
                  모든 프레임을 개별 이미지 파일로 ZIP 아카이브에 다운로드합니다.
                </p>
                <fieldset>
                  <legend className="text-sm font-medium text-gray-900 mb-2">
                    파일 형식 선택:
                  </legend>
                  <div className="space-y-2">
                    <label className="flex items-center p-2 rounded-md hover:bg-gray-100 cursor-pointer">
                      <input
                        type="radio"
                        value="png"
                        checked={exportFormat === 'png'}
                        onChange={() => setExportFormat('png')}
                        className="h-4 w-4 text-blue-600 border-gray-300 focus:ring-blue-500"
                      />
                      <span className="ml-3 text-sm text-gray-700">
                        PNG (투명도 지원)
                      </span>
                    </label>
                    <label className="flex items-center p-2 rounded-md hover:bg-gray-100 cursor-pointer">
                      <input
                        type="radio"
                        value="jpg"
                        checked={exportFormat === 'jpg'}
                        onChange={() => setExportFormat('jpg')}
                        className="h-4 w-4 text-blue-600 border-gray-300 focus:ring-blue-500"
                      />
                      <span className="ml-3 text-sm text-gray-700">
                        JPG (파일 크기 작음)
                      </span>
                    </label>
                  </div>
                </fieldset>
              </div>
              <div className="bg-gray-50 px-6 py-4 flex justify-end gap-3 rounded-b-lg">
                <button
                  onClick={() => setShowExportFramesModal(false)}
                  className="px-4 py-2 text-sm font-medium text-gray-700 bg-white border border-gray-300 rounded-md shadow-sm hover:bg-gray-50 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-gray-400">
                  취소
                </button>
                <button
                  onClick={handleExportFrames}
                  disabled={isExporting}
                  className="px-4 py-2 text-sm font-medium text-white bg-blue-600 border border-transparent rounded-md shadow-sm hover:bg-blue-700 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-blue-500 disabled:bg-blue-300">
                  {isExporting ? '압축 중...' : '다운로드'}
                </button>
              </div>
            </div>
          </div>
        )}
        {showErrorModal && (
          <div className="fixed inset-0 bg-black/50 flex items-center justify-center z-50 p-4">
            <div className="bg-white rounded-lg shadow-xl max-w-md w-full p-6">
              <div className="flex justify-between items-start mb-4">
                <h3 className="text-xl font-bold text-gray-700">생성 실패</h3>
                <button
                  onClick={closeErrorModal}
                  className="text-gray-400 hover:text-gray-500">
                  <X className="w-5 h-5" />
                </button>
              </div>
              <p className="font-medium text-gray-600">{errorMessage}</p>
            </div>
          </div>
        )}
      </div>
    </>
  );
}

