  const drawCanvasContent = () => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    // Clear canvas
    ctx.save();
    ctx.setTransform(1, 0, 0, 1, 0, 0);
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    ctx.restore();

    // Apply zoom and pan
    ctx.save();
    ctx.translate(pan.x, pan.y);
    ctx.scale(zoom, zoom);

    // Draw the current frame image
    const dataUrl = frames[currentFrameIndex];
    if (dataUrl) {
        const img = new Image();
        img.onload = () => {
            ctx.drawImage(img, 0, 0);
            // Draw a border around the canvas content, scaled with zoom
            ctx.strokeStyle = '#9ca3af'; // gray-400
            ctx.lineWidth = 2 / zoom;
            ctx.strokeRect(0, 0, currentCanvasDimensions.width, currentCanvasDimensions.height);
