    const canvas = canvasRef.current;
    if (!canvas || activeTool === 'pan') return;

    const ctx = canvas.getContext('2d');
    if (ctx) ctx.closePath();

    if (activeTool === 'ai-eraser') {
        handleAiInpaint();
    } else {
        // Since we are now drawing directly on the canvas, we need to merge this with the existing frame data
        const tempCanvas = document.createElement('canvas');
        tempCanvas.width = canvas.width;
        tempCanvas.height = canvas.height;
        const tempCtx = tempCanvas.getContext('2d');
        if (!tempCtx) return;

        // 1. Draw the original frame content
        const existingImage = frames[currentFrameIndex];
        if (existingImage) {
            const img = new Image();
            img.onload = () => {
                tempCtx.drawImage(img, 0, 0);
