  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!prompt) return;
    setIsLoading(true);

    try {
        const parts: any[] = [];

        // Add selected characters to parts
        selectedCharacterIndices.forEach(index => {
            const charImage = cast[index];
            parts.push({
                inlineData: { data: charImage.split(',')[1], mimeType: 'image/png' }
            });
        });

        let finalPrompt = prompt;
        if (selectedCharacterIndices.length > 0) {
            finalPrompt += ` Please include the character(s) provided in the image.`
        }

        if (selectedStyle) {
            finalPrompt += ` Draw the result in this style: ${selectedStyle}.`;
        }
        finalPrompt += ` CRITICAL: Do not include any text, letters, or numbers in the image.`;

        parts.push({ text: finalPrompt });

        const response = await ai.models.generateContent({
            model: selectedModel,
            contents: { parts },
            config: { systemInstruction: INFOGRAPHIC_SYSTEM_INSTRUCTION },
        });

        let generatedImageData: string | undefined;
        for (const part of response.candidates?.[0]?.content?.parts || []) {
            if (part.inlineData) {
                generatedImageData = part.inlineData.data;
                break;
            }
        }

        if (generatedImageData) {
            const imageUrl = `data:image/png;base64,${generatedImageData}`;
            const newFrames = [...frames];
            newFrames[currentFrameIndex] = imageUrl;
            setFrames(newFrames);
            updateHistory(imageUrl, true); // Replace history with the new generated image
        } else {
            throw new Error('Could not find an image in the response. It might be blocked by safety settings.');
        }

        setPrompt('');
    } catch (error) {
        console.error('Error on submit:', error);
        setErrorMessage(parseError(error.message) || 'An unexpected error occurred.');
        setShowErrorModal(true);
    } finally {
        setIsLoading(false);
    }
};

  const handleGenerateAnimation = async (generationPrompt: string) => {
    if (!generationPrompt) return;
    setIsLoading(true);
    try {
        setInitialPrompt(generationPrompt);
        let allGeneratedFrames: string[] = [];
        const characterImages = selectedCharacterIndices.map(index => cast[index]);
        const totalFramesPerScene = sceneDuration * fps;

        for (let i = 0; i < numKeyScenes; i++) {
          for (let j = 0; j < totalFramesPerScene; j++) {
            const parts: any[] = [];
            characterImages.forEach(charImg => {
                parts.push({
                    inlineData: { data: charImg.split(',')[1], mimeType: 'image/png' },
                });
            });

            let framePrompt = `Key Scene ${i + 1} of ${numKeyScenes}. Frame ${j + 1} of ${totalFramesPerScene} in a ${sceneDuration}-second animation at ${fps} FPS of: ${generationPrompt}. The character(s) provided should be included if it makes sense. Ensure smooth, continuous motion from the previous frame to the next for this scene.`;
            if (selectedStyle) {
              framePrompt += ` IMPORTANT: Draw this in the following style: ${selectedStyle}.`;
            }
            framePrompt += ` CRITICAL: Do not include any text, letters, or numbers in the image.`;
            parts.push({text: framePrompt});

            const response = await ai.models.generateContent({
              model: selectedModel,
              contents: {parts},
              config: {systemInstruction: INFOGRAPHIC_SYSTEM_INSTRUCTION},
            });

            let generatedImageData: string | undefined;
            for (const part of response.candidates?.[0]?.content?.parts || []) {
              if (part.inlineData) {
                generatedImageData = part.inlineData.data;
                break;
              }
            }

            if (generatedImageData) {
              allGeneratedFrames.push(`data:image/png;base64,${generatedImageData}`);
            } else {
              throw new Error(`Frame generation failed at Scene ${i + 1}, Frame ${j + 1}. It might be blocked by safety settings.`);
            }
          }
        }

        setFrames(allGeneratedFrames);
        const newDurations = Array(allGeneratedFrames.length).fill(1000 / fps);
        setFrameDurations(newDurations);
        setCurrentFrameIndex(0);
        const newHistory = {};
        const newHistoryIndex = {};
        allGeneratedFrames.forEach((frame, index) => {
          if (frame) {
            newHistory[index] = [frame];
            newHistoryIndex[index] = 0;
          }
        });
        setHistory(newHistory);
        setHistoryIndex(newHistoryIndex);

    } catch (error) {
      console.error('Error generating animation:', error);
      setErrorMessage(
        parseError(error.message) || 'An unexpected error occurred during animation generation.',
      );
      setShowErrorModal(true);
    } finally {
        setIsLoading(false);
    }
  }


  const addFrame = () => {
    const currentFrameData = frames[currentFrameIndex];
    const newFrames = [...frames];
    newFrames.splice(currentFrameIndex + 1, 0, currentFrameData);
    setFrames(newFrames);

    const newDurations = [...frameDurations];
    newDurations.splice(currentFrameIndex + 1, 0, 1000 / fps);
    setFrameDurations(newDurations);

    setCurrentFrameIndex(currentFrameIndex + 1);
  };

  const selectFrame = (index: number) => {
    if (isPlaying) setIsPlaying(false);
    setCurrentFrameIndex(index);
  };

  const deleteFrame = (index: number) => {
    if (frames.length <= 1) {
      setFrames([null]);
      setFrameDurations([1000/fps]);
      setCurrentFrameIndex(0);
      return;
    }
    const newFrames = frames.filter((_, i) => i !== index);
    setFrames(newFrames);

    const newDurations = frameDurations.filter((_, i) => i !== index);
    setFrameDurations(newDurations);

    if (currentFrameIndex >= index) {
      setCurrentFrameIndex(Math.max(0, currentFrameIndex - 1));
    }
  };

  const togglePlay = () => setIsPlaying(!isPlaying);

  const closeErrorModal = () => setShowErrorModal(false);

  const handleFrameDurationChange = (e: ChangeEvent<HTMLInputElement>) => {
    const newDuration = Number(e.target.value);
    if (newDuration > 0) {
        const newDurations = [...frameDurations];
        newDurations[currentFrameIndex] = newDuration;
        setFrameDurations(newDurations);
    }
  };

  const handleGenerateNarration = async () => {
    const validFrames = frames.filter((f): f is string => f !== null);
    if (validFrames.length === 0) {
      setErrorMessage('Please create an animation before generating narration.');
      setShowErrorModal(true);
      return;
    }
    setIsGeneratingNarration(true);
    try {
      // 1. Describe frames to get context
      const descriptionParts: any[] = [
        {
          text: 'Describe this sequence of images as a short, simple story for an animation. Focus on the main action and mood. This description will be used to create a narration script. Do not describe the style, only the content.',
        },
      ];
      validFrames.forEach((frame) => {
        descriptionParts.push({
          inlineData: {data: frame.split(',')[1], mimeType: 'image/png'},
        });
      });

      const descriptionResponse = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: {parts: descriptionParts},
      });
      // Fix: Per Gemini API guidelines, .text is a property, not a method.
      const description = descriptionResponse.text ?? '';

      // 2. Generate a script from the description
      const scriptPrompt = `Based on the following scene description, write a short, one or two-sentence narration script in English. Include simple onomatopoeia (like "whoosh", "pop", "ding") where appropriate to make it lively. The script should be suitable for a general audience. Scene description: ${description}. The original animation idea was: ${initialPrompt}`;
      const scriptResponse = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: scriptPrompt,
      });
      // Fix: Per Gemini API guidelines, .text is a property, not a method.
      const script = (scriptResponse.text ?? '').trim();
      if (!script) {
        throw new Error('Failed to generate a narration script.');
      }

      // 3. Generate audio from the script using TTS
      const ttsResponse = await ai.models.generateContent({
        model: 'gemini-2.5-flash-preview-tts',
        contents: [{parts: [{text: `Read this cheerfully: ${script}`}]}],
        config: {
          responseModalities: [Modality.AUDIO],
          speechConfig: {
            voiceConfig: {prebuiltVoiceConfig: {voiceName: 'Kore'}},
          },
        },
      });

      const base64Audio =
        ttsResponse.candidates?.[0]?.content?.parts?.[0]?.inlineData?.data;
      if (!base64Audio) {
        throw new Error('Audio data not found in the response.');
      }

      // 4. Create a playable WAV blob and set it in state
      const pcmData = decode(base64Audio);
      const wavBlob = createWavBlob(pcmData, 24000, 1);
      const audioUrl = URL.createObjectURL(wavBlob);
      setNarrationAudio(audioUrl);
    } catch (error) {
      console.error('Narration generation failed:', error);
      setErrorMessage(
        parseError(error.message) || 'Failed to generate narration.',
      );
      setShowErrorModal(true);
    } finally {
      setIsGeneratingNarration(false);
    }
  };

  const handleExportGif = async () => {
    if (isExporting) return;
    const framesToExport = frames.filter(
      (frame): frame is string => frame !== null,
    );
    if (framesToExport.length === 0) {
      alert('There are no frames to export.');
      return;
    }

    setIsExporting(true);
    setShowGifExportModal(false);

    try {
      const gif = new GIF({
        workers: 2,
        quality: gifQuality,
        workerScript:
          'https://cdnjs.cloudflare.com/ajax/libs/gif.js/0.2.0/gif.worker.js',
        width: ASPECT_RATIOS[aspectRatio].width,
        height: ASPECT_RATIOS[aspectRatio].height,
      });

      const imagePromises = framesToExport.map((dataUrl) => {
        return new Promise<HTMLImageElement>((resolve, reject) => {
          const img = new Image();
          img.onload = () => resolve(img);
          img.onerror = reject;
          img.src = dataUrl;
        });
      });

      const loadedImages = await Promise.all(imagePromises);

      for (let i = 0; i < loadedImages.length; i++) {
        const image = loadedImages[i];
        const delay = frameDurations[i] || (1000 / fps);
        gif.addFrame(image, { delay });
      }

      gif.on('finished', (blob) => {
        const url = URL.createObjectURL(blob);
        const a = document.createElement('a');
        a.href = url;
        a.download = 'animation.gif';
        document.body.appendChild(a);
        a.click();
        document.body.removeChild(a);
        URL.revokeObjectURL(url);
        setIsExporting(false);
      });

      gif.render();
    } catch (error) {
      console.error('GIF export failed:', error);
      setErrorMessage('An error occurred while exporting the GIF.');
      setShowErrorModal(true);
      setIsExporting(false);
    }
  };

  const handleExportFrames = async () => {
    if (isExporting) return;
    const framesToExport = frames.filter((frame): frame is string =>
      Boolean(frame),
    );
    if (framesToExport.length === 0) {
      alert('There are no frames to export.');
      return;
    }

    setIsExporting(true);
    setShowExportFramesModal(false);

    try {
      const zip = new JSZip();
      const format = exportFormat;
      const mimeType = `image/${format === 'jpg' ? 'jpeg' : 'png'}`;

      for (let i = 0; i < framesToExport.length; i++) {
        const frameDataUrl = framesToExport[i];
        let processedDataUrl = frameDataUrl;

        if (format === 'jpg') {
          processedDataUrl = await new Promise<string>((resolve, reject) => {
            const img = new Image();
            img.onload = () => {
              const canvas = document.createElement('canvas');
              canvas.width = img.width;
              canvas.height = img.height;
              const ctx = canvas.getContext('2d');
              if (!ctx) return reject(new Error('Canvas context unavailable'));
              ctx.fillStyle = '#FFFFFF'; // Add white background for JPG
              ctx.fillRect(0, 0, canvas.width, canvas.height);
              ctx.drawImage(img, 0, 0);
              resolve(canvas.toDataURL(mimeType, 0.9));
            };
            img.onerror = reject;
            img.src = frameDataUrl;
          });
        }

        const base64Data = processedDataUrl.split(',')[1];
        zip.file(
          `frame_${String(i + 1).padStart(3, '0')}.${format}`,
          base64Data,
          {base64: true},
        );
      }

      const blob = await zip.generateAsync({type: 'blob'});
      const a = document.createElement('a');
      a.href = URL.createObjectURL(blob);
      a.download = `animation_frames.zip`;
      document.body.appendChild(a);
      a.click();
      document.body.removeChild(a);
      URL.revokeObjectURL(a.href);
    } catch (error) {
      console.error('Frame export failed:', error);
      setErrorMessage(
        `An error occurred while exporting frames as ${exportFormat.toUpperCase()}.`,
      );
      setShowErrorModal(true);
    } finally {
      setIsExporting(false);
    }
  };

  const handleExportMp4 = async () => {
    if (isExporting || isExportingMp4) return;
    const framesToExport = frames.filter(
      (frame): frame is string => frame !== null,
    );
    if (framesToExport.length === 0) {
      alert('There are no frames to export.');
      return;
    }

    setIsExportingMp4(true);

    try {
      const canvas = document.createElement('canvas');
      canvas.width = ASPECT_RATIOS[aspectRatio].width;
      canvas.height = ASPECT_RATIOS[aspectRatio].height;
      const ctx = canvas.getContext('2d');
      if (!ctx) {
        throw new Error('Could not get canvas context.');
      }

      const videoStream = canvas.captureStream(fps);
      let finalStream: MediaStream = videoStream;

      // If narration exists, mix it in
      if (narrationAudio) {
        const audioContext = new (window.AudioContext || (window as any).webkitAudioContext)();
        const response = await fetch(narrationAudio);
        const arrayBuffer = await response.arrayBuffer();
        const audioBuffer = await audioContext.decodeAudioData(arrayBuffer);
        const destination = audioContext.createMediaStreamDestination();
        const source = audioContext.createBufferSource();
        source.buffer = audioBuffer;
        source.connect(destination);
        const audioStream = destination.stream;
        finalStream = new MediaStream([
            ...videoStream.getVideoTracks(),
            ...audioStream.getAudioTracks()
        ]);
        source.start(); // Start playing the audio into the stream
      }

      const mimeType = 'video/webm; codecs=vp9,opus';
      if (!MediaRecorder.isTypeSupported(mimeType)) {
        throw new Error(`${mimeType} is not supported in this browser.`);
      }
      const recorder = new MediaRecorder(finalStream, {mimeType});

      const chunks: Blob[] = [];
      recorder.ondataavailable = (e) => {
        if (e.data.size > 0) {
          chunks.push(e.data);
        }
      };

      recorder.onstop = () => {
        const blob = new Blob(chunks, {type: 'video/mp4'});
        const url = URL.createObjectURL(blob);
        const a = document.createElement('a');
        a.href = url;
        a.download = 'animation.mp4';
        document.body.appendChild(a);
        a.click();
        document.body.removeChild(a);
        URL.revokeObjectURL(url);
        setIsExportingMp4(false);
      };

      const imagePromises = framesToExport.map(
        (dataUrl) =>
          new Promise<HTMLImageElement>((resolve, reject) => {
            const img = new Image();
            img.onload = () => resolve(img);
            img.onerror = reject;
            img.src = dataUrl;
          }),
      );
      const loadedImages = await Promise.all(imagePromises);

      recorder.start();

      let frameIndex = 0;
      const intervalId = setInterval(() => {
        if (frameIndex >= loadedImages.length) {
          clearInterval(intervalId);
          recorder.stop();
          return;
        }
        const image = loadedImages[frameIndex];
        ctx.fillStyle = '#FFFFFF';
        ctx.fillRect(0, 0, canvas.width, canvas.height);
        ctx.drawImage(image, 0, 0, canvas.width, canvas.height);
        frameIndex++;
      }, 1000 / fps);
    } catch (error) {
      console.error('MP4 export failed:', error);
      setErrorMessage(`An error occurred while exporting the MP4: ${error.message}`);
      setShowErrorModal(true);
      setIsExportingMp4(false);
    }
  };

  const performAspectRatioChange = async (newRatio: AspectRatio) => {
    const currentFrameData = frames[currentFrameIndex];
    setShowAspectRatioConfirm(false);

    if (!currentFrameData) {
      setAspectRatio(newRatio);
      setFrames([null]);
      setFrameDurations([1000/fps]);
      setCurrentFrameIndex(0);
      setHistory({});
      setHistoryIndex({});
      setNarrationAudio(null);
      setTargetAspectRatio(null);
      return;
    }

    setIsRecomposing(true);
    setErrorMessage('');

    try {
      const parts = [
        {
          inlineData: {
            data: currentFrameData.split(',')[1],
            mimeType: 'image/png',
          },
        },
        {
          text: `Re-compose this image to fit a ${newRatio} aspect ratio. Do not stretch or distort the main subject; instead, expand the background scenery to fit the new dimensions while maintaining the subject's proportions.`,
        },
      ];

      const response = await ai.models.generateContent({
        model: selectedModel,
        contents: {parts},
        config: {systemInstruction: RECOMPOSE_SYSTEM_INSTRUCTION},
      });

      let generatedImageData: string | undefined;
      for (const part of response.candidates?.[0]?.content?.parts || []) {
        if (part.inlineData) {
          generatedImageData = part.inlineData.data;
          break;
        }
      }

      if (generatedImageData) {
        const imageUrl = `data:image/png;base64,${generatedImageData}`;
        setAspectRatio(newRatio);
        const newFrames = Array(frames.length).fill(null);
        newFrames[0] = imageUrl;

        setFrames(newFrames);
        setFrameDurations(Array(frames.length).fill(1000 / fps));
        setCurrentFrameIndex(0);
        setHistory({0: [imageUrl]});
        setHistoryIndex({0: 0});
        setNarrationAudio(null);
      } else {
        throw new Error(
          'Failed to re-compose the image. The model did not return a valid image.',
        );
      }
    } catch (error) {
      console.error('Error during re-composition:', error);
      setErrorMessage(
        parseError(error.message) ||
          'An error occurred during re-composition.',
      );
      setShowErrorModal(true);
    } finally {
      setIsRecomposing(false);
      setTargetAspectRatio(null);
    }
  };

  const handleAspectRatioChange = (newRatio: AspectRatio) => {
    if (newRatio === aspectRatio) return;

    const hasContent = frames.some((f) => f !== null);
    if (hasContent) {
      setTargetAspectRatio(newRatio);
      setShowAspectRatioConfirm(true);
    } else {
      // If there's no content, just change the aspect ratio without AI call
      setAspectRatio(newRatio);
      setFrames([null]);
      setFrameDurations([1000 / fps]);
      setCurrentFrameIndex(0);
      setHistory({});
      setHistoryIndex({});
      setNarrationAudio(null);
    }
  };

  const handleSaveCharacter = () => {
    const canvas = canvasRef.current;
    if (canvas) {
      const dataUrl = canvas.toDataURL('image/png');
      const isEmpty = !frames[currentFrameIndex];
      if (!isEmpty) {
        setCast([...cast, dataUrl]);
      } else {
        setErrorMessage('Cannot save an empty canvas as a character.');
        setShowErrorModal(true);
      }
    }
  };

  const handleSelectCharacter = (index: number) => {
    setSelectedCharacterIndices(prev => 
        prev.includes(index) 
        ? prev.filter(i => i !== index)
        : [...prev, index]
    );
  };

  const handleRemoveCharacter = (
    e: React.MouseEvent,
    indexToRemove: number,
  ) => {
    e.stopPropagation(); // Prevent selection when clicking remove button
    setCast(cast.filter((_, index) => index !== indexToRemove));
    setSelectedCharacterIndices(prev => prev.filter(i => i !== indexToRemove));
  };


  useEffect(() => {
    const preventTouchDefault = (e: TouchEvent) => {
      if (isInteracting.current) e.preventDefault();
    };
    const canvas = canvasRef.current;
    if (canvas) {
      canvas.addEventListener('touchstart', preventTouchDefault, {
        passive: false,
      });
      canvas.addEventListener('touchmove', preventTouchDefault, {
        passive: false,
      });
    }
    return () => {
      if (canvas) {
        canvas.removeEventListener('touchstart', preventTouchDefault);
        canvas.removeEventListener('touchmove', preventTouchDefault);
      }
    };
  }, []);

  const hasContent = frames.some(f => f !== null);

  const canUndo = (historyIndex[currentFrameIndex] ?? 0) > 0;
  const canRedo =
    (historyIndex[currentFrameIndex] ?? -1) <
    (history[currentFrameIndex]?.length ?? 0) - 1;

  const currentCanvasDimensions = ASPECT_RATIOS[aspectRatio];
  const currentThumbnailDimensions = THUMBNAIL_DIMS[aspectRatio];

  const previewStylePrompt = hoveredStyle || selectedStyle;
  const previewStyleObject = ANIMATION_STYLES.find(s => s.prompt === previewStylePrompt);


  return (
    <>
      <div className="min-h-screen notebook-paper-bg text-gray-900 flex flex-col justify-start items-center">
        <main className="container mx-auto px-3 sm:px-6 py-5 sm:py-10 max-w-7xl w-full">
          {/* Header */}
          <div className="flex flex-col sm:flex-row sm:justify-between sm:items-end mb-4 sm:mb-6 gap-2">
            <div>
              <h1 className="text-2xl sm:text-3xl font-bold mb-0 leading-tight font-mega">
                Gemini 애니메이션 스튜디오
              </h1>
              <p className="text-sm sm:text-base text-gray-500 mt-1">
                <a
                  className="underline"
                  href="https://ai.google.dev/gemini-api/docs/image-generation"
                  target="_blank"
                  rel="noopener noreferrer">
                  Gemini 네이티브 이미지 생성으로 제작
                </a>
              </p>
            </div>
          </div>

          {/* Main Content: Two-column layout for large screens */}
          <div className="w-full grid grid-cols-1 lg:grid-cols-2 lg:gap-8">
            {/* Left Column: Canvas, Prompt, Cast, Timeline */}
            <div className="flex gap-4">
                <div className="flex flex-col gap-2 items-center p-2 bg-gray-200/60 rounded-lg shadow-sm">
                    <button onClick={() => setActiveTool('pen')} className={`p-2 rounded-md transition-colors ${activeTool === 'pen' ? 'bg-blue-500 text-white' : 'hover:bg-gray-300'}`} aria-label="Pen Tool">
                        <PenTool className="w-5 h-5" />
                    </button>
                    <button onClick={() => setActiveTool('pan')} className={`p-2 rounded-md transition-colors ${activeTool === 'pan' ? 'bg-blue-500 text-white' : 'hover:bg-gray-300'}`} aria-label="Pan Tool">
                        <Hand className="w-5 h-5" />
                    </button>
                    <button onClick={() => setActiveTool('eraser')} className={`p-2 rounded-md transition-colors ${activeTool === 'eraser' ? 'bg-blue-500 text-white' : 'hover:bg-gray-300'}`} aria-label="Eraser Tool">
                        <Eraser className="w-5 h-5" />
                    </button>
                    <button onClick={() => setActiveTool('ai-eraser')} className={`p-2 rounded-md transition-colors ${activeTool === 'ai-eraser' ? 'bg-blue-500 text-white' : 'hover:bg-gray-300'}`} aria-label="AI Eraser Tool">
                        <Sparkles className="w-5 h-5" />
