                  className="text-gray-400 hover:text-gray-500">
                  <X className="w-5 h-5" />
                </button>
              </div>
              <p className="font-medium text-gray-600">{errorMessage}</p>
            </div>
          </div>
        )}
      </div>
    </>
  );
}

