    document.addEventListener('touchmove', preventTouchDefault, { passive: false });

    return () => {
      document.removeEventListener('touchstart', preventTouchDefault);
      document.removeEventListener('touchmove', preventTouchDefault);
    };
  }, []);

  const hasContent = frames.some(f => f !== null);

  const canUndo = (historyIndex[currentFrameIndex] ?? 0) > 0;
  const canRedo =
    (historyIndex[currentFrameIndex] ?? -1) <
    (history[currentFrameIndex]?.length ?? 0) - 1;

  const currentCanvasDimensions = ASPECT_RATIOS[aspectRatio];
  const currentThumbnailDimensions = THUMBNAIL_DIMS[aspectRatio];

  const previewStylePrompt = hoveredStyle || selectedStyle;
  const previewStyleObject = ANIMATION_STYLES.find(s => s.prompt === previewStylePrompt);


  return (
    <>
      <div className="min-h-screen notebook-paper-bg text-gray-900 flex flex-col justify-start items-center">
