    try {
      const synopsisPrompt = `Analyze the following script/story and break it down into ${synopsisNumScenes} key visual scenes. For each scene, provide a short, descriptive title and a detailed visual prompt suitable for an image generation model. The visual prompt should be in English. Respond ONLY with a valid JSON array of objects, where each object has a "title" and a "prompt" key.

