  const handleCreateTimelineFromSynopsis = async () => {
    if (generatedSynopsis.length === 0) return;
    setIsLoading(true);
    setShowScriptModal(false);
    try {
        const imageGenerationPromises = generatedSynopsis.map(scene => {
            let finalPrompt = scene.prompt;
            if (selectedStyle) {
                finalPrompt += ` Draw this in the style of: ${selectedStyle}.`;
            }
             finalPrompt += ` CRITICAL: Do not include any text, letters, or numbers in the image.`;

            return ai.models.generateContent({
                model: selectedModel,
                contents: finalPrompt,
                config: { systemInstruction: INFOGRAPHIC_SYSTEM_INSTRUCTION },
            });
        });

        const responses = await Promise.all(imageGenerationPromises);

        const newImageFrames = responses.map(response => {
            for (const part of response.candidates?.[0]?.content?.parts || []) {
                if (part.inlineData) {
                    return `data:image/png;base64,${part.inlineData.data}`;
                }
