ite shadow-sm transition-all hover:bg-gray-50 disabled:opacity-50 disabled:cursor-not-allowed"><UserPlus className="w-5 h-5 text-gray-700" /></button></div><div className="flex-grow flex gap-2 overflow-x-auto p-2 bg-black/5 rounded-md min-h-[120px] items-center">{frames.map((frame, index) => { const scene = sceneData[index]; return (<div key={index} onDoubleClick={() => { setCurrentFrameIndex(index); setViewMode('editor'); }} className="relative shrink-0 cursor-pointer group" style={{ width: `${currentThumbnailDimensions.width}px`, height: `${currentThumbnailDimensions.height}px`}}>{frame ? (<img src={frame} className={`bg-white rounded-sm w-full h-full object-contain ${ currentFrameIndex === index ? 'ring-2 ring-blue-500 ring-offset-2' : 'ring-1 ring-gray-300' }`} />) : scene && scene.prompt ? (<div className={`w-full h-full bg-gray-100 flex flex-col items-center justify-center p-1 text-center border rounded-sm transition-all ${ currentFrameIndex === index ? 'ring-2 ring-blue-500 ring-offset-2' : 'border-gray-300 hover:bg-gray-200'}`}><span className="font-bold text-gray-700 text-lg">{index + 1}</span><p className="text-[10px] text-gray-600 leading-tight overflow-hidden" style={{ display: '-webkit-box', WebkitLineClamp: 3, WebkitBoxOrient: 'vertical' }}>{scene.prompt}</p></div>) : (<div className={`bg-white rounded-sm w-full h-full object-contain flex items-center justify-center ${ currentFrameIndex === index ? 'ring-2 ring-blue-500 ring-offset-2' : 'ring-1 ring-gray-300' }`} />)}<span className="absolute bottom-1 right-1.5 text-xs font-mono bg-black/50 text-white px-1 py-0.5 rounded-sm pointer-events-none">{index + 1}</span>{frames.length > 1 && (<button onClick={(e) => { e.stopPropagation(); deleteFrame(index); }} className="absolute -top-2 -right-2 w-5 h-5 bg-red-500 text-white rounded-full flex items-center justify-center shadow transition-transform hover:scale-110 opacity-0 group-hover:opacity-100" aria-label={`프레임 ${index + 1} 삭제`}><X className="w-3 h-3" /></button>)}</div>)})}</div></div></footer>
