  const [showErrorModal, setShowErrorModal] = useState(false);
  const [errorMessage, setErrorMessage] = useState('');
  const [selectedModel, setSelectedModel] = useState('gemini-2.5-flash-image');

  const [zoom, setZoom] = useState(1);
  const [pan, setPan] = useState({ x: 0, y: 0 });

  const [frames, setFrames] = useState<(string | null)[]>([null]);
  const [currentFrameIndex, setCurrentFrameIndex] = useState(0);
  const [isPlaying, setIsPlaying] = useState(false);
  const [fps, setFps] = useState(8);
  const [frameDurations, setFrameDurations] = useState<number[]>([1000]);
  const [isExporting, setIsExporting] = useState(false);
  const [isExportingMp4, setIsExportingMp4] = useState(false);
  const playbackTimeoutRef = useRef<number | null>(null);

  const [narrationAudio, setNarrationAudio] = useState<string | null>(null);
  const [isGeneratingNarration, setIsGeneratingNarration] = useState(false);
  const [initialPrompt, setInitialPrompt] = useState('');
  const audioRef = useRef<HTMLAudioElement>(null);

  const [aspectRatio, setAspectRatio] = useState<AspectRatio>('16:9');
  const [showAspectRatioConfirm, setShowAspectRatioConfirm] = useState(false);
  const [targetAspectRatio, setTargetAspectRatio] =
    useState<AspectRatio | null>(null);
  const [isRecomposing, setIsRecomposing] = useState(false);

  const [history, setHistory] = useState<{ [key: number]: string[] }>({});
  const [historyIndex, setHistoryIndex] = useState<{ [key: number]: number }>(
    {},
  );

  const fileInputRef = useRef<HTMLInputElement>(null);

  const [cast, setCast] = useState<string[]>([]);
  const [selectedCharacterIndices, setSelectedCharacterIndices] = useState<number[]>([]);

  const [showExportModal, setShowExportModal] = useState(false);
  const [exportFormat, setExportFormat] = useState<'png' | 'jpg'>('png');
  const [gifQuality, setGifQuality] = useState(10);

  const [selectedStyle, setSelectedStyle] = useState<string | null>(null);

  const [showScriptModal, setShowScriptModal] = useState(false);
  const [scriptText, setScriptText] = useState('');
  const [generatedSynopsis, setGeneratedSynopsis] = useState<SynopsisScene[]>([]);
  const [isGeneratingSynopsis, setIsGeneratingSynopsis] = useState(false);
  const [synopsisNumScenes, setSynopsisNumScenes] = useState(5);
  const [sceneData, setSceneData] = useState<SynopsisScene[]>([]);

  const drawCanvasContent = (canvas: HTMLCanvasElement | null, dataUrl: string | null) => {
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    ctx.clearRect(0, 0, canvas.width, canvas.height);

    if (dataUrl) {
      const img = new Image();
      img.onload = () => {
        ctx.drawImage(img, 0, 0);
      };
      img.src = dataUrl;
    }
  };

  useEffect(() => {
    drawCanvasContent(canvasRef.current, frames[currentFrameIndex]);
  }, [currentFrameIndex, frames, aspectRatio, viewMode]);

  useEffect(() => {
    const currentScene = sceneData[currentFrameIndex];
    if (viewMode === 'editor' && currentScene && !frames[currentFrameIndex]) {
      setPrompt(currentScene.prompt);
    }
  }, [currentFrameIndex, sceneData, frames, viewMode]);

  useEffect(() => {
    const overlayCanvas = overlayCanvasRef.current;
    if (overlayCanvas) {
      const overlayCtx = overlayCanvas.getContext('2d');
      overlayCtx?.clearRect(0, 0, overlayCanvas.width, overlayCanvas.height);
    }
  }, [activeTool]);

    useEffect(() => {
        if (playbackTimeoutRef.current) {
            clearTimeout(playbackTimeoutRef.current);
        }

        if (isPlaying) {
            const playNextFrame = () => {
                setCurrentFrameIndex(prevIndex => (prevIndex + 1) % frames.length);
            };

            const currentDuration = frameDurations[currentFrameIndex] ?? 1000 / fps;
            playbackTimeoutRef.current = window.setTimeout(playNextFrame, currentDuration);
        }

        return () => {
            if (playbackTimeoutRef.current) {
                clearTimeout(playbackTimeoutRef.current);
            }
        };
    }, [isPlaying, currentFrameIndex, frames.length, frameDurations, fps]);

  const getCoordinates = (e: React.MouseEvent | React.TouchEvent) => {
    const canvas = canvasRef.current;
    if (!canvas) return { x: 0, y: 0 };
    const rect = canvas.getBoundingClientRect();

    const clientX = 'touches' in e ? e.touches[0].clientX : e.clientX;
    const clientY = 'touches' in e ? e.touches[0].clientY : e.clientY;

    const elementX = clientX - rect.left;
    const elementY = clientY - rect.top;

    const bitmapX = elementX * (canvas.width / rect.width);
    const bitmapY = elementY * (canvas.height / rect.height);

    const transformedX = (bitmapX - pan.x) / zoom;
    const transformedY = (bitmapY - pan.y) / zoom;

    return {
      x: transformedX,
      y: transformedY,
    };
  };

  const startInteraction = (e: React.MouseEvent | React.TouchEvent) => {
    if ('touches' in e) e.preventDefault();
    if (isPlaying) setIsPlaying(false);

    isInteracting.current = true;

    if (activeTool === 'pan') {
      const clientX = 'touches' in e ? e.touches[0].clientX : e.clientX;
      const clientY = 'touches' in e ? e.touches[0].clientY : e.clientY;
      lastPosition.current = { x: clientX, y: clientY };
    } else {
      const { x, y } = getCoordinates(e);
      let ctx: CanvasRenderingContext2D | null | undefined;

      if (activeTool === 'ai-eraser') {
        ctx = overlayCanvasRef.current?.getContext('2d');
      } else {
        ctx = canvasRef.current?.getContext('2d');
      }

      if (!ctx) return;

      ctx.beginPath();
      ctx.moveTo(x, y);
    }
  };

  const moveInteraction = (e: React.MouseEvent | React.TouchEvent) => {
    if (!isInteracting.current) return;
    if ('touches' in e) e.preventDefault();

    if (activeTool === 'pan') {
      const clientX = 'touches' in e ? e.touches[0].clientX : e.clientX;
      const clientY = 'touches' in e ? e.touches[0].clientY : e.clientY;
      const dx = clientX - lastPosition.current.x;
      const dy = clientY - lastPosition.current.y;
      setPan({ x: pan.x + dx, y: pan.y + dy });
      lastPosition.current = { x: clientX, y: clientY };
    } else {
        const { x, y } = getCoordinates(e);
        let ctx: CanvasRenderingContext2D | null | undefined;

        if (activeTool === 'ai-eraser') {
            ctx = overlayCanvasRef.current?.getContext('2d');
            if (ctx) {
                ctx.strokeStyle = 'rgba(255, 255, 0, 0.5)';
                ctx.lineWidth = eraserSize;
                ctx.lineCap = 'round';
                ctx.globalCompositeOperation = 'source-over';
            }
        } else {
            ctx = canvasRef.current?.getContext('2d');
            if (ctx) {
                if (activeTool === 'pen') {
                    ctx.globalCompositeOperation = 'source-over';
                    ctx.lineWidth = penSize;
                    ctx.strokeStyle = penColor;
                } else { // eraser
                    ctx.globalCompositeOperation = 'destination-out';
                    ctx.lineWidth = eraserSize;
                }
                ctx.lineCap = 'round';
            }
        }

        if (!ctx) return;
        ctx.lineTo(x, y);
        ctx.stroke();
    }
  };

  const handleAiInpaint = async () => {
    const canvas = canvasRef.current;
    if (!canvas) return;

    const erasedImageData = canvas.toDataURL('image/png');

    const newFrames = [...frames];
    newFrames[currentFrameIndex] = erasedImageData;
    setFrames(newFrames);
    updateHistory(erasedImageData);

    setIsLoading(true);

    try {
        const aiPrompt = `This is an inpainting request. The transparent pixels in this image should be filled in. Use the surrounding image content and style to fill the transparent area. Additionally, follow this user instruction: ${prompt || 'seamlessly blend with the background'}. CRITICAL: Do not include any text, letters, or numbers in the image.`;

        const parts = [
            { inlineData: { data: erasedImageData.split(',')[1], mimeType: 'image/png' } },
            { text: aiPrompt }
        ];

        const response = await ai.models.generateContent({
            model: selectedModel,
            contents: { parts },
        });

        let generatedImageData: string | undefined;
        for (const part of response.candidates?.[0]?.content?.parts || []) {
            if (part.inlineData) {
                generatedImageData = part.inlineData.data;
                break;
            }
        }

        if (generatedImageData) {
            const imageUrl = `data:image/png;base64,${generatedImageData}`;
            const finalFrames = [...frames];
            finalFrames[currentFrameIndex] = imageUrl;
            setFrames(finalFrames);
            updateHistory(imageUrl);
            setPrompt('');
        } else {
            throw new Error('AI 지우개 작업에 실패했습니다. 안전 설정에 의해 차단되었을 수 있습니다.');
        }
    } catch (error) {
        console.error('AI inpainting failed:', error);
        setErrorMessage(parseError(error.message) || 'AI 지우개 작업 중 오류가 발생했습니다.');
        setShowErrorModal(true);
        handleUndo();
    } finally {
        setIsLoading(false);
    }
  };

  const stopInteraction = () => {
    if (!isInteracting.current) return;
    isInteracting.current = false;

    if (activeTool === 'pan') return;

    let targetCanvas: HTMLCanvasElement | null = null;
    if (activeTool === 'ai-eraser') {
      targetCanvas = overlayCanvasRef.current;
    } else {
      targetCanvas = canvasRef.current;
    }

    if (!targetCanvas) return;
    const ctx = targetCanvas.getContext('2d');
    if (ctx) ctx.closePath();

    if (activeTool === 'ai-eraser') {
        const mainCanvas = canvasRef.current;
        const overlayCanvas = overlayCanvasRef.current;
        if (!mainCanvas || !overlayCanvas) return;
        const mainCtx = mainCanvas.getContext('2d');
        const overlayCtx = overlayCanvas.getContext('2d');
        if (!mainCtx || !overlayCtx) return;

        mainCtx.globalCompositeOperation = 'destination-out';
        mainCtx.drawImage(overlayCanvas, 0, 0);
        mainCtx.globalCompositeOperation = 'source-over'; 

        overlayCtx.clearRect(0, 0, overlayCanvas.width, overlayCanvas.height);

        handleAiInpaint();
    } else {
         const dataUrl = targetCanvas.toDataURL('image/png');
         updateHistory(dataUrl);
         const newFrames = [...frames];
         newFrames[currentFrameIndex] = dataUrl;
         setFrames(newFrames);
    }
  };

  const updateHistory = (dataUrl: string, replace = false) => {
    const currentIndex = historyIndex[currentFrameIndex] ?? -1;
    const currentHistory = history[currentFrameIndex] || [];
    const newHistory = replace
      ? [dataUrl]
      : [...currentHistory.slice(0, currentIndex + 1), dataUrl];

    setHistory({...history, [currentFrameIndex]: newHistory});
    setHistoryIndex({
      ...historyIndex,
      [currentFrameIndex]: newHistory.length - 1,
    });
  };

  const handleUndo = () => {
    const currentIndex = historyIndex[currentFrameIndex] ?? 0;
    if (currentIndex <= 0) return;

    const newIndex = currentIndex - 1;
    setHistoryIndex({...historyIndex, [currentFrameIndex]: newIndex});

    const dataUrl = history[currentFrameIndex][newIndex];
    const newFrames = [...frames];
    newFrames[currentFrameIndex] = dataUrl;
    setFrames(newFrames);
  };

  const handleRedo = () => {
    const currentIndex = historyIndex[currentFrameIndex] ?? -1;
    const frameHistory = history[currentFrameIndex] || [];
    if (currentIndex >= frameHistory.length - 1) return;

    const newIndex = currentIndex + 1;
    setHistoryIndex({...historyIndex, [currentFrameIndex]: newIndex});

    const dataUrl = frameHistory[newIndex];
    const newFrames = [...frames];
    newFrames[currentFrameIndex] = dataUrl;
    setFrames(newFrames);
  };

  const clearCanvas = () => {
    const newFrames = [...frames];
    newFrames[currentFrameIndex] = null;
    setFrames(newFrames);

    const newSceneData = [...sceneData];
    if (newSceneData[currentFrameIndex]) {
        newSceneData[currentFrameIndex] = { title: '', prompt: '' }; 
        setSceneData(newSceneData);
    }

    const newHistory = {...history};
    delete newHistory[currentFrameIndex];
    setHistory(newHistory);
    const newHistoryIdx = {...historyIndex};
    delete newHistoryIdx[currentFrameIndex];
    setHistoryIndex(newHistoryIdx);
  };

  const handleColorChange = (e: ChangeEvent<HTMLInputElement>) =>
    setPenColor(e.target.value);

  const openColorPicker = () =>
    (colorInputRef.current as HTMLInputElement)?.click();

  const processImageFile = (file: File) => {
    if (file && file.type.startsWith('image/')) {
        const reader = new FileReader();
        reader.onloadend = () => {
            const dataUrl = reader.result as string;

            const tempCanvas = document.createElement('canvas');
            const targetDims = ASPECT_RATIOS[aspectRatio];
            tempCanvas.width = targetDims.width;
            tempCanvas.height = targetDims.height;
            const ctx = tempCanvas.getContext('2d');
            if (!ctx) return;

            const img = new Image();
            img.onload = () => {
                ctx.fillStyle = '#FFFFFF';
                ctx.fillRect(0, 0, tempCanvas.width, tempCanvas.height);
                const hRatio = tempCanvas.width / img.width;
                const vRatio = tempCanvas.height / img.height;
                const ratio = Math.min(hRatio, vRatio);
                const centerShift_x = (tempCanvas.width - img.width * ratio) / 2;
                const centerShift_y = (tempCanvas.height - img.height * ratio) / 2;
                ctx.drawImage(img, 0, 0, img.width, img.height, 
                              centerShift_x, centerShift_y, img.width * ratio, img.height * ratio);

                const finalDataUrl = tempCanvas.toDataURL('image/png');
                const newFrames = [...frames];
                newFrames[currentFrameIndex] = finalDataUrl;
                setFrames(newFrames);
                updateHistory(finalDataUrl, true);

                const newSceneData = [...sceneData];
                if (newSceneData[currentFrameIndex]) {
                    newSceneData[currentFrameIndex] = { title: '', prompt: '' };
                    setSceneData(newSceneData);
                }

            };
            img.src = dataUrl;
        };
        reader.readAsDataURL(file);
    }
  };

  const handleImageUpload = (e: ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      processImageFile(file);
    }
    e.target.value = '';
  };

  const handleStyleSelect = (stylePrompt: string) => {
    if (selectedStyle === stylePrompt) {
      setSelectedStyle(null);
    } else {
      setSelectedStyle(stylePrompt);
    }
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!prompt) return;
    setIsLoading(true);

    try {
        const parts: any[] = [];

        selectedCharacterIndices.forEach(index => {
            const charImage = cast[index];
            parts.push({
                inlineData: { data: charImage.split(',')[1], mimeType: 'image/png' }
            });
        });

        let finalPrompt = prompt;
        if (selectedCharacterIndices.length > 0) {
            finalPrompt += ` Please include the character(s) provided in the image.`
        }

        if (selectedStyle) {
            finalPrompt += ` Draw the result in this style: ${selectedStyle}.`;
        }
        finalPrompt += ` CRITICAL: Do not include any text, letters, or numbers in the image.`;

        parts.push({ text: finalPrompt });

        const response = await ai.models.generateContent({
            model: selectedModel,
            contents: { parts },
            config: { systemInstruction: INFOGRAPHIC_SYSTEM_INSTRUCTION },
        });

        let generatedImageData: string | undefined;
        for (const part of response.candidates?.[0]?.content?.parts || []) {
            if (part.inlineData) {
                generatedImageData = part.inlineData.data;
                break;
            }
        }

        if (generatedImageData) {
            const imageUrl = `data:image/png;base64,${generatedImageData}`;
            const newFrames = [...frames];
            newFrames[currentFrameIndex] = imageUrl;
            setFrames(newFrames);
            updateHistory(imageUrl, true); 

            const newSceneData = [...sceneData];
            if (newSceneData[currentFrameIndex]) {
                const updatedScene = { ...newSceneData[currentFrameIndex] };
                newSceneData[currentFrameIndex] = updatedScene;
                setSceneData(newSceneData);
            }

        } else {
            throw new Error('Could not find an image in the response. It might be blocked by safety settings.');
        }
    } catch (error) {
        console.error('Error on submit:', error);
        setErrorMessage(parseError(error.message) || 'An unexpected error occurred.');
        setShowErrorModal(true);
    } finally {
        setIsLoading(false);
    }
};

  const handleGenerateSynopsis = async () => {
    if (!scriptText) return;
    setIsGeneratingSynopsis(true);
    setErrorMessage('');
    try {
      const synopsisPrompt = `Analyze the following script/story and break it down into ${synopsisNumScenes} key visual scenes. For each scene, provide a short, descriptive "title" and a "prompt". The "prompt" MUST be a detailed visual description in KOREAN, suitable for an image generation model. Respond ONLY with a valid JSON array of objects.

      Script:
      ---
      ${scriptText}
      ---
      `;

      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: synopsisPrompt,
        config: {
          responseMimeType: 'application/json',
          responseSchema: {
            type: Type.ARRAY,
            items: {
              type: Type.OBJECT,
              properties: {
                title: { type: Type.STRING },
                prompt: { type: Type.STRING },
              },
            },
          },
        },
      });

      const jsonStr = response.text;
      if (jsonStr) {
        const parsedSynopsis = JSON.parse(jsonStr);
        setGeneratedSynopsis(parsedSynopsis);
      } else {
        throw new Error('시놉시스를 생성하지 못했습니다. 모델이 빈 응답을 반환했습니다.');
      }
    } catch (error) {
      console.error('Error generating synopsis:', error);
      setErrorMessage(parseError(error.message) || '시놉시스 생성 중 오류가 발생했습니다.');
    } finally {
      setIsGeneratingSynopsis(false);
    }
  };

  const handleImportSynopsisToTimeline = () => {
    if (generatedSynopsis.length === 0) return;

    const newFrames = Array(generatedSynopsis.length).fill(null);
    setFrames(newFrames);
    setSceneData(generatedSynopsis);

    setFrameDurations(Array(generatedSynopsis.length).fill(1000)); 
    setCurrentFrameIndex(0);
    setHistory({}); 
    setHistoryIndex({});

    setShowScriptModal(false);
    setGeneratedSynopsis([]);
    setScriptText('');
  };


  const addFrame = () => {
    const newFrames = [...frames];
    newFrames.splice(currentFrameIndex + 1, 0, null);
    setFrames(newFrames);

    const newSceneData = [...sceneData];
    newSceneData.splice(currentFrameIndex + 1, 0, { title: '', prompt: '' });
    setSceneData(newSceneData);

    const newDurations = [...frameDurations];
    newDurations.splice(currentFrameIndex + 1, 0, 1000);
    setFrameDurations(newDurations);

    setCurrentFrameIndex(currentFrameIndex + 1);
  };

  const selectFrame = (index: number) => {
    if (isPlaying) setIsPlaying(false);
    setCurrentFrameIndex(index);
  };

  const deleteFrame = (index: number) => {
    if (frames.length <= 1) {
      setFrames([null]);
      setSceneData([]);
      setFrameDurations([1000]);
      setCurrentFrameIndex(0);
      return;
    }
    const newFrames = frames.filter((_, i) => i !== index);
    setFrames(newFrames);

    const newSceneData = sceneData.filter((_, i) => i !== index);
    setSceneData(newSceneData);

    const newDurations = frameDurations.filter((_, i) => i !== index);
    setFrameDurations(newDurations);

    if (currentFrameIndex >= index) {
      setCurrentFrameIndex(Math.max(0, currentFrameIndex - 1));
    }
  };

  const togglePlay = () => setIsPlaying(!isPlaying);

  const closeErrorModal = () => setShowErrorModal(false);

  const handleGenerateNarration = async () => {
    const validFrames = frames.filter((f): f is string => f !== null);
    if (validFrames.length === 0) {
      setErrorMessage('Please create an animation before generating narration.');
      setShowErrorModal(true);
      return;
    }
    setIsGeneratingNarration(true);
    try {
      const descriptionParts: any[] = [
        {
          text: 'Describe this sequence of images as a short, simple story for an animation. Focus on the main action and mood. This description will be used to create a narration script. Do not describe the style, only the content.',
        },
      ];
      validFrames.forEach((frame) => {
        descriptionParts.push({
          inlineData: {data: frame.split(',')[1], mimeType: 'image/png'},
        });
      });

      const descriptionResponse = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: {parts: descriptionParts},
      });
      const description = descriptionResponse.text ?? '';

      const scriptPrompt = `Based on the following scene description, write a short, one or two-sentence narration script in English. Include simple onomatopoeia (like "whoosh", "pop", "ding") where appropriate to make it lively. The script should be suitable for a general audience. Scene description: ${description}. The original animation idea was: ${initialPrompt}`;
      const scriptResponse = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: scriptPrompt,
      });
      const script = (scriptResponse.text ?? '').trim();
      if (!script) {
        throw new Error('Failed to generate a narration script.');
      }

      const ttsResponse = await ai.models.generateContent({
        model: 'gemini-2.5-flash-preview-tts',
        contents: [{parts: [{text: `Read this cheerfully: ${script}`}]}],
        config: {
          responseModalities: [Modality.AUDIO],
          speechConfig: {
            voiceConfig: {prebuiltVoiceConfig: {voiceName: 'Kore'}},
          },
        },
      });

      const base64Audio =
        ttsResponse.candidates?.[0]?.content?.parts?.[0]?.inlineData?.data;
      if (!base64Audio) {
        throw new Error('Audio data not found in the response.');
      }

      const pcmData = decode(base64Audio);
      const wavBlob = createWavBlob(pcmData, 24000, 1);
      const audioUrl = URL.createObjectURL(wavBlob);
      setNarrationAudio(audioUrl);
    } catch (error) {
      console.error('Narration generation failed:', error);
      setErrorMessage(
        parseError(error.message) || 'Failed to generate narration.',
      );
      setShowErrorModal(true);
    } finally {
      setIsGeneratingNarration(false);
    }
  };

  const handleExportGif = async () => {
    if (isExporting) return;
    const framesToExport = frames.filter(
      (frame): frame is string => frame !== null,
    );
    if (framesToExport.length === 0) {
      alert('There are no frames to export.');
      return;
    }

    setIsExporting(true);

    try {
      const gif = new GIF({
        workers: 2,
        quality: gifQuality,
        workerScript:
          'https://cdnjs.cloudflare.com/ajax/libs/gif.js/0.2.0/gif.worker.js',
        width: ASPECT_RATIOS[aspectRatio].width,
        height: ASPECT_RATIOS[aspectRatio].height,
      });

      const imagePromises = framesToExport.map((dataUrl) => {
        return new Promise<HTMLImageElement>((resolve, reject) => {
          const img = new Image();
          img.onload = () => resolve(img);
          img.onerror = reject;
          img.src = dataUrl;
        });
      });

      const loadedImages = await Promise.all(imagePromises);

      for (let i = 0; i < loadedImages.length; i++) {
        const image = loadedImages[i];
        const delay = frameDurations[i] || (1000 / fps);
        gif.addFrame(image, { delay });
      }

      gif.on('finished', (blob) => {
        const url = URL.createObjectURL(blob);
        const a = document.createElement('a');
        a.href = url;
        a.download = 'animation.gif';
        document.body.appendChild(a);
        a.click();
        document.body.removeChild(a);
        URL.revokeObjectURL(url);
        setIsExporting(false);
        setShowExportModal(false);
      });

      gif.render();
    } catch (error) {
      console.error('GIF export failed:', error);
      setErrorMessage('An error occurred while exporting the GIF.');
      setShowErrorModal(true);
      setIsExporting(false);
    }
  };

  const handleExportFrames = async () => {
    if (isExporting) return;
    const framesToExport = frames.filter((frame): frame is string =>
      Boolean(frame),
    );
    if (framesToExport.length === 0) {
      alert('There are no frames to export.');
      return;
    }

    setIsExporting(true);

    try {
      const zip = new JSZip();
      const format = exportFormat;
      const mimeType = `image/${format === 'jpg' ? 'jpeg' : 'png'}`;

      for (let i = 0; i < framesToExport.length; i++) {
        const frameDataUrl = framesToExport[i];
        let processedDataUrl = frameDataUrl;

        if (format === 'jpg') {
          processedDataUrl = await new Promise<string>((resolve, reject) => {
            const img = new Image();
            img.onload = () => {
              const canvas = document.createElement('canvas');
              canvas.width = img.width;
              canvas.height = img.height;
              const ctx = canvas.getContext('2d');
              if (!ctx) return reject(new Error('Canvas context unavailable'));
              ctx.fillStyle = '#FFFFFF';
              ctx.fillRect(0, 0, canvas.width, canvas.height);
              ctx.drawImage(img, 0, 0);
              resolve(canvas.toDataURL(mimeType, 0.9));
            };
            img.onerror = reject;
            img.src = frameDataUrl;
          });
        }

        const base64Data = processedDataUrl.split(',')[1];
        zip.file(
          `frame_${String(i + 1).padStart(3, '0')}.${format}`,
          base64Data,
          {base64: true},
        );
      }

      const blob = await zip.generateAsync({type: 'blob'});
      const a = document.createElement('a');
      a.href = URL.createObjectURL(blob);
      a.download = `animation_frames.zip`;
      document.body.appendChild(a);
      a.click();
      document.body.removeChild(a);
      URL.revokeObjectURL(a.href);
    } catch (error) {
      console.error('Frame export failed:', error);
      setErrorMessage(
        `An error occurred while exporting frames as ${exportFormat.toUpperCase()}.`,
      );
      setShowErrorModal(true);
    } finally {
      setIsExporting(false);
      setShowExportModal(false);
    }
  };

  const handleExportMp4 = async () => {
    if (isExporting || isExportingMp4) return;
    const framesToExport = frames.filter(
      (frame): frame is string => frame !== null,
    );
    if (framesToExport.length === 0) {
      alert('There are no frames to export.');
      return;
    }

    setIsExportingMp4(true);

    try {
      const canvas = document.createElement('canvas');
      canvas.width = ASPECT_RATIOS[aspectRatio].width;
      canvas.height = ASPECT_RATIOS[aspectRatio].height;
      const ctx = canvas.getContext('2d');
      if (!ctx) {
        throw new Error('Could not get canvas context.');
      }

      const videoStream = canvas.captureStream(fps);
      let finalStream: MediaStream = videoStream;

      if (narrationAudio) {
        const audioContext = new (window.AudioContext || (window as any).webkitAudioContext)();
        const response = await fetch(narrationAudio);
        const arrayBuffer = await response.arrayBuffer();
        const audioBuffer = await audioContext.decodeAudioData(arrayBuffer);
        const destination = audioContext.createMediaStreamDestination();
        const source = audioContext.createBufferSource();
        source.buffer = audioBuffer;
        source.connect(destination);
        const audioStream = destination.stream;
        finalStream = new MediaStream([
            ...videoStream.getVideoTracks(),
            ...audioStream.getAudioTracks()
        ]);
        source.start();
      }

      const mimeType = 'video/webm; codecs=vp9,opus';
      if (!MediaRecorder.isTypeSupported(mimeType)) {
        throw new Error(`${mimeType} is not supported in this browser.`);
      }
      const recorder = new MediaRecorder(finalStream, {mimeType});

      const chunks: Blob[] = [];
      recorder.ondataavailable = (e) => {
        if (e.data.size > 0) {
          chunks.push(e.data);
        }
      };

      recorder.onstop = () => {
        const blob = new Blob(chunks, {type: 'video/mp4'});
        const url = URL.createObjectURL(blob);
        const a = document.createElement('a');
        a.href = url;
        a.download = 'animation.mp4';
        document.body.appendChild(a);
        a.click();
        document.body.removeChild(a);
        URL.revokeObjectURL(url);
        setIsExportingMp4(false);
        setShowExportModal(false);
      };

      const imagePromises = framesToExport.map(
        (dataUrl) =>
          new Promise<HTMLImageElement>((resolve, reject) => {
            const img = new Image();
            img.onload = () => resolve(img);
            img.onerror = reject;
            img.src = dataUrl;
          }),
      );
      const loadedImages = await Promise.all(imagePromises);

      recorder.start();

      let frameIndex = 0;
      const intervalId = setInterval(() => {
        if (frameIndex >= loadedImages.length) {
          clearInterval(intervalId);
          recorder.stop();
          return;
        }
        const image = loadedImages[frameIndex];
        ctx.fillStyle = '#FFFFFF';
        ctx.fillRect(0, 0, canvas.width, canvas.height);
        ctx.drawImage(image, 0, 0, canvas.width, canvas.height);
        frameIndex++;
      }, 1000 / fps);
    } catch (error) {
      console.error('MP4 export failed:', error);
      setErrorMessage(`An error occurred while exporting the MP4: ${error.message}`);
      setShowErrorModal(true);
      setIsExportingMp4(false);
    }
  };

  const performAspectRatioChange = async (newRatio: AspectRatio) => {
    const currentFrameData = frames[currentFrameIndex];
    setShowAspectRatioConfirm(false);

    if (!currentFrameData) {
      setAspectRatio(newRatio);
      setFrames([null]);
      setFrameDurations([1000]);
      setCurrentFrameIndex(0);
      setHistory({});
      setHistoryIndex({});
      setNarrationAudio(null);
      setTargetAspectRatio(null);
      return;
    }

    setIsRecomposing(true);
    setErrorMessage('');

    try {
      const parts = [
        {
          inlineData: {
            data: currentFrameData.split(',')[1],
            mimeType: 'image/png',
          },
        },
        {
          text: `Re-compose this image to fit a ${newRatio} aspect ratio. Do not stretch or distort the main subject; instead, expand the background scenery to fit the new dimensions while maintaining the subject's proportions.`,
        },
      ];

      const response = await ai.models.generateContent({
        model: selectedModel,
        contents: {parts},
        config: {systemInstruction: RECOMPOSE_SYSTEM_INSTRUCTION},
      });

      let generatedImageData: string | undefined;
      for (const part of response.candidates?.[0]?.content?.parts || []) {
        if (part.inlineData) {
          generatedImageData = part.inlineData.data;
          break;
        }
      }

      if (generatedImageData) {
        const imageUrl = `data:image/png;base64,${generatedImageData}`;
        setAspectRatio(newRatio);
        const newFrames = Array(frames.length).fill(null);
        newFrames[0] = imageUrl;

        setFrames(newFrames);
        setFrameDurations(Array(frames.length).fill(1000));
        setCurrentFrameIndex(0);
        setHistory({0: [imageUrl]});
        setHistoryIndex({0: 0});
        setNarrationAudio(null);
        setSceneData([]);
      } else {
        throw new Error(
          'Failed to re-compose the image. The model did not return a valid image.',
        );
      }
    } catch (error) {
      console.error('Error during re-composition:', error);
      setErrorMessage(
        parseError(error.message) ||
          'An error occurred during re-composition.',
      );
      setShowErrorModal(true);
    } finally {
      setIsRecomposing(false);
      setTargetAspectRatio(null);
    }
  };

