            <div className="p-4 bg-white/60 rounded-lg shadow-sm">
                <div className="grid grid-cols-2 gap-3">
                    <button onClick={handleSaveCharacter} title="현재 프레임을 캐릭터로 저장" disabled={!frames[currentFrameIndex]} className="w-full flex items-center justify-center gap-2 h-10 px-4 rounded-full bg-white shadow-sm transition-all hover:bg-gray-50 text-gray-700 font-medium text-sm disabled:opacity-50 disabled:cursor-not-allowed"><UserPlus className="w-4 h-4" /> 캐릭터 저장</button>
                    <button onClick={() => setShowExportModal(true)} disabled={isExporting || isExportingMp4} className="w-full flex items-center justify-center gap-2 h-10 px-4 rounded-full bg-white shadow-sm transition-all hover:bg-gray-50 text-gray-700 font-medium text-sm disabled:bg-gray-200 disabled:cursor-not-allowed"><Download className="w-4 h-4" /> 콘텐츠 내보내기</button>
