       <div className="flex-grow flex items-stretch gap-4 overflow-hidden">
        <aside className="flex-shrink-0 w-48 flex flex-col gap-4 p-3 bg-white/60 rounded-lg shadow-sm overflow-y-auto">
          <div className="grid grid-cols-2 gap-2">
