                                    <label className="flex items-center p-2 rounded-md hover:bg-gray-100 cursor-pointer"><input type="radio" value="jpg" checked={exportFormat === 'jpg'} onChange={() => setExportFormat('jpg')} className="h-4 w-4 text-blue-600 border-gray-300 focus:ring-blue-500"/><span className="ml-2 text-sm text-gray-700">JPG</span></label>
                                </div>
                            </fieldset>
                            <button onClick={handleExportFrames} disabled={isExporting} className="w-full flex items-center justify-center gap-2 h-10 px-4 rounded-md bg-blue-600 text-white shadow-sm transition-all hover:bg-blue-700 disabled:bg-blue-300">
