  const handleGenerateNarration = async () => {
    const validFrames = frames.filter((f): f is string => f !== null);
    if (validFrames.length === 0) {
      setErrorMessage('Please create an animation before generating narration.');
      setShowErrorModal(true);
      return;
    }
    setIsGeneratingNarration(true);
    try {
      const descriptionParts: any[] = [
        {
          text: 'Describe this sequence of images as a short, simple story for an animation. Focus on the main action and mood. This description will be used to create a narration script. Do not describe the style, only the content.',
        },
      ];
      validFrames.forEach((frame) => {
        descriptionParts.push({
          inlineData: {data: frame.split(',')[1], mimeType: 'image/png'},
        });
      });

      const descriptionResponse = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: {parts: descriptionParts},
      });
      const description = descriptionResponse.text ?? '';

      const scriptPrompt = `Based on the following scene description, write a short, one or two-sentence narration script in English. Include simple onomatopoeia (like "whoosh", "pop", "ding") where appropriate to make it lively. The script should be suitable for a general audience. Scene description: ${description}. The original animation idea was: ${initialPrompt}`;
      const scriptResponse = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: scriptPrompt,
      });
      const script = (scriptResponse.text ?? '').trim();
      if (!script) {
        throw new Error('Failed to generate a narration script.');
      }

      const ttsResponse = await ai.models.generateContent({
        model: 'gemini-2.5-flash-preview-tts',
        contents: [{parts: [{text: `Read this cheerfully: ${script}`}]}],
        config: {
          responseModalities: [Modality.AUDIO],
          speechConfig: {
            voiceConfig: {prebuiltVoiceConfig: {voiceName: 'Kore'}},
          },
        },
      });

      const base64Audio =
        ttsResponse.candidates?.[0]?.content?.parts?.[0]?.inlineData?.data;
      if (!base64Audio) {
        throw new Error('Audio data not found in the response.');
      }

      const pcmData = decode(base64Audio);
      const wavBlob = createWavBlob(pcmData, 24000, 1);
      const audioUrl = URL.createObjectURL(wavBlob);

      const audioContext = new (window.AudioContext || (window as any).webkitAudioContext)();
      const arrayBuffer = await wavBlob.arrayBuffer();
      const audioBuffer = await audioContext.decodeAudioData(arrayBuffer);

      setAudioInfo({ url: audioUrl, duration: audioBuffer.duration, name: '생성된 내레이션.wav' });

    } catch (error) {
      console.error('Narration generation failed:', error);
      setErrorMessage(
        parseError(error.message) || 'Failed to generate narration.',
      );
      setShowErrorModal(true);
    } finally {
      setIsGeneratingNarration(false);
    }
  };

  const handleExportGif = async () => {
    if (isExporting) return;
    const framesToExport = frames.filter(
      (frame): frame is string => frame !== null,
    );
    if (framesToExport.length === 0) {
      alert('There are no frames to export.');
      return;
    }

    setIsExporting(true);

    try {
      const gif = new GIF({
        workers: 2,
        quality: gifQuality,
        workerScript:
          'https://cdnjs.cloudflare.com/ajax/libs/gif.js/0.2.0/gif.worker.js',
        width: ASPECT_RATIOS[aspectRatio].width,
        height: ASPECT_RATIOS[aspectRatio].height,
      });

      const imagePromises = framesToExport.map((dataUrl) => {
        return new Promise<HTMLImageElement>((resolve, reject) => {
          const img = new Image();
          img.onload = () => resolve(img);
          img.onerror = reject;
          img.src = dataUrl;
        });
      });

      const loadedImages = await Promise.all(imagePromises);

      for (let i = 0; i < loadedImages.length; i++) {
        const image = loadedImages[i];
        const delay = frameDurations[i] || (1000 / fps);
        gif.addFrame(image, { delay });
      }

      gif.on('finished', (blob) => {
        const url = URL.createObjectURL(blob);
        const a = document.createElement('a');
        a.href = url;
        a.download = 'animation.gif';
        document.body.appendChild(a);
        a.click();
        document.body.removeChild(a);
        URL.revokeObjectURL(url);
        setIsExporting(false);
        setShowExportModal(false);
      });

      gif.render();
    } catch (error) {
      console.error('GIF export failed:', error);
      setErrorMessage('An error occurred while exporting the GIF.');
      setShowErrorModal(true);
      setIsExporting(false);
    }
  };

  const handleExportFrames = async () => {
    if (isExporting) return;
    const framesToExport = frames.filter((frame): frame is string =>
      Boolean(frame),
    );
    if (framesToExport.length === 0) {
      alert('There are no frames to export.');
      return;
    }

    setIsExporting(true);

    try {
      const zip = new JSZip();
      const format = exportFormat;
      const mimeType = `image/${format === 'jpg' ? 'jpeg' : 'png'}`;

      for (let i = 0; i < framesToExport.length; i++) {
        const frameDataUrl = framesToExport[i];
        let processedDataUrl = frameDataUrl;

        if (format === 'jpg') {
          processedDataUrl = await new Promise<string>((resolve, reject) => {
            const img = new Image();
            img.onload = () => {
              const canvas = document.createElement('canvas');
              canvas.width = img.width;
              canvas.height = img.height;
              const ctx = canvas.getContext('2d');
              if (!ctx) return reject(new Error('Canvas context unavailable'));
              ctx.fillStyle = '#FFFFFF';
              ctx.fillRect(0, 0, canvas.width, canvas.height);
              ctx.drawImage(img, 0, 0);
              resolve(canvas.toDataURL(mimeType, 0.9));
            };
            img.onerror = reject;
            img.src = frameDataUrl;
          });
        }

        const base64Data = processedDataUrl.split(',')[1];
        zip.file(
          `frame_${String(i + 1).padStart(3, '0')}.${format}`,
          base64Data,
          {base64: true},
        );
      }

      const blob = await zip.generateAsync({type: 'blob'});
      const a = document.createElement('a');
      a.href = URL.createObjectURL(blob);
      a.download = `animation_frames.zip`;
      document.body.appendChild(a);
      a.click();
      document.body.removeChild(a);
      URL.revokeObjectURL(a.href);
    } catch (error) {
      console.error('Frame export failed:', error);
      setErrorMessage(
        `An error occurred while exporting frames as ${exportFormat.toUpperCase()}.`,
      );
      setShowErrorModal(true);
    } finally {
      setIsExporting(false);
      setShowExportModal(false);
    }
  };

  const handleExportMp4 = async () => {
    if (isExporting || isExportingMp4) return;
    const framesToExport = frames.filter(
      (frame): frame is string => frame !== null,
    );
    if (framesToExport.length === 0) {
      alert('There are no frames to export.');
      return;
    }

    setIsExportingMp4(true);

    try {
      const canvas = document.createElement('canvas');
      canvas.width = ASPECT_RATIOS[aspectRatio].width;
      canvas.height = ASPECT_RATIOS[aspectRatio].height;
      const ctx = canvas.getContext('2d');
      if (!ctx) {
        throw new Error('Could not get canvas context.');
      }

      const videoStream = canvas.captureStream(fps);
      let finalStream: MediaStream = videoStream;

      if (audioInfo?.url) {
        const audioContext = new (window.AudioContext || (window as any).webkitAudioContext)();
        const response = await fetch(audioInfo.url);
        const arrayBuffer = await response.arrayBuffer();
        const audioBuffer = await audioContext.decodeAudioData(arrayBuffer);
        const destination = audioContext.createMediaStreamDestination();
        const source = audioContext.createBufferSource();
        source.buffer = audioBuffer;
        source.connect(destination);
        const audioStream = destination.stream;
        finalStream = new MediaStream([
            ...videoStream.getVideoTracks(),
            ...audioStream.getAudioTracks()
        ]);
        source.start();
      }

      const mimeType = 'video/webm; codecs=vp9,opus';
      if (!MediaRecorder.isTypeSupported(mimeType)) {
        throw new Error(`${mimeType} is not supported in this browser.`);
      }
      const recorder = new MediaRecorder(finalStream, {mimeType});

      const chunks: Blob[] = [];
      recorder.ondataavailable = (e) => {
        if (e.data.size > 0) {
          chunks.push(e.data);
        }
      };

      recorder.onstop = () => {
        const blob = new Blob(chunks, {type: 'video/mp4'});
        const url = URL.createObjectURL(blob);
        const a = document.createElement('a');
        a.href = url;
        a.download = 'animation.mp4';
        document.body.appendChild(a);
        a.click();
        document.body.removeChild(a);
        URL.revokeObjectURL(url);
        setIsExportingMp4(false);
        setShowExportModal(false);
      };

      const imagePromises = framesToExport.map(
        (dataUrl) =>
          new Promise<HTMLImageElement>((resolve, reject) => {
            const img = new Image();
            img.onload = () => resolve(img);
            img.onerror = reject;
            img.src = dataUrl;
          }),
      );
      const loadedImages = await Promise.all(imagePromises);

      recorder.start();

      let frameIndex = 0;
      const intervalId = setInterval(() => {
        if (frameIndex >= loadedImages.length) {
          clearInterval(intervalId);
          recorder.stop();
          return;
        }
        const image = loadedImages[frameIndex];
        ctx.fillStyle = '#FFFFFF';
        ctx.fillRect(0, 0, canvas.width, canvas.height);
        ctx.drawImage(image, 0, 0, canvas.width, canvas.height);
        frameIndex++;
      }, 1000 / fps);
    } catch (error) {
      console.error('MP4 export failed:', error);
      setErrorMessage(`An error occurred while exporting the MP4: ${error.message}`);
      setShowErrorModal(true);
      setIsExportingMp4(false);
    }
  };

  const performAspectRatioChange = async (newRatio: AspectRatio) => {
