    setSelectedCharacterIndices(prev => prev.filter(i => i !== indexToRemove));
  };

  const handleAnimateFrame = async (index: number, frameCount: number) => {
      const startFrame = frames[index];
      const endFrame = frames[index + 1];
      setShowAnimateModal(false);

      if (typeof startFrame !== 'string' || typeof endFrame !== 'string') {
          setErrorMessage('애니메이션을 만들려면 시작 프레임과 끝 프레임이 모두 단일 이미지여야 합니다.');
          setShowErrorModal(true);
          return;
      }
      setIsAnimatingFrame(index);
      try {
          const animPrompt = `Create ${frameCount} intermediate frames (in-betweens) to smoothly animate the transition from the first image to the second image. The output should be a sequence of images representing the motion. CRITICAL: Do not include any text, letters, or numbers in the images. The images must be purely visual. Maintain the aspect ratio and art style.`;

          const response = await ai.models.generateContent({
              model: selectedModel,
              contents: {
                  parts: [
                      { inlineData: { data: startFrame.split(',')[1], mimeType: 'image/png' } },
                      { inlineData: { data: endFrame.split(',')[1], mimeType: 'image/png' } },
                      { text: animPrompt }
                  ]
              },
              config: {
                systemInstruction: RECOMPOSE_SYSTEM_INSTRUCTION, 
                imageConfig: {
                    aspectRatio: aspectRatio,
                },
              }
          });

          const generatedSubFrames: string[] = [];
          for (const part of response.candidates?.[0]?.content?.parts || []) {
              if (part.inlineData) {
                  generatedSubFrames.push(`data:image/png;base64,${part.inlineData.data}`);
              }
          }

          if (generatedSubFrames.length > 1) {
              const newFrames = [...frames];
              newFrames[index] = generatedSubFrames;
              setFrames(newFrames);
              updateHistory(generatedSubFrames, true);
          } else {
              throw new Error("애니메이션 프레임을 생성하지 못했습니다. 모델이 충분한 이미지를 반환하지 않았습니다.");
          }

      } catch (error) {
          console.error("Error animating frame:", error);
          setErrorMessage(parseError(error.message) || '프레임 애니메이션 중 오류가 발생했습니다.');
          setShowErrorModal(true);
      } finally {
        setIsAnimatingFrame(-1);
      }
  };

  useEffect(() => {
