      const scriptPrompt = `Based on the following scene description, write a short, one or two-sentence narration script in English. Include simple onomatopoeia (like "whoosh", "pop", "ding") where appropriate to make it lively. The script should be suitable for a general audience. Scene description: ${description}.`;
