  const processScriptWithSettings = async () => {
    if (!scriptText) return;
    setIsGeneratingSynopsis(true);
    setErrorMessage('');

    let chunkSize: number;
    if (chunkingMode === 'simple') {
      const len = scriptText.length;
      if (simpleChunkSize === 'short') {
        chunkSize = len < 1500 ? 200 : len < 4000 ? 400 : 700;
      } else if (simpleChunkSize === 'long') {
        chunkSize = len < 1500 ? 400 : len < 4000 ? 700 : 1000;
      } else { // medium
        chunkSize = len < 1500 ? 300 : len < 4000 ? 500 : 800;
      }
    } else { // detailed
      chunkSize = detailedChunkValue;
    }

    const scriptChunks = [];
    for (let i = 0; i < scriptText.length; i += chunkSize) {
        scriptChunks.push(scriptText.substring(i, i + chunkSize));
    }
    if (scriptChunks.length === 0) {
      setIsGeneratingSynopsis(false);
      return;
    }

    try {
      const synopsisPrompt = `Analyze the following array of script chunks. For each chunk, create a corresponding JSON object with a short, descriptive "title" and a detailed "prompt" for an image generation model. The "prompt" MUST be in KOREAN. Respond ONLY with a valid JSON array of these objects, with one object per input chunk.

      Script Chunks:
      ---
      ${JSON.stringify(scriptChunks)}
      ---
      `;

      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: synopsisPrompt,
        config: {
          responseMimeType: 'application/json',
          responseSchema: {
            type: Type.ARRAY,
            items: {
              type: Type.OBJECT,
              properties: {
                title: { type: Type.STRING },
                prompt: { type: Type.STRING },
              },
            },
          },
        },
      });

      const jsonStr = response.text;
      if (jsonStr) {
        const parsedSynopsis = JSON.parse(jsonStr);
        if (parsedSynopsis.length === 0) throw new Error("시놉시스를 생성하지 못했습니다.");

        setFrames(Array(parsedSynopsis.length).fill(null));
        setSceneData(parsedSynopsis);
        setFrameDurations(Array(parsedSynopsis.length).fill(1000)); 
        setCurrentFrameIndex(0);
        setHistory({}); 
        setHistoryIndex({});
        setShowScriptModal(false);
        setScriptText('');
      } else {
        throw new Error('시놉시스를 생성하지 못했습니다. 모델이 빈 응답을 반환했습니다.');
      }
    } catch (error) {
      console.error('Error generating synopsis:', error);
      setErrorMessage(parseError(error) || '시놉시스 생성 중 오류가 발생했습니다.');
