  const handleSaveCharacter = () => {
    const currentFrame = frames[currentFrameIndex];
    if (currentFrame && typeof currentFrame === 'string') {
        setCast([...cast, currentFrame]);
    } else {
        setErrorMessage('Cannot save an empty or animated frame as a character.');
        setShowErrorModal(true);
    }
  };

  const handleSelectCharacter = (index: number) => {
    setSelectedCharacterIndices(prev => 
        prev.includes(index) 
        ? prev.filter(i => i !== index)
        : [...prev, index]
    );
  };

  const handleRemoveCharacter = (
    e: React.MouseEvent,
    indexToRemove: number,
  ) => {
    e.stopPropagation();
    setCast(cast.filter((_, index) => index !== indexToRemove));
    setSelectedCharacterIndices(prev => prev.filter(i => i !== indexToRemove));
  };

  const handleAnimateFrame = async (index: number, frameCount: number) => {
      const sourceFrame = frames[index];
      const sourcePrompt = sceneData[index]?.prompt || '';
      setShowAnimateModal(false);

      if (typeof sourceFrame !== 'string') {
          setErrorMessage('애니메이션을 만들려면 원본 프레임이 단일 이미지여야 합니다.');
          setShowErrorModal(true);
          return;
      }
      setIsAnimatingFrame(index);
      try {
          const animPrompt = `Based on the following context, create a coherent and dynamic animated scene.

          **Original Scene Context:** "${sourcePrompt}"

          Your task is to generate a sequence of **${frameCount} frames**. This sequence should start with the provided image and evolve into a new, logical final state that tells a mini-story.`;

          const response = await ai.models.generateContent({
              model: selectedModel,
              contents: {
                  parts: [
                      { inlineData: { data: sourceFrame.split(',')[1], mimeType: 'image/png' } },
                      { text: animPrompt }
                  ]
              },
              config: {
                systemInstruction: SCENE_ANIMATION_SYSTEM_INSTRUCTION, 
                imageConfig: {
                    aspectRatio: aspectRatio,
                },
              }
          });

          const generatedSubFrames: string[] = [];
          for (const part of response.candidates?.[0]?.content?.parts || []) {
              if (part.inlineData) {
                  generatedSubFrames.push(`data:image/png;base64,${part.inlineData.data}`);
              }
          }

          if (generatedSubFrames.length > 1) {
              const newFrames = [...frames];
              newFrames[index] = generatedSubFrames;
              setFrames(newFrames);
              updateHistory(generatedSubFrames, true);
          } else {
              throw new Error("애니메이션 프레임을 생성하지 못했습니다. 모델이 충분한 이미지를 반환하지 않았습니다.");
          }

      } catch (error) {
          console.error("Error animating frame:", error);
          setErrorMessage(parseError(error) || '프레임 애니메이션 중 오류가 발생했습니다.');
          setShowErrorModal(true);
      } finally {
        setIsAnimatingFrame(-1);
      }
  };

  useEffect(() => {
    const preventDefault = (e: TouchEvent) => {
      if (isInteracting.current && canvasRef.current?.contains(e.target as Node)) {
          e.preventDefault();
      }
    };

    document.addEventListener('touchstart', preventDefault, { passive: false });
    document.addEventListener('touchmove', preventDefault, { passive: false });

    const handlePaste = (e: ClipboardEvent) => {
        const items = e.clipboardData?.items;
        if (!items) return;
        for (let i = 0; i < items.length; i++) {
            if (items[i].type.indexOf('image') !== -1) {
                const file = items[i].getAsFile();
                if (file) {
                    processImageFile(file);
                    e.preventDefault();
                    return;
                }
            }
        }
    };

    window.addEventListener('paste', handlePaste);

    return () => {
      document.removeEventListener('touchstart', preventDefault);
      document.removeEventListener('touchmove', preventDefault);
      window.removeEventListener('paste', handlePaste);
    };
  }, [frames, currentFrameIndex, aspectRatio]);

  const handleDragOver = (e: React.DragEvent) => {
    e.preventDefault();
  };

  const handleDrop = (e: React.DragEvent) => {
