  const [audioInfo, setAudioInfo] = useState<{ url: string; duration: number; name: string; } | null>(null);
  const [isGeneratingNarration, setIsGeneratingNarration] = useState(false);
  const [isProcessingAudio, setIsProcessingAudio] = useState(false);
  const audioInputRef = useRef<HTMLInputElement>(null);
  const audioRef = useRef<HTMLAudioElement>(null);

  const [aspectRatio, setAspectRatio] = useState<AspectRatio>('16:9');
  const [showAspectRatioConfirm, setShowAspectRatioConfirm] = useState(false);
  const [targetAspectRatio, setTargetAspectRatio] =
    useState<AspectRatio | null>(null);

  const [history, setHistory] = useState<{ [key: number]: (string | string[])[] }>({});
  const [historyIndex, setHistoryIndex] = useState<{ [key: number]: number }>(
    {},
  );

  const fileInputRef = useRef<HTMLInputElement>(null);

  const [cast, setCast] = useState<string[]>([]);
  const [selectedCharacterIndices, setSelectedCharacterIndices] = useState<number[]>([]);

  const [showExportModal, setShowExportModal] = useState(false);
  const [exportFormat, setExportFormat] = useState<'png' | 'jpg'>('png');
  const [gifQuality, setGifQuality] = useState(10);

  const [selectedStyle, setSelectedStyle] = useState<string | null>(null);

  const [showScriptModal, setShowScriptModal] = useState(false);
  const [scriptText, setScriptText] = useState('');
  const [isGeneratingSynopsis, setIsGeneratingSynopsis] = useState(false);
  const [sceneData, setSceneData] = useState<SynopsisScene[]>([]);
  const [showSettings, setShowSettings] = useState(false);

  // New state for chunking settings
  const [showChunkSettingsModal, setShowChunkSettingsModal] = useState(false);
  const [chunkingSource, setChunkingSource] = useState<'script' | 'audio' | null>(null);
  const [chunkingMode, setChunkingMode] = useState<'simple' | 'detailed'>('simple');
  const [simpleChunkSize, setSimpleChunkSize] = useState<'short' | 'medium' | 'long'>('medium');
  const [detailedChunkType, setDetailedChunkType] = useState<'time' | 'chars'>('time');
  const [detailedChunkValue, setDetailedChunkValue] = useState(10);
  const [audioFileToProcess, setAudioFileToProcess] = useState<File | null>(null);
  const [audioDuration, setAudioDuration] = useState(0); // To calculate expected frames
  const [isAnimatingFrame, setIsAnimatingFrame] = useState(-1);

  // State for the animation frame count modal
  const [showAnimateModal, setShowAnimateModal] = useState(false);
  const [animationTargetIndex, setAnimationTargetIndex] = useState(-1);
  const [animationFrameCount, setAnimationFrameCount] = useState(8);

  const drawCanvasContent = (canvas: HTMLCanvasElement | null, dataUrl: string | string[] | null) => {
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    ctx.clearRect(0, 0, canvas.width, canvas.height);

    let imageUrl: string | null = null;
    if (Array.isArray(dataUrl)) {
      imageUrl = dataUrl[0];
    } else {
      imageUrl = dataUrl;
    }

    if (imageUrl) {
      const img = new Image();
      img.onload = () => {
        ctx.drawImage(img, 0, 0);
      };
      img.src = imageUrl;
    }
  };

  useEffect(() => {
    const currentFrame = frames[currentFrameIndex];
    if (subFramePlaybackRef.current) {
        clearInterval(subFramePlaybackRef.current);
        subFramePlaybackRef.current = null;
    }

    if (Array.isArray(currentFrame)) {
        let localSubIndex = 0;
        subFramePlaybackRef.current = window.setInterval(() => {
            localSubIndex = (localSubIndex + 1) % currentFrame.length;
            setSubFrameIndex(localSubIndex);
        }, 1000 / fps);
    } else {
        setSubFrameIndex(0); // Reset for single frames
    }

    return () => {
        if (subFramePlaybackRef.current) {
            clearInterval(subFramePlaybackRef.current);
        }
    };
  }, [currentFrameIndex, frames, fps]);

  useEffect(() => {
    if (viewMode === 'editor') {
      drawCanvasContent(canvasRef.current, frames[currentFrameIndex]);
    }
  }, [frames, currentFrameIndex, viewMode]);

  useEffect(() => {
    const currentScene = sceneData[currentFrameIndex];
    if (viewMode === 'editor' && currentScene && !frames[currentFrameIndex]) {
      setPrompt(currentScene.prompt);
    }
  }, [currentFrameIndex, sceneData, frames, viewMode]);

  useEffect(() => {
    const overlayCanvas = overlayCanvasRef.current;
    if (overlayCanvas) {
      const overlayCtx = overlayCanvas.getContext('2d');
      overlayCtx?.clearRect(0, 0, overlayCanvas.width, overlayCanvas.height);
    }
  }, [activeTool]);

  // Combined Playback Logic
  useEffect(() => {
    const audioEl = audioRef.current;

    const handleTimeUpdate = () => {
      if (!audioEl) return;
      const currentTime = audioEl.currentTime;
      let cumulativeTime = 0;
      for (let i = 0; i < frameDurations.length; i++) {
        cumulativeTime += frameDurations[i] / 1000;
        if (currentTime < cumulativeTime) {
          if (currentFrameIndex !== i) {
            setCurrentFrameIndex(i);
          }
          break;
        }
      }
    };

    const playNextVisualFrame = () => {
      const nextIndex = (currentFrameIndex + 1) % frames.length;
      setCurrentFrameIndex(nextIndex);
      const nextDuration = frameDurations[nextIndex] ?? 1000;
      playbackTimeoutRef.current = window.setTimeout(playNextVisualFrame, nextDuration);
    };

    if (isPlaying) {
      if (audioEl && audioInfo) {
        audioEl.play();
        audioEl.addEventListener('timeupdate', handleTimeUpdate);
        audioEl.addEventListener('ended', () => setIsPlaying(false));
      } else {
        // Fallback to visual-only timer if no audio
        const currentDuration = frameDurations[currentFrameIndex] ?? 1000;
        playbackTimeoutRef.current = window.setTimeout(playNextVisualFrame, currentDuration);
      }
    } else {
      if (audioEl) {
        audioEl.pause();
      }
      if (playbackTimeoutRef.current) {
        clearTimeout(playbackTimeoutRef.current);
      }
    }

    return () => {
      if (audioEl) {
        audioEl.removeEventListener('timeupdate', handleTimeUpdate);
      }
      if (playbackTimeoutRef.current) {
        clearTimeout(playbackTimeoutRef.current);
      }
    };
  }, [isPlaying, audioInfo, frames.length, frameDurations, currentFrameIndex]);

  const getCoordinates = (e: React.MouseEvent | React.TouchEvent) => {
    const canvas = canvasRef.current;
    if (!canvas) return { x: 0, y: 0 };
    const rect = canvas.getBoundingClientRect();

    const clientX = 'touches' in e ? e.touches[0].clientX : e.clientX;
    const clientY = 'touches' in e ? e.touches[0].clientY : e.clientY;

    const elementX = clientX - rect.left;
    const elementY = clientY - rect.top;

    const bitmapX = elementX * (canvas.width / rect.width);
    const bitmapY = elementY * (canvas.height / rect.height);

    const transformedX = (bitmapX - pan.x) / zoom;
    const transformedY = (bitmapY - pan.y) / zoom;

    return {
      x: transformedX,
      y: transformedY,
    };
  };

  const startInteraction = (e: React.MouseEvent | React.TouchEvent) => {
    if ('touches' in e) e.preventDefault();
    if (isPlaying) setIsPlaying(false);

    isInteracting.current = true;

    if (activeTool === 'pan') {
      const clientX = 'touches' in e ? e.touches[0].clientX : e.clientX;
      const clientY = 'touches' in e ? e.touches[0].clientY : e.clientY;
      lastPosition.current = { x: clientX, y: clientY };
    } else {
      const { x, y } = getCoordinates(e);
      let ctx: CanvasRenderingContext2D | null | undefined;

      if (activeTool === 'ai-eraser') {
        ctx = overlayCanvasRef.current?.getContext('2d');
      } else {
        ctx = canvasRef.current?.getContext('2d');
      }

      if (!ctx) return;

      ctx.beginPath();
      ctx.moveTo(x, y);
    }
  };

  const moveInteraction = (e: React.MouseEvent | React.TouchEvent) => {
    if (!isInteracting.current) return;
    if ('touches' in e) e.preventDefault();

    if (activeTool === 'pan') {
      const clientX = 'touches' in e ? e.touches[0].clientX : e.clientX;
      const clientY = 'touches' in e ? e.touches[0].clientY : e.clientY;
      const dx = clientX - lastPosition.current.x;
      const dy = clientY - lastPosition.current.y;
      setPan({ x: pan.x + dx, y: pan.y + dy });
      lastPosition.current = { x: clientX, y: clientY };
    } else {
        const { x, y } = getCoordinates(e);
        let ctx: CanvasRenderingContext2D | null | undefined;

        if (activeTool === 'ai-eraser') {
            ctx = overlayCanvasRef.current?.getContext('2d');
            if (ctx) {
                ctx.strokeStyle = 'rgba(255, 255, 0, 0.5)';
                ctx.lineWidth = eraserSize;
                ctx.lineCap = 'round';
                ctx.globalCompositeOperation = 'source-over';
            }
        } else {
            ctx = canvasRef.current?.getContext('2d');
            if (ctx) {
                if (activeTool === 'pen') {
                    ctx.globalCompositeOperation = 'source-over';
                    ctx.lineWidth = penSize;
                    ctx.strokeStyle = penColor;
                } else { // eraser
                    ctx.globalCompositeOperation = 'destination-out';
                    ctx.lineWidth = eraserSize;
                }
                ctx.lineCap = 'round';
            }
        }

        if (!ctx) return;
        ctx.lineTo(x, y);
        ctx.stroke();
    }
  };

  const handleAiInpaint = async () => {
    const canvas = canvasRef.current;
    if (!canvas) return;

    const erasedImageData = canvas.toDataURL('image/png');

    const newFrames = [...frames];
    newFrames[currentFrameIndex] = erasedImageData;
    setFrames(newFrames);
    updateHistory(erasedImageData);

    setIsLoading(true);

    try {
        const aiPrompt = `This is an inpainting request. The transparent pixels in this image should be filled in. Use the surrounding image content and style to fill the transparent area. Additionally, follow this user instruction: ${prompt || 'seamlessly blend with the background'}. CRITICAL: Do not include any text, letters, or numbers in the image.`;

        const parts = [
            { inlineData: { data: erasedImageData.split(',')[1], mimeType: 'image/png' } },
            { text: aiPrompt }
        ];

        const response = await ai.models.generateContent({
            model: selectedModel,
            contents: { parts },
            config: {
                imageConfig: {
                    aspectRatio: aspectRatio,
                },
            },
        });

        let generatedImageData: string | undefined;
        for (const part of response.candidates?.[0]?.content?.parts || []) {
            if (part.inlineData) {
                generatedImageData = part.inlineData.data;
                break;
            }
        }

        if (generatedImageData) {
            const imageUrl = `data:image/png;base64,${generatedImageData}`;
            const finalFrames = [...frames];
            finalFrames[currentFrameIndex] = imageUrl;
            setFrames(finalFrames);
            updateHistory(imageUrl);
            setPrompt('');
        } else {
            throw new Error('AI 지우개 작업에 실패했습니다. 안전 설정에 의해 차단되었을 수 있습니다.');
        }
    } catch (error) {
        console.error('AI inpainting failed:', error);
        setErrorMessage(parseError(error) || 'AI 지우개 작업 중 오류가 발생했습니다.');
        setShowErrorModal(true);
        handleUndo();
    } finally {
        setIsLoading(false);
    }
  };

  const stopInteraction = () => {
    if (!isInteracting.current) return;
    isInteracting.current = false;

    if (activeTool === 'pan') return;

    let targetCanvas: HTMLCanvasElement | null = null;
    if (activeTool === 'ai-eraser') {
      targetCanvas = overlayCanvasRef.current;
    } else {
      targetCanvas = canvasRef.current;
    }

    if (!targetCanvas) return;
    const ctx = targetCanvas.getContext('2d');
    if (ctx) ctx.closePath();

    if (activeTool === 'ai-eraser') {
        const mainCanvas = canvasRef.current;
        const overlayCanvas = overlayCanvasRef.current;
        if (!mainCanvas || !overlayCanvas) return;
        const mainCtx = mainCanvas.getContext('2d');
        const overlayCtx = overlayCanvas.getContext('2d');
        if (!mainCtx || !overlayCtx) return;

        mainCtx.globalCompositeOperation = 'destination-out';
        mainCtx.drawImage(overlayCanvas, 0, 0);
        mainCtx.globalCompositeOperation = 'source-over'; 

        overlayCtx.clearRect(0, 0, overlayCanvas.width, overlayCanvas.height);

        handleAiInpaint();
    } else {
         const dataUrl = targetCanvas.toDataURL('image/png');
         updateHistory(dataUrl);
         const newFrames = [...frames];
         newFrames[currentFrameIndex] = dataUrl;
         setFrames(newFrames);
    }
  };

  const updateHistory = (dataUrl: string | string[], replace = false) => {
    const currentIndex = historyIndex[currentFrameIndex] ?? -1;
    const currentHistory = history[currentFrameIndex] || [];
    const newHistory = replace
      ? [dataUrl]
      : [...currentHistory.slice(0, currentIndex + 1), dataUrl];

    setHistory({...history, [currentFrameIndex]: newHistory});
    setHistoryIndex({
      ...historyIndex,
      [currentFrameIndex]: newHistory.length - 1,
    });
  };

  const handleUndo = () => {
    const currentIndex = historyIndex[currentFrameIndex] ?? 0;
    if (currentIndex <= 0) return;

    const newIndex = currentIndex - 1;
    setHistoryIndex({...historyIndex, [currentFrameIndex]: newIndex});

    const dataUrl = history[currentFrameIndex][newIndex];
    const newFrames = [...frames];
    newFrames[currentFrameIndex] = dataUrl;
    setFrames(newFrames);
  };

  const handleRedo = () => {
    const currentIndex = historyIndex[currentFrameIndex] ?? -1;
    const frameHistory = history[currentFrameIndex] || [];
    if (currentIndex >= frameHistory.length - 1) return;

    const newIndex = currentIndex + 1;
    setHistoryIndex({...historyIndex, [currentFrameIndex]: newIndex});

    const dataUrl = frameHistory[newIndex];
    const newFrames = [...frames];
    newFrames[currentFrameIndex] = dataUrl;
    setFrames(newFrames);
  };

  const clearCanvas = () => {
    const newFrames = [...frames];
    newFrames[currentFrameIndex] = null;
    setFrames(newFrames);

    const newSceneData = [...sceneData];
    if (newSceneData[currentFrameIndex]) {
        newSceneData[currentFrameIndex] = { title: '', prompt: '' }; 
        setSceneData(newSceneData);
    }

    const newHistory = {...history};
    delete newHistory[currentFrameIndex];
    setHistory(newHistory);
    const newHistoryIdx = {...historyIndex};
    delete newHistoryIdx[currentFrameIndex];
    setHistoryIndex(newHistoryIdx);
  };

  const handleColorChange = (e: ChangeEvent<HTMLInputElement>) =>
    setPenColor(e.target.value);

  const openColorPicker = () =>
    (colorInputRef.current as HTMLInputElement)?.click();

  const processImageFile = (file: File) => {
    if (file && file.type.startsWith('image/')) {
        const reader = new FileReader();
        reader.onloadend = () => {
            const dataUrl = reader.result as string;

            const tempCanvas = document.createElement('canvas');
            const targetDims = ASPECT_RATIOS[aspectRatio];
            tempCanvas.width = targetDims.width;
            tempCanvas.height = targetDims.height;
            const ctx = tempCanvas.getContext('2d');
            if (!ctx) return;

            const img = new Image();
            img.onload = () => {
                ctx.fillStyle = '#FFFFFF';
                ctx.fillRect(0, 0, tempCanvas.width, tempCanvas.height);
                const hRatio = tempCanvas.width / img.width;
                const vRatio = tempCanvas.height / img.height;
                const ratio = Math.min(hRatio, vRatio);
                const centerShift_x = (tempCanvas.width - img.width * ratio) / 2;
                const centerShift_y = (tempCanvas.height - img.height * ratio) / 2;
                ctx.drawImage(img, 0, 0, img.width, img.height, 
                              centerShift_x, centerShift_y, img.width * ratio, img.height * ratio);

                const finalDataUrl = tempCanvas.toDataURL('image/png');
                const newFrames = [...frames];
                newFrames[currentFrameIndex] = finalDataUrl;
                setFrames(newFrames);
                updateHistory(finalDataUrl, true);

                const newSceneData = [...sceneData];
                if (newSceneData[currentFrameIndex]) {
                    newSceneData[currentFrameIndex] = { title: '', prompt: '' };
                    setSceneData(newSceneData);
                }

            };
            img.src = dataUrl;
        };
        reader.readAsDataURL(file);
    }
  };

  const handleImageUpload = (e: ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      processImageFile(file);
    }
    e.target.value = '';
  };

  const handleStyleSelect = (stylePrompt: string) => {
    if (selectedStyle === stylePrompt) {
      setSelectedStyle(null);
    } else {
      setSelectedStyle(stylePrompt);
    }
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!prompt) return;
    setIsLoading(true);

    try {
        const parts: any[] = [];

        selectedCharacterIndices.forEach(index => {
            const charImage = cast[index];
            parts.push({
                inlineData: { data: charImage.split(',')[1], mimeType: 'image/png' }
            });
        });

        const systemInstruction = selectedCharacterIndices.length > 0
            ? CHARACTER_GENERATION_SYSTEM_INSTRUCTION
            : CREATIVE_IMAGE_SYSTEM_INSTRUCTION;

        let finalPrompt = prompt;
        if (selectedCharacterIndices.length > 0) {
            finalPrompt = `Using the provided character reference image, redraw the character to match this description: "${prompt}". Maintain the character's core design and style, but change its pose and expression as described.`;
        }

        if (selectedStyle) {
            finalPrompt += ` Draw the result in this style: ${selectedStyle}.`;
        }

        finalPrompt += ` CRITICAL: Do not include any text, letters, or numbers in the image.`;

        parts.push({ text: finalPrompt });

        const response = await ai.models.generateContent({
            model: selectedModel,
            contents: { parts },
            config: {
                systemInstruction: systemInstruction,
                imageConfig: {
                    aspectRatio: aspectRatio,
                },
            },
        });

        let generatedImageData: string | undefined;
        for (const part of response.candidates?.[0]?.content?.parts || []) {
            if (part.inlineData) {
                generatedImageData = part.inlineData.data;
                break;
            }
        }

        if (generatedImageData) {
            const imageUrl = `data:image/png;base64,${generatedImageData}`;
            const newFrames = [...frames];
            newFrames[currentFrameIndex] = imageUrl;
            setFrames(newFrames);
            updateHistory(imageUrl, true); 

            const newSceneData = [...sceneData];
            while (newSceneData.length <= currentFrameIndex) {
              newSceneData.push({ title: `장면 ${newSceneData.length + 1}`, prompt: '' });
            }
            newSceneData[currentFrameIndex].prompt = prompt;
            setSceneData(newSceneData);

        } else {
            throw new Error('Could not find an image in the response. It might be blocked by safety settings.');
        }
    } catch (error) {
        console.error('Error on submit:', error);
        setErrorMessage(parseError(error) || 'An unexpected error occurred.');
        setShowErrorModal(true);
    } finally {
        setIsLoading(false);
    }
};

  const processScriptWithSettings = async () => {
    if (!scriptText) return;
    setIsGeneratingSynopsis(true);
    setErrorMessage('');

    let chunkSize: number;
    if (chunkingMode === 'simple') {
      const len = scriptText.length;
      if (simpleChunkSize === 'short') {
        chunkSize = len < 1500 ? 200 : len < 4000 ? 400 : 700;
      } else if (simpleChunkSize === 'long') {
        chunkSize = len < 1500 ? 400 : len < 4000 ? 700 : 1000;
      } else { // medium
        chunkSize = len < 1500 ? 300 : len < 4000 ? 500 : 800;
      }
    } else { // detailed
      chunkSize = detailedChunkValue;
    }

    const scriptChunks = [];
    for (let i = 0; i < scriptText.length; i += chunkSize) {
        scriptChunks.push(scriptText.substring(i, i + chunkSize));
    }
    if (scriptChunks.length === 0) {
      setIsGeneratingSynopsis(false);
      return;
    }

    try {
      const synopsisPrompt = `Analyze the following array of script chunks. For each chunk, create a corresponding JSON object with a short, descriptive "title" and a detailed "prompt" for an image generation model. The "prompt" MUST be in KOREAN. Respond ONLY with a valid JSON array of these objects, with one object per input chunk.

      Script Chunks:
      ---
      ${JSON.stringify(scriptChunks)}
      ---
      `;

      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: synopsisPrompt,
        config: {
          responseMimeType: 'application/json',
          responseSchema: {
            type: Type.ARRAY,
            items: {
              type: Type.OBJECT,
              properties: {
                title: { type: Type.STRING },
                prompt: { type: Type.STRING },
              },
            },
          },
        },
      });

      const jsonStr = response.text;
      if (jsonStr) {
        const parsedSynopsis = JSON.parse(jsonStr);
        if (parsedSynopsis.length === 0) throw new Error("시놉시스를 생성하지 못했습니다.");

        setFrames(Array(parsedSynopsis.length).fill(null));
        setSceneData(parsedSynopsis);
        setFrameDurations(Array(parsedSynopsis.length).fill(1000)); 
        setCurrentFrameIndex(0);
        setHistory({}); 
        setHistoryIndex({});
        setShowScriptModal(false);
        setScriptText('');
      } else {
        throw new Error('시놉시스를 생성하지 못했습니다. 모델이 빈 응답을 반환했습니다.');
      }
    } catch (error) {
      console.error('Error generating synopsis:', error);
      setErrorMessage(parseError(error) || '시놉시스 생성 중 오류가 발생했습니다.');
      setShowErrorModal(true);
    } finally {
      setIsGeneratingSynopsis(false);
      setShowChunkSettingsModal(false);
    }
  };

  const addFrame = () => {
    const newFrames = [...frames];
    newFrames.splice(currentFrameIndex + 1, 0, null);
    setFrames(newFrames);

    const newSceneData = [...sceneData];
    newSceneData.splice(currentFrameIndex + 1, 0, { title: '', prompt: '' });
    setSceneData(newSceneData);

    const newDurations = [...frameDurations];
    newDurations.splice(currentFrameIndex + 1, 0, 1000);
    setFrameDurations(newDurations);

    setCurrentFrameIndex(currentFrameIndex + 1);
  };

  const selectFrame = (index: number) => {
    if (isPlaying) setIsPlaying(false);
    setCurrentFrameIndex(index);
  };

  const deleteFrame = (index: number) => {
    if (frames.length <= 1) {
      setFrames([null]);
      setSceneData([]);
      setFrameDurations([1000]);
      setCurrentFrameIndex(0);
      return;
    }
    const newFrames = frames.filter((_, i) => i !== index);
    setFrames(newFrames);

    const newSceneData = sceneData.filter((_, i) => i !== index);
    setSceneData(newSceneData);

    const newDurations = frameDurations.filter((_, i) => i !== index);
    setFrameDurations(newDurations);

    if (currentFrameIndex >= index) {
      setCurrentFrameIndex(Math.max(0, currentFrameIndex - 1));
    }
  };

  const togglePlay = () => setIsPlaying(!isPlaying);

  const closeErrorModal = () => setShowErrorModal(false);

  const processAudioWithSettings = async (file: File, duration: number) => {
    setIsProcessingAudio(true);
    setErrorMessage('');

    const fileReader = new FileReader();
    fileReader.onload = async () => {
      try {
        const dataUrl = fileReader.result as string;
        const base64Data = dataUrl.split(',')[1];
        const mimeType = file.type;

        let chunkDuration: number;
        if (chunkingMode === 'simple') {
            if (simpleChunkSize === 'short') {
                chunkDuration = duration < 60 ? 5 : duration < 180 ? 8 : 12;
            } else if (simpleChunkSize === 'long') {
                chunkDuration = duration < 60 ? 10 : duration < 180 ? 18 : 25;
            } else { // medium
                chunkDuration = duration < 60 ? 7 : duration < 180 ? 12 : 20;
            }
        } else { // detailed
            chunkDuration = detailedChunkValue;
        }

        const timeSegments = [];
        for (let i = 0; i < duration; i += chunkDuration) {
            const startTime = i;
            const endTime = Math.min(i + chunkDuration, duration);
            timeSegments.push({ startTime, endTime });
        }

        if (timeSegments.length === 0 && duration > 0) {
            timeSegments.push({ startTime: 0, endTime: duration });
        }

        const prompt = `오디오 파일을 분석하고 다음 시간 세그먼트 목록을 따르세요: ${JSON.stringify(timeSegments)}. 각 시간 세그먼트에 대해 오디오에서 일어나는 일을 설명하는 JSON 객체를 제공하세요. 각 객체는 다음을 포함해야 합니다:
- 'title': 장면에 대한 짧고 설명적인 한국어 제목.
- 'prompt': 이미지 생성 모델에 적합한, 장면의 핵심 행동, 캐릭터, 분위기를 포착하는 상세한 한국어 시각적 설명.
- 'startTime': 제공된 세그먼트의 시작 시간(초).
- 'endTime': 제공된 세그먼트의 종료 시간(초).
제공된 세그먼트 수와 정확히 일치하는 유효한 JSON 객체 배열로만 응답해 주세요.`;

        const response = await ai.models.generateContent({
          model: 'gemini-3-flash-preview',
          contents: {
            parts: [
              {text: prompt},
              {inlineData: {data: base64Data, mimeType: mimeType}},
            ],
          },
          config: {
            responseMimeType: 'application/json',
            responseSchema: {
              type: Type.ARRAY,
              items: {
                type: Type.OBJECT,
                properties: {
                  title: {type: Type.STRING},
                  prompt: {type: Type.STRING},
                  startTime: {type: Type.NUMBER},
                  endTime: {type: Type.NUMBER},
                },
                required: ['title', 'prompt', 'startTime', 'endTime'],
              },
            },
          },
        });

        const jsonStr = response.text;
        if (!jsonStr) throw new Error('모델이 장면을 생성하지 못했습니다.');

        const scenes: {
          title: string;
          prompt: string;
          startTime: number;
          endTime: number;
        }[] = JSON.parse(jsonStr);
        if (scenes.length === 0)
          throw new Error('오디오에서 장면을 추출할 수 없습니다.');

        const url = URL.createObjectURL(file);
        setAudioInfo({url, duration, name: file.name});
        setFrames(Array(scenes.length).fill(null));
        setSceneData(scenes.map((s) => ({title: s.title, prompt: s.prompt})));
        setFrameDurations(
          scenes.map((s) => Math.max(100, (s.endTime - s.startTime) * 1000)),
        ); // Ensure minimum duration
        setCurrentFrameIndex(0);
        setHistory({});
        setHistoryIndex({});
      } catch (err) {
        console.error('Error processing audio file:', err);
        setErrorMessage(
          parseError(err) || '오디오 파일을 처리하는 중 오류가 발생했습니다.',
        );
        setShowErrorModal(true);
        setAudioInfo(null);
      } finally {
        setIsProcessingAudio(false);
        setShowChunkSettingsModal(false);
        setAudioFileToProcess(null);
      }
    };
    fileReader.onerror = () => {
      setErrorMessage('파일을 읽는 데 실패했습니다.');
      setShowErrorModal(true);
      setIsProcessingAudio(false);
      setShowChunkSettingsModal(false);
      setAudioFileToProcess(null);
    };
    fileReader.readAsDataURL(file);
  }


  const handleAudioUpload = async (e: ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    try {
        const audioContext = new (window.AudioContext || (window as any).webkitAudioContext)();
        const arrayBuffer = await file.arrayBuffer();
        const audioBuffer = await audioContext.decodeAudioData(arrayBuffer);
        const duration = audioBuffer.duration;
        setAudioDuration(duration);
        setAudioFileToProcess(file);
        setChunkingSource('audio');
        setDetailedChunkType('time'); // Default for audio
        setDetailedChunkValue(10);
        setShowChunkSettingsModal(true);
    } catch (err) {
        console.error("Error decoding audio file:", err);
        setErrorMessage("유효하지 않은 오디오 파일입니다. 다른 파일을 시도해 주세요.");
        setShowErrorModal(true);
    }
    e.target.value = ''; // Reset file input
  };

  const handleStartGeneration = () => {
