        </div>

        {/* Right Controls Pane */}
        <aside className="flex-shrink-0 w-full md:w-[420px] flex flex-col gap-4 overflow-hidden">
            <div className="relative p-4 bg-white/60 rounded-lg shadow-sm">
                <div className="flex items-center justify-between">
                    <div>
                        <h1 className="text-xl font-bold">애니메이션 스튜디오</h1>
                        <p className="text-sm text-gray-500">Gemini 네이티브 이미지 생성</p>
