  };

  const canUndo = (historyIndex[currentFrameIndex] ?? 0) > 0;
  const canRedo =
    (historyIndex[currentFrameIndex] ?? -1) <
    (history[currentFrameIndex]?.length ?? 0) - 1;

  const currentCanvasDimensions = ASPECT_RATIOS[aspectRatio];

  const calculateExpectedFrames = () => {
    if (chunkingSource === 'script') {
        if (!scriptText) return 0;
        let chunkSize: number;
        if (chunkingMode === 'simple') {
            const len = scriptText.length;
            if (simpleChunkSize === 'short') chunkSize = len < 1500 ? 200 : len < 4000 ? 400 : 700;
            else if (simpleChunkSize === 'long') chunkSize = len < 1500 ? 400 : len < 4000 ? 700 : 1000;
            else chunkSize = len < 1500 ? 300 : len < 4000 ? 500 : 800;
        } else {
            chunkSize = detailedChunkValue > 0 ? detailedChunkValue : 1;
        }
        return Math.ceil(scriptText.length / chunkSize);
    }
    if (chunkingSource === 'audio') {
        if (!audioDuration) return 0;
        let chunkDuration: number;
        if (chunkingMode === 'simple') {
            if (simpleChunkSize === 'short') chunkDuration = audioDuration < 60 ? 5 : audioDuration < 180 ? 8 : 12;
            else if (simpleChunkSize === 'long') chunkDuration = audioDuration < 60 ? 10 : audioDuration < 180 ? 18 : 25;
            else chunkDuration = audioDuration < 60 ? 7 : audioDuration < 180 ? 12 : 20;
        } else {
            chunkDuration = detailedChunkValue > 0 ? detailedChunkValue : 1;
        }
        return Math.ceil(audioDuration / chunkDuration);
    }
    return 0;
  };

